    "Boredom": {
        "Default_Solution": "#include <iostream>\n#include <cstdio>\n#include <cstdlib>\n#include <algorithm>\n#include <cmath>\n#include <vector>\n#include <set>\n#include <map>\n#include <unordered_set>\n#include <unordered_map>\n#include <queue>\n#include <ctime>\n#include <cassert>\n#include <complex>\n#include <string>\n#include <cstring>\nusing namespace std;\n\n#ifdef LOCAL\n\t#define eprintf(...) fprintf(stderr, __VA_ARGS__)\n#else\n\t#define eprintf(...) 42\n#endif\n\ntypedef long long ll;\ntypedef pair<int, int> pii;\n#define mp make_pair\n\nconst int N = 200200;\nstruct Node {\n\tint L, R;\n\tint l, r;\n\tint val;\n\n\tNode() : L(-1), R(-1), l(-1), r(-1), val(0) {}\n\tNode(int _l, int _r) : L(-1), R(-1), l(_l), r(_r), val(0) {}\n};\nconst int S = (int)7e6;\nNode tree[S];\nint treeSz;\n\nint build(int l, int r) {\n\tint v = treeSz++;\n\ttree[v] = Node(l, r);\n\tif (l + 1 == r) return v;\n\tint mid = (l + r) / 2;\n\ttree[v].L = build(l, mid);\n\ttree[v].R = build(mid, r);\n\treturn v;\n}\n\nint setVal(int v, int p, int x) {\n\tif (p < tree[v].l || tree[v].r <= p) return v;\n\tint u = treeSz++;\n\ttree[u] = tree[v];\n\tif (tree[v].L == -1) {\n\t\ttree[u].val = x;\n\t\treturn u;\n\t}\n\ttree[u].L = setVal(tree[v].L, p, x);\n\ttree[u].R = setVal(tree[v].R, p, x);\n\ttree[u].val = tree[tree[u].L].val + tree[tree[u].R].val;\n\treturn u;\n}\n\nint getSum(int v, int l, int r) {\n\tif (l <= tree[v].l && tree[v].r <= r)\n\t\treturn tree[v].val;\n\tif (l >= tree[v].r || tree[v].l >= r)\n\t\treturn 0;\n\treturn getSum(tree[v].L, l, r) + getSum(tree[v].R, l, r);\n}\n\nint roots[N];\nint n, q;\n\nint main()\n{\n//\tfreopen(\"input.txt\", \"r\", stdin);\n//\tfreopen(\"output.txt\", \"w\", stdout);\n\n\tscanf(\"%d%d\", &n, &q);\n\troots[0] = build(0, n);\n\tfor (int i = 0; i < n; i++) {\n\t\tint p;\n\t\tscanf(\"%d\", &p);\n\t\tp--;\n\t\troots[i + 1] = setVal(roots[i], p, 1);\n\t}\n\twhile(q--) {\n\t\tint x1, x2, y1, y2;\n\t\tscanf(\"%d%d%d%d\", &x1, &y1, &x2, &y2);\n\t\tx1--;\n\t\ty1--;\n\t\tll ans = (ll)n * (n - 1);\n\t\tans -= (ll)x1 * (x1 - 1);\n\t\tans -= (ll)(n - x2) * (n - x2 - 1);\n\t\tans -= (ll)y1 * (y1 - 1);\n\t\tans -= (ll)(n - y2) * (n - y2 - 1);\n\t\tll cnt = getSum(roots[x1], 0, y1);\n\t\tans += cnt * (cnt - 1);\n\t\tcnt = getSum(roots[x1], y2, n);\n\t\tans += cnt * (cnt - 1);\n\t\tcnt = y1 - getSum(roots[x2], 0, y1);\n\t\tans += cnt * (cnt - 1);\n\t\tcnt = n - y2 - getSum(roots[x2], y2, n);\n\t\tans += cnt * (cnt - 1);\n\t\tprintf(\"%lld\n\", ans / 2);\n\t}\n\n\treturn 0;\n}\n"
    },
