        "Default_Solution": "/**\n *    author:  tourist\n *    created: 13.03.2021 12:04:29       \n**/\n#include <bits/stdc++.h>\n\nusing namespace std;\n\nint main() {\n  ios::sync_with_stdio(false);\n  cin.tie(0);\n  int n;\n  cin >> n;\n  vector<int> a(n);\n  for (int i = 0; i < n; i++) {\n    cin >> a[i];\n  }\n  int mx = *max_element(a.begin(), a.end()) + 1;\n  vector<int> p1(mx, -1);\n  vector<int> p2(mx, -1);\n  vector<int> p3(mx, -1);\n  for (int i = 0; i < n; i++) {\n    if (p1[a[i]] == -1) {\n      p1[a[i]] = i;\n      continue;\n    }\n    if (p2[a[i]] == -1) {\n      p2[a[i]] = i;\n      continue;\n    }\n    if (p3[a[i]] == -1) {\n      p3[a[i]] = i;\n      continue;\n    }\n    cout << \"YES\" << '\n';\n    cout << p1[a[i]] + 1 << \" \" << p2[a[i]] + 1 << \" \" << p3[a[i]] + 1 << \" \" << i + 1 << '\n';\n    return 0;\n  }\n  vector<int> ind;\n  int two = -1;\n  for (int i = 0; i < mx; i++) {\n    if (p1[i] == -1) {\n      continue;\n    }\n    ind.push_back(p1[i]);\n    if (p2[i] == -1) {\n      continue;\n    }\n    if (two != -1) {\n      cout << \"YES\" << '\n';\n      cout << p1[two] + 1 << \" \" << p1[i] + 1 << \" \" << p2[two] + 1 << \" \" << p2[i] + 1 << '\n';\n      return 0;\n    }\n    two = i;\n  }\n  vector<pair<int, int>> met(2 * mx, make_pair(-1, -1));\n  sort(ind.begin(), ind.end());\n  if (two != -1) {\n    met[two + two] = make_pair(p1[two], p2[two]);\n  }\n  for (int i = 0; i < (int) ind.size(); i++) {\n    for (int j = i + 1; j < (int) ind.size(); j++) {\n      int sum = a[ind[i]] + a[ind[j]];\n      if (met[sum].first != -1) {\n        cout << \"YES\" << '\n';\n        cout << met[sum].first + 1 << \" \" << met[sum].second + 1 << \" \" << ind[i] + 1 << \" \" << ind[j] + 1 << '\n';\n        return 0;\n      }\n      met[sum] = make_pair(ind[i], ind[j]);\n    }\n  }\n  cout << \"NO\" << '\n';\n  return 0;\n}\n"
