        "Default_Solution": "#pragma comment(linker, \"/STACK:65777216\")\n\n#include <algorithm>\n#include <iostream>\n#include <string>\n#include<sstream>\n#include<string.h>\n#include <cstdio>\n#include <vector>\n#include <bitset>\n#include <cmath>\n#include <queue>\n#include<stack>\n#include <set>\n#include <map>\n#include<ctime>\n\nusing namespace std;\n\ntypedef long long ll;\ntypedef vector<int> vi;\ntypedef pair<int,int> pii;\ntypedef pair<double,double> pdd;\ntypedef unsigned long long ull;\n\n#define FOR(i,a,b) for (int i(a); i < (b); i++) \n#define REP(i,n) FOR(i,0,n) \n#define SORT(v) sort((v).begin(),(v).end())\n#define UN(v) sort((v).begin(),(v).end()),v.erase(unique(v.begin(),v.end()),v.end())\n#define CL(a,b) memset(a,b,sizeof(a))\n#define pb push_back\n\nstring s;\nint a[33];\nint k;\nbool u[33];\n\nint main(){ \n#ifdef LocalHost\n\tfreopen(\"input.txt\",\"r\",stdin);\n//\tfreopen(\"output.txt\",\"w\",stdout);\n#endif\n\tgetline(cin,s);\n\tcin>>k;\n\tREP(i,s.size()) a[s[i]-'a']++;\n\n\tvector<pii> v;\n\tREP(i,26) v.pb(pii(a[i],i));\n\tSORT(v);\n\tint curr = 0;\n\twhile(v.size() && curr + v[0].first<=k){\n\t\tcurr += v[0].first;\n\t\tu[v[0].second] = true;\n\t\tv.erase(v.begin());\n\t}\n\tcout<<v.size()<<endl;\n\tstring t;\n\tREP(i,s.size()) if(!u[s[i]-'a']) t.pb(s[i]);\n\tprintf(\"%s\",t.c_str());\n\n#ifdef LocalHost\n\tcout<<endl<<endl<<\"TIME: \"<<clock()<<endl;\n#endif\n\treturn 0;\n}"
