        "Default_Solution": "#include <iostream>\n#include <cstdio>\n#include <cstdlib>\n#include <algorithm>\n#include <cmath>\n#include <vector>\n#include <set>\n#include <map>\n#include <unordered_set>\n#include <unordered_map>\n#include <queue>\n#include <ctime>\n#include <cassert>\n#include <complex>\n#include <string>\n#include <cstring>\n#include <chrono>\n#include <random>\n#include <bitset>\nusing namespace std;\n\n#ifdef LOCAL\n\t#define eprintf(...) fprintf(stderr, __VA_ARGS__);fflush(stderr);\n#else\n\t#define eprintf(...) 42\n#endif\n\nusing ll = long long;\nusing ld = long double;\nusing uint = unsigned int;\nusing ull = unsigned long long;\ntemplate<typename T>\nusing pair2 = pair<T, T>;\nusing pii = pair<int, int>;\nusing pli = pair<ll, int>;\nusing pll = pair<ll, ll>;\nmt19937_64 rng(chrono::steady_clock::now().time_since_epoch().count());\nll myRand(ll B) {\n\treturn (ull)rng() % B;\n}\n\n#define pb push_back\n#define mp make_pair\n#define all(x) (x).begin(),(x).end()\n#define fi first\n#define se second\n\nclock_t startTime;\ndouble getCurrentTime() {\n\treturn (double)(clock() - startTime) / CLOCKS_PER_SEC;\n}\n\nconst int N = 200200;\nint d[N];\nint ans[N][3];\n\n\nint main()\n{\n\tstartTime = clock();\n//\tfreopen(\"input.txt\", \"r\", stdin);\n//\tfreopen(\"output.txt\", \"w\", stdout);\n\n\tfor (int i = 2; i < N; i++) {\n\t\tif (d[i]) continue;\n\t\tfor (int j = i; j < N; j += i)\n\t\t\tif (d[j] == 0)\n\t\t\t\td[j] = i;\n\t}\n\tfor (int i = 0; i < N; i++)\n\t\tans[i][0] = ans[i][1] = 100;\n\tint n;\n\tscanf(\"%d\", &n);\n\tfor (int i = 0; i < n; i++) {\n\t\tint x;\n\t\tscanf(\"%d\", &x);\n\t\twhile(x > 1) {\n\t\t\tint p = d[x];\n\t\t\tint t = 0;\n\t\t\twhile(x % p == 0) {\n\t\t\t\tx /= p;\n\t\t\t\tt++;\n\t\t\t}\n\t\t\tfor (int j = 0; j < 2; j++) {\n\t\t\t\tif (t < ans[p][j])\n\t\t\t\t\tswap(t, ans[p][j]);\n\t\t\t}\n\t\t\tans[p][2]++;\n\t\t}\n\t}\n\tll res = 1;\n\tfor (int p = 2; p < N; p++) {\n\t\tif (ans[p][2] <= n - 2) continue;\n\t\tint t = 0;\n\t\tif (ans[p][2] == n - 1)\n\t\t\tt = ans[p][0];\n\t\telse\n\t\t\tt = ans[p][1];\n\t\twhile(t--) res *= p;\n\t}\n\tprintf(\"%lld\n\", res);\n\n\treturn 0;\n}\n"
