        "Default_Solution": "#include<cstdio>\n#include<algorithm>\nusing namespace std;\n\nint T,n,m;\nint arr[100000];\nint p1[100000];\nint p2[100000];\nint deg[100000];\n\nint main(void)\n{\n\tscanf(\"%d\",&T);\n\twhile(T--){\n\t\tscanf(\"%d%d\",&n,&m);\n\t\tfor(int i=0;i<n;i++){\n\t\t\tscanf(\"%d\",&arr[i]);\n\t\t\tdeg[i]=0;\n\t\t}\n\t\tfor(int i=0;i<m;i++){\n\t\t\tscanf(\"%d%d\",&p1[i],&p2[i]);\n\t\t\tp1[i]--; p2[i]--;\n\t\t\tdeg[p1[i]]++; deg[p2[i]]++;\n\t\t}\n\t\tint ans=114514;\n\t\tif(m%2==0) ans=0;\n\t\tfor(int i=0;i<n;i++)\n\t\t\tif((m-deg[i])%2==0)\n\t\t\t\tans=min(ans,arr[i]);\n\t\tfor(int i=0;i<m;i++)\n\t\t\tif((m-deg[p1[i]]-deg[p2[i]]+1)%2==0)\n\t\t\t\tans=min(ans,arr[p1[i]]+arr[p2[i]]);\n\t\tprintf(\"%d\n\",ans);\n\t}\n\treturn 0;\n}"
