        "Default_Solution": "#include <stdio.h>\n#include <bits/stdc++.h>\n\nusing namespace std;\n\nconst int MAXN = 100005;\n\nint T,n,m,ans;\nint fa[MAXN];\n\nint getroot(int u)\n{\n\treturn u == fa[u] ? u : fa[u] = getroot(fa[u]);\n}\n\nint main()\n{\n\tscanf(\"%d\",&T);\n\twhile (T--)\n\t{\n\t\tscanf(\"%d%d\",&n,&m);\n\t\tfor (int i = 1;i <= n;i++)\n\t\t\tfa[i] = i;\n\t\tans = m;\n\t\tfor (int u,v,i = 1;i <= m;i++)\n\t\t{\n\t\t\tscanf(\"%d%d\",&u,&v);\n\t\t\tif (u == v)\n\t\t\t{\n\t\t\t\tans--;\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tint ru = getroot(u),rv = getroot(v);\n\t\t\tif (ru == rv)\n\t\t\t\tans++;\n\t\t\telse\n\t\t\t\tfa[ru] = rv;\n\t\t}\n\t\tprintf(\"%d\n\",ans);\n\t}\n\treturn 0;\n}"
