        "Default_Solution": "/**\n *    author:  tourist\n *    created: 24.07.2020 17:34:32       \n**/\n#include <bits/stdc++.h>\n\nusing namespace std;\n\nclass dsu {\n public:\n  vector<int> p;\n  int n;\n\n  dsu(int _n) : n(_n) {\n    p.resize(n);\n    iota(p.begin(), p.end(), 0);\n  }\n\n  inline int get(int x) {\n    return (x == p[x] ? x : (p[x] = get(p[x])));\n  }\n\n  inline bool unite(int x, int y) {\n    x = get(x);\n    y = get(y);\n    if (x != y) {\n      p[x] = y;\n      return true;\n    }\n    return false;\n  }\n};\n\nint main() {\n  ios::sync_with_stdio(false);\n  cin.tie(0);\n  int tt;\n  cin >> tt;\n  while (tt--) {\n    int n;\n    cin >> n;\n    string a, b;\n    cin >> a >> b;\n    dsu d(26);\n    int ans = 0;\n    for (int i = 0; i < n; i++) {\n      if (a[i] > b[i]) {\n        ans = -1;\n        break;\n      }\n      if (d.unite((int) (a[i] - 'a'), (int) (b[i] - 'a'))) {\n        ++ans;\n      }\n    }\n    cout << ans << '\n';\n  }\n  return 0;\n}\n"
