        "Default_Solution": "#include <bits/stdc++.h>\nusing namespace std;\n\nint main(){\n\tios_base::sync_with_stdio(false), cin.tie(nullptr);\n\tint n;\n\tcin >> n;\n\tset<pair<int,int>> odd, even;\n\tfor(int i = 0; i < n; i++){\n\t\tfor(int j = 0; j < n; j++){\n\t\t\tif((i + j) & 1){\n\t\t\t\todd.insert({i, j});\n\t\t\t} else {\n\t\t\t\teven.insert({i, j});\n\t\t\t}\n\t\t}\n\t}\n\tfor(int t = 0; t < n*n; t++){\n\t\tint a;\n\t\tcin >> a;\n\t\tif(odd.size() && even.size()){\n\t\t\tint c = (a == 1) ? 2 : 1;\n\t\t\tset<pair<int,int>>& x = (c == 1) ? odd : even;\n\t\t\tpair<int,int> f = *x.begin();\n\t\t\tx.erase(f);\n\t\t\tcout << c << ' ' << (f.first + 1) << ' ' << (f.second + 1) << '\n';\n\t\t\tcout << flush;\n\t\t} else {\n\t\t\tset<pair<int,int>>& x = even.empty() ? odd : even;\n\t\t\tint wh = even.empty() ? 1 : 2;\n\t\t\tpair<int,int> f = *x.begin();\n\t\t\tx.erase(f);\n\t\t\tint c = (a == 3) ? (wh) : 3;\n\t\t\tcout << c << ' ' << (f.first + 1) << ' ' << (f.second + 1) << '\n';\n\t\t\tcout << flush;\n\t\t}\n\t}\n}"
