        "Default_Solution": "#pragma GCC optimize(\"Ofast\",\"unroll-loops\",\"omit-frame-pointer\",\"inline\")//Optimization flags\n#pragma GCC option(\"arch=native\",\"tune=native\",\"no-zero-upper\")//Enable AVX\n#pragma GCC target(\"sse,sse2,sse3,ssse3,sse4,popcnt,abm,mmx,avx,avx2\")\n#include<bits/stdc++.h>\n//#include<ext/pb_ds/assoc_container.hpp>\nusing namespace std;\n//using namespace __gnu_pbds;\nconst int inf=0x3f3f3f3f;\nconst double eps=1e-6;\nconst int mod=1e9+7;\ntypedef long long ll;\n#ifndef LOCAL\n#define cerr if(0)cout\n#define eprintf(...)0\n#else\n#define eprintf(...)fprintf(stderr,__VA_ARGS__)\n#endif\ninline string getstr(string&s,int l,int r){string ret=\"\";for(int i=l;i<=r;i++)ret.push_back(s[i]);return ret;}\nint modpow(int x,int y,int md=mod){int ret=1;do{if(y&1)ret=(ll)ret*x%md;x=(ll)x*x%md;}while(y>>=1);return ret;}\ninline int Rand(){return rand()*32768+rand();}\nint n,k,p[5555],dp[2][22][555],la,nw,suf[5005][5005],pos[5005],cc,cur;\nint in[22],cnt,nmsk,nj,np;\nvoid upd(int&x,int y){\n\tif(x > y)x=y;\n}\nint main(){\n\tscanf(\"%d%d\",&n,&k);\n\tfor(int i=1; i<=n; i++)scanf(\"%d\",&p[i]);\n\tnw=1;\n\tfor(int i=0; i<2; i++){\n\t\tfor(int j=0; j<=2*k+2; j++){\n\t\t\tfor(int h=0; h<(1<<k); h++)\n\t\t\t\t\t\tdp[i][j][h]=inf;\n\t\t}\n\t}\n\tfor(int i=1; i<=n; i++)pos[p[i]]=i;\n\tfor(int i=1; i<=n; i++){\n\t\tfor(int j=1; j<=n; j++)suf[i][j]=suf[i-1][j];\n\t\tfor(int j=1; j<=pos[i]; j++)suf[i][j]++;\n\t}\n\tdp[0][k+2][0]=0;\n\tfor(int i=1; i<=n; i++){\n\t\tfor(int j=0; j<=2*k+2; j++){\n\t\t\tfor(int h=0; h<(1<<k); h++)\n\t\t\t\t\t\tdp[nw][j][h]=inf;\n\t\t}\n\t\tfor(int j=0; j<=2*k+2; j++){\n\t\t\tfor(int h=0; h<(1<<k); h++){\n\t\t\t\tif(dp[la][j][h] > 1e8)continue;\n\t\t\t\tcc=i+j-k-2;\n\t\t\t\tcnt=0;\n\t\t\t\tfor(int p=0; p<8; p++){\n\t\t\t\t\tif(h&(1<<p))in[++cnt]=pos[cc+p+1];\n\t\t\t\t}\n\t\t\t\tfor(int p=0; p<8&& cc+p+1<=n; p++){\n\t\t\t\t\tif(h&(1<<p))continue;\n\t\t\t\t\tcur=suf[cc-1][pos[cc+p+1]];\n\t\t\t\t\tfor(int t=1; t<=cnt; t++)cur+=(pos[cc+p+1]<in[t]);\n\t\t\t\t\tif(j)upd(dp[nw][j-1][h |(1<<p)],dp[la][j][h]+cur);\n\t\t\t\t}\n\t\t\t\tcur=suf[cc-1][pos[cc]];\n\t\t\t\tfor(int t=1; t<=cnt;t++)cur+=(pos[cc]<in[t]);\n\t\t\t\tif(h==(1<<k)-1)np=k;else np=__builtin_ctz(~h);\n\t\t\t\tnj=j+np;\n\t\t\t\tif(nj<=(k<<1)+2){\n\t\t\t\t\tupd(dp[nw][nj][h >>(np+1)],dp[la][j][h]+cur);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tla^=1;\n\t\tnw^=1;\n\t}\n\tprintf(\"%d\n\",dp[la][k+2][0]);\n\treturn 0;\n}"
