    "Glass Half Spilled": {
        "Default_Solution": "/**\n *    author:  tourist\n *    created: 19.12.2020 12:42:11       \n**/\n#include <bits/stdc++.h>\n\nusing namespace std;\n\nint main() {\n  ios::sync_with_stdio(false);\n  cin.tie(0);\n  int n;\n  cin >> n;\n  vector<int> a(n), b(n);\n  for (int i = 0; i < n; i++) {\n    cin >> a[i] >> b[i];\n    a[i] -= b[i];\n  }\n  int total = accumulate(b.begin(), b.end(), 0);\n  vector<vector<int>> dp(n + 1, vector<int>(total + 1, -1));\n  dp[0][0] = 0;\n  for (int i = 0; i < n; i++) {\n    for (int j = i; j >= 0; j--) {\n      for (int s = 0; s <= total; s++) {\n        if (dp[j][s] != -1) {\n          int ns = min(s + 2 * a[i] + b[i], total);\n          dp[j + 1][ns] = max(dp[j + 1][ns], dp[j][s] + b[i]);\n        }\n      }\n    }\n  }\n  for (int j = 1; j <= n; j++) {\n    int ans = 0;\n    for (int s = 0; s <= total; s++) {\n      if (dp[j][s] != -1) {\n        ans = max(ans, dp[j][s] + s);\n      }\n    }\n    cout << fixed << setprecision(1) << 0.5 * ans << '\n';\n  }\n  return 0;\n}\n"
    },
    "Graph Subset Problem": {
        "Default_Solution": "#include <bits/extc++.h>\n\nstruct splitmix64_hash {\n\tstatic uint64_t splitmix64(uint64_t x) {\n\t\t// http://xorshift.di.unimi.it/splitmix64.c\n\t\tx += 0x9e3779b97f4a7c15;\n\t\tx = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9;\n\t\tx = (x ^ (x >> 27)) * 0x94d049bb133111eb;\n\t\treturn x ^ (x >> 31);\n\t}\n\n\tsize_t operator()(uint64_t x) const {\n\t\tstatic const uint64_t FIXED_RANDOM = std::chrono::steady_clock::now().time_since_epoch().count();\n\t\treturn splitmix64(x + FIXED_RANDOM);\n\t}\n};\n\ntemplate <typename K, typename V, typename Hash = splitmix64_hash>\nusing hash_map = __gnu_pbds::gp_hash_table<K, V, Hash>;\n\ntemplate <typename K, typename Hash = splitmix64_hash>\nusing hash_set = hash_map<K, __gnu_pbds::null_type, Hash>;\n\nint main() {\n\tusing namespace std;\n\tios_base::sync_with_stdio(false), cin.tie(nullptr);\n\n\tint T; cin >> T;\n\twhile (T--) {\n\t\t[]() {\n\t\t\tint N, M, K; cin >> N >> M >> K;\n\t\t\tvector<hash_set<int>> adj(N);\n\t\t\tfor (int e = 0; e < M; e++) {\n\t\t\t\tint u, v; cin >> u >> v; u--, v--;\n\t\t\t\tadj[u].insert(v);\n\t\t\t\tadj[v].insert(u);\n\t\t\t}\n\t\t\tvector<int> deg(N);\n\t\t\tfor (int i = 0; i < N; i++) deg[i] = int(adj[i].size());\n\n\t\t\tvector<bool> alive(N, true);\n\t\t\tvector<int> q; q.reserve(N);\n\t\t\tfor (int i = 0; i < N; i++) {\n\t\t\t\tif (deg[i] < K - 1) q.push_back(i);\n\t\t\t}\n\t\t\tfor (int z = 0; z < int(q.size()); z++) {\n\t\t\t\tint cur = q[z];\n\t\t\t\talive[cur] = false;\n\t\t\t\tfor (int nxt : adj[cur]) {\n\t\t\t\t\tif (deg[nxt] == K-1) q.push_back(nxt);\n\t\t\t\t\t--deg[nxt];\n\t\t\t\t}\n\t\t\t}\n\n\t\t\tq.clear();\n\n\t\t\tfor (int i = 0; i < N; i++) {\n\t\t\t\tif (!alive[i]) continue;\n\t\t\t\tif (deg[i] == K-1) q.push_back(i);\n\t\t\t}\n\n\t\t\tvector<int> cur_verts; cur_verts.reserve(K);\n\t\t\tfor (int z = 0; z < int(q.size()); z++) {\n\t\t\t\tint cur = q[z];\n\t\t\t\tassert(deg[cur] <= K-1);\n\t\t\t\talive[cur] = false;\n\t\t\t\tfor (int nxt : adj[cur]) {\n\t\t\t\t\tif (deg[nxt] == K) q.push_back(nxt);\n\t\t\t\t\t--deg[nxt];\n\t\t\t\t}\n\n\t\t\t\tif (deg[cur] < K-1) continue;\n\t\t\t\tassert(deg[cur] == K-1);\n\n\t\t\t\tcur_verts.clear();\n\t\t\t\tcur_verts.push_back(cur);\n\t\t\t\tfor (int nxt : adj[cur]) {\n\t\t\t\t\tif (alive[nxt]) {\n\t\t\t\t\t\tif (deg[nxt] < K-2) goto bad;\n\t\t\t\t\t\tcur_verts.push_back(nxt);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tassert(int(cur_verts.size()) == K);\n\t\t\t\tfor (int i = 1; i < K; i++) {\n\t\t\t\t\tint a = cur_verts[i];\n\t\t\t\t\tconst auto& mp = adj[a];\n\t\t\t\t\tfor (int j = i+1; j < K; j++) {\n\t\t\t\t\t\tif (mp.find(cur_verts[j]) == mp.end()) {\n\t\t\t\t\t\t\tgoto bad;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\t{\n\t\t\t\t\tcout << 2 << '\n';\n\t\t\t\t\tfor (int i = 0; i < K; i++) {\n\t\t\t\t\t\tcout << cur_verts[i]+1 << \" \n\"[i+1==K];\n\t\t\t\t\t}\n\t\t\t\t\treturn;\n\t\t\t\t}\nbad:\n\t\t\t\tcontinue;\n\t\t\t}\n\n\t\t\tvector<int> still_alive; still_alive.reserve(N);\n\t\t\tfor (int i = 0; i < N; i++) {\n\t\t\t\tif (alive[i]) still_alive.push_back(i);\n\t\t\t}\n\t\t\tif (!still_alive.empty()) {\n\t\t\t\tcout << 1 << ' ' << still_alive.size() << '\n';\n\t\t\t\tfor (int z = 0; z < int(still_alive.size()); z++) {\n\t\t\t\t\tcout << still_alive[z]+1 << \" \n\"[z+1==int(still_alive.size())];\n\t\t\t\t}\n\t\t\t\treturn;\n\t\t\t}\n\t\t\tcout << -1 << '\n';\n\t\t}();\n\t}\n\n\treturn 0;\n}\n"
    },
    "Grime Zoo": {
        "Default_Solution": "#include <stdio.h>\n#include <bits/stdc++.h>\n\nusing namespace std;\n\ntypedef long long ll;\n\nconst int MAXN = 100005;\n\nint n;\n\nll x,y,ans;\nll f[MAXN];\nll g[MAXN];\nll pre[MAXN];\nll suf[MAXN];\n\nchar s[MAXN];\n\nint main()\n{\n\tans = 1e18;\n\tscanf(\"%s%lld%lld\",s + 1,&x,&y);\n\tn = strlen(s + 1);\n\tf[0] = 0;\n\tfor (int i = 1;i <= n;i++)\n\t{\n\t\tchar cur = (s[i] != '1' ? '0' : '1');\n\t\tpre[i] = pre[i - 1] + (cur == '0');\n\t\tf[i] = f[i - 1] + (cur == '0' ? y * (i - 1 - pre[i - 1]) : x * pre[i - 1]);\n\t}\n\tfor (int i = n;i >= 1;i--)\n\t{\n\t\tchar cur = (s[i] != '0' ? '1' : '0');\n\t\tsuf[i] = suf[i + 1] + (cur == '1');\n\t\tg[i] = g[i + 1] + (cur == '1' ? y * (n - i - suf[i + 1]) : x * suf[i + 1]);\n\t}\n\tfor (int i = 0;i <= n;i++)\n\t\tans = min(ans,f[i] + g[i + 1] + x * pre[i] * suf[i + 1] + y * (i - pre[i]) * (n - i - suf[i + 1]));\n\t\t\n\tf[0] = 0;\n\tfor (int i = 1;i <= n;i++)\n\t{\n\t\tchar cur = (s[i] != '0' ? '1' : '0');\n\t\tpre[i] = pre[i - 1] + (cur == '0');\n\t\tf[i] = f[i - 1] + (cur == '0' ? y * (i - 1 - pre[i - 1]) : x * pre[i - 1]);\n\t}\n\tfor (int i = n;i >= 1;i--)\n\t{\n\t\tchar cur = (s[i] != '1' ? '0' : '1');\n\t\tsuf[i] = suf[i + 1] + (cur == '1');\n\t\tg[i] = g[i + 1] + (cur == '1' ? y * (n - i - suf[i + 1]) : x * suf[i + 1]);\n\t}\n\tfor (int i = 0;i <= n;i++)\n\t\tans = min(ans,f[i] + g[i + 1] + x * pre[i] * suf[i + 1] + y * (i - pre[i]) * (n - i - suf[i + 1]));\n\t\t\n\tprintf(\"%lld\n\",ans);\n\treturn 0;\n}"
    },
