        "Default_Solution": "#include <cstdio>\n#include <algorithm>\n#include <vector>\n#include <set>\n#include <map>\n#include <queue>\n#include <string>\n#include <cmath>\n#include <cstring>\nusing namespace std;\n#define MOD 1000000009\n#define ADD(X, Y) ((X) = ((X) + (Y)) % MOD)\n\ntypedef long long i64;\n\nint N, M, K;\nvector<int> to[100000], dist[100000];\nbool vis[100000];\n\nint main()\n{\n\tscanf(\"%d%d%d\", &N, &M, &K);\n\n\tfor (int i = 0; i < M; i++) {\n\t\tint u, v, x;\n\t\tscanf(\"%d%d%d\", &u, &v, &x);\n\n\t\t--u; --v;\n\n\t\tto[u].push_back(v);\n\t\tdist[u].push_back(x);\n\t\tto[v].push_back(u);\n\t\tdist[v].push_back(x);\n\t}\n\n\tfor (int i = 0; i < N; i++) vis[i] = false;\n\n\tpriority_queue<pair<i64, int> > Q;\n\tQ.push(make_pair((i64)0, 0));\n\t\n\tfor (int i = 0; i < K; i++) {\n\t\tint s, y;\n\t\tscanf(\"%d%d\", &s, &y);\n\n\t\t--s;\n\n\t\tQ.push(make_pair(-(i64)y, s - N));\n\t}\n\n\tint ret = 0;\n\n\twhile(!Q.empty()) {\n\t\tpair<i64, int> tmp = Q.top(); Q.pop();\n\n\t\tif (tmp.second < 0) {\n\t\t\ttmp.second += N;\n\n\t\t\tif(vis[tmp.second]) ++ret;\n\t\t}\n\n\t\tif(vis[tmp.second]) continue;\n\t\tvis[tmp.second] = true;\n\n\t\tint p = tmp.second;\n\n\t\tfor(int i=0;i<to[p].size();i++) Q.push(make_pair(tmp.first - dist[p][i], to[p][i]));\n\t}\n\n\tprintf(\"%d\n\", ret);\n\treturn 0;\n}\n"
