    "Little Elephant and Array": {
        "Default_Solution": "// @author peter50216\n// #includes {{{\n#include<stdio.h>\n#include<stdlib.h>\n#include<string.h>\n#include<math.h>\n#include<assert.h>\n#include<stdarg.h>\n#include<time.h>\n#include<limits.h>\n#include<ctype.h>\n#include<string>\n#include<map>\n#include<set>\n#include<queue>\n#include<algorithm>\n#include<vector>\nusing namespace std;\n// }}}\n\nint in[101000];\nint l[101000],r[101000];\nint cnt[101000];\nvector<int> qs[1010];\nint ans[101000];\ninline bool cmp(int a,int b){return r[a]<r[b];}\nint qq;\nint n;\ninline void add(int x){\n    if(x>n)return;\n    if(cnt[x]==x)qq--;\n    cnt[x]++;\n    if(cnt[x]==x)qq++;\n}\ninline void del(int x){\n    if(x>n)return;\n    if(cnt[x]==x)qq--;\n    cnt[x]--;\n    if(cnt[x]==x)qq++;\n}\nint main(){\n    int m,i,j,k;\n    scanf(\"%d%d\",&n,&m);\n    for(i=0;i<n;i++)scanf(\"%d\",&in[i]);\n    int sn=(int)(sqrt(n)+1);\n    for(i=0;i<m;i++){\n        scanf(\"%d%d\",&l[i],&r[i]);\n        l[i]--;r[i]--;\n        qs[l[i]/sn].push_back(i);\n    }\n    for(i=0;i<=n/sn;i++){\n        if(qs[i].size()==0)continue;\n        sort(qs[i].begin(),qs[i].end(),cmp);\n        memset(cnt,0,sizeof(cnt));\n        qq=0;\n        int ll=l[qs[i][0]],rr=r[qs[i][0]];\n        for(j=ll;j<=rr;j++)add(in[j]);\n        ans[qs[i][0]]=qq;\n        for(j=1;j<qs[i].size();j++){\n            int ii=qs[i][j];\n            int lll=l[ii],rrr=r[ii];\n            for(k=rr+1;k<=rrr;k++)add(in[k]);\n            if(lll<ll){\n                for(k=ll-1;k>=lll;k--)add(in[k]);\n            }else if(lll>ll){\n                for(k=ll;k<lll;k++)del(in[k]);\n            }\n            ll=lll;rr=rrr;\n            ans[ii]=qq;\n        }\n    }\n    for(i=0;i<m;i++)printf(\"%d\n\",ans[i]);\n}\n// vim: fdm=marker:commentstring=\\ \\\"\\ %s:nowrap:autoread\n\n"
    },
