    "Mike and Feet": {
        "Default_Solution": "#include <bits/stdc++.h>\n#define SZ(X) ((int)(X).size())\n#define ALL(X) (X).begin(), (X).end()\n#define REP(I, N) for (int I = 0; I < (N); ++I)\n#define REPP(I, A, B) for (int I = (A); I < (B); ++I)\n#define RI(X) scanf(\"%d\", &(X))\n#define RII(X, Y) scanf(\"%d%d\", &(X), &(Y))\n#define RIII(X, Y, Z) scanf(\"%d%d%d\", &(X), &(Y), &(Z))\n#define DRI(X) int (X); scanf(\"%d\", &X)\n#define DRII(X, Y) int X, Y; scanf(\"%d%d\", &X, &Y)\n#define DRIII(X, Y, Z) int X, Y, Z; scanf(\"%d%d%d\", &X, &Y, &Z)\n#define RS(X) scanf(\"%s\", (X))\n#define CASET int ___T, case_n = 1; scanf(\"%d \", &___T); while (___T-- > 0)\n#define MP make_pair\n#define PB push_back\n#define MS0(X) memset((X), 0, sizeof((X)))\n#define MS1(X) memset((X), -1, sizeof((X)))\n#define LEN(X) strlen(X)\n#define PII pair<int,int>\n#define VPII vector<pair<int,int> >\n#define PLL pair<long long,long long>\n#define F first\n#define S second\ntypedef long long LL;\nusing namespace std;\nconst int MOD = 1e9+7;\nconst int SIZE = 1e6+10;\n// template end here\nint a[SIZE];\nVPII pp;\nstruct Union_Find{\n    int d[SIZE],num[SIZE];\n    void init(int n){\n        REP(i,n)d[i]=i,num[i]=1;\n    }\n    int find(int x){\n        return (x!=d[x])?(d[x]=find(d[x])):x;\n    }\n    bool uu(int x,int y){\n        x=find(x);\n        y=find(y);\n        if(x==y)return 0;\n        if(num[x]<=num[y]){\n            num[y]+=num[x];\n            d[x]=y;\n        }\n        else{\n            num[x]+=num[y];\n            d[y]=x;\n        }\n        return 1;\n    }\n}U;\ntemplate <class T>\nvoid maa(T& x,T y){\n    if(x<y)x=y;\n}\ntemplate <class T>\nvoid mii(T& x,T y){\n    if(x>y)x=y;\n}\nint an[SIZE];\nbool v[SIZE];\nvoid print_array(int arr[],int n){\n    REP(i,n){\n        if(i)printf(\" \");\n        printf(\"%d\",arr[i]);\n    }\n    puts(\"\");\n}\nint main(){\n    DRI(n);\n\n    REP(i,n){\n        RI(a[i]);\n        pp.PB(MP(a[i],i));\n    }\n    sort(ALL(pp));\n    reverse(ALL(pp));\n    U.init(n);\n    REP(i,n){\n        int me=pp[i].S;\n        if(me&&v[me-1]){\n            U.uu(me,me-1);\n        }\n        if(me+1<n&&v[me+1]){\n            U.uu(me,me+1);\n        }\n        v[me]=1;\n        maa(an[U.num[U.find(me)]],pp[i].F);\n    }\n    for(int i=n-1;i>0;i--)maa(an[i],an[i+1]);\n    print_array(an+1,n);\n    return 0;\n}\n"
    },
    "Minimum Path": {
        "Default_Solution": "#include <bits/stdc++.h>\nusing i64 = long long;\nusing u64 = unsigned long long;\nusing u32 = unsigned;\nconstexpr i64 inf = 1e18;\nint main() {\n    std::ios::sync_with_stdio(false);\n    std::cin.tie(nullptr);\n    int n, m;\n    std::cin >> n >> m;\n    std::vector<std::vector<std::pair<int, int>>> e(n);\n    for (int i = 0; i < m; i++) {\n        int u, v, w;\n        std::cin >> u >> v >> w;\n        u--;\n        v--;\n        e[u].emplace_back(v, w);\n        e[v].emplace_back(u, w);\n    }\n    std::vector<i64> dis(4 * n, inf);\n    std::priority_queue<std::pair<i64, int>> h;\n    dis[0] = 0;\n    h.emplace(0, 0);\n    while (!h.empty()) {\n        i64 d = -h.top().first;\n        int x = h.top().second;\n        h.pop();\n        if (d > dis[x]) {\n            continue;\n        }\n        int u = x / 4;\n        int p = x / 2 % 2;\n        int q = x % 2;\n        for (auto [v, w] : e[u]) {\n            int y = v * 4 + p * 2 + q;\n            if (dis[y] > dis[x] + w) {\n                dis[y] = dis[x] + w;\n                h.emplace(-dis[y], y);\n            }\n            if (p == 0 && dis[y + 2] > dis[x]) {\n                dis[y + 2] = dis[x];\n                h.emplace(-dis[y + 2], y + 2);\n            }\n            if (q == 0 && dis[y + 1] > dis[x] + 2 * w) {\n                dis[y + 1] = dis[x] + 2 * w;\n                h.emplace(-dis[y + 1], y + 1);\n            }\n        }\n    }\n    for (int i = 1; i < n; i++) {\n        std::cout << std::min(dis[i * 4], dis[i * 4 + 3]) << \" \n\"[i == n - 1];\n    }\n    return 0;\n}"
    },
