        "Default_Solution": "#include <iostream>\n#include <cstdio>\n#include <cstdlib>\n#include <algorithm>\n#include <cmath>\n#include <vector>\n#include <set>\n#include <map>\n#include <unordered_set>\n#include <unordered_map>\n#include <queue>\n#include <ctime>\n#include <cassert>\n#include <complex>\n#include <string>\n#include <cstring>\n#include <chrono>\n#include <random>\n#include <bitset>\nusing namespace std;\n\n#ifdef LOCAL\n\t#define eprintf(...) fprintf(stderr, __VA_ARGS__);fflush(stderr);\n#else\n\t#define eprintf(...) 42\n#endif\n\nusing ll = long long;\nusing ld = long double;\nusing uint = unsigned int;\nusing ull = unsigned long long;\ntemplate<typename T>\nusing pair2 = pair<T, T>;\nusing pii = pair<int, int>;\nusing pli = pair<ll, int>;\nusing pll = pair<ll, ll>;\nmt19937_64 rng(chrono::steady_clock::now().time_since_epoch().count());\nll myRand(ll B) {\n\treturn (ull)rng() % B;\n}\n\n#define pb push_back\n#define mp make_pair\n#define all(x) (x).begin(),(x).end()\n#define fi first\n#define se second\n\nclock_t startTime;\ndouble getCurrentTime() {\n\treturn (double)(clock() - startTime) / CLOCKS_PER_SEC;\n}\n\nconst int N = 100100;\nint n, k;\nint a[N];\n\nint sgn(int x) {\n\tif (x > 0) return 1;\n\tif (x == 0) return 0;\n\treturn -1;\n}\n\nbool solve() {\n\tscanf(\"%d%d\", &n, &k);\n\tbool hv = false;\n\tbool bad = false;\n\tfor (int i = 0; i < n; i++) {\n\t\tint x;\n\t\tscanf(\"%d\", &x);\n\t\tx -= k;\n\t\thv |= (x == 0);\n\t\tx = sgn(x);\n\t\tbad |= x == -1;\n\t\tif (x == 0) x = 1;\n\t\ta[i + 1] = x;\n\t}\n\tif (!hv) return false;\n\tif (!bad) return true;\n\ta[0] = 0;\n\tfor (int i = 0; i < n; i++)\n\t\ta[i + 1] += a[i];\n\tint minBal = n + 3;\n\tfor (int i = 3; i <= n; i++) {\n\t\tminBal = min(minBal, a[i - 3]);\n\t\tif (a[i] > minBal)\n\t\t\treturn true;\n\t}\n\treturn false;\n}\n\nint main()\n{\n\tstartTime = clock();\n//\tfreopen(\"input.txt\", \"r\", stdin);\n//\tfreopen(\"output.txt\", \"w\", stdout);\n\n\tint t;\n\tscanf(\"%d\", &t);\n\twhile(t--)\n\t\tif (solve())\n\t\t\tprintf(\"yes\n\");\n\t\telse\n\t\t\tprintf(\"no\n\");\n\n\treturn 0;\n}\n"
