        "Default_Solution": "/**\n *    author:  tourist\n *    created: 22.01.2022 17:44:36       \n**/\n#include <bits/stdc++.h>\n\nusing namespace std;\n\n#ifdef LOCAL\n#include \"algo/debug.h\"\n#else\n#define debug(...) 42\n#endif\n\nint main() {\n  ios::sync_with_stdio(false);\n  cin.tie(0);\n  int tt;\n  cin >> tt;\n  while (tt--) {\n    int n;\n    cin >> n;\n    vector<string> s(n);\n    for (int i = 0; i < n; i++) {\n      cin >> s[i];\n    }\n    bool ok = false;\n    for (int i = 0; i < n; i++) {\n      if (s[i] == string(s[i].rbegin(), s[i].rend())) {\n        ok = true;\n        break;\n      }\n    }\n    if (ok) {\n      cout << \"YES\" << '\n';\n      continue;\n    }\n    set<string> p;\n    for (int i = 0; i < n; i++) {\n      string x(s[i].rbegin(), s[i].rend());\n      string y(s[i].rbegin(), prev(s[i].rend()));\n      if (p.find(x) != p.end() || p.find(y) != p.end()) {\n        ok = true;\n        break;\n      }\n      p.insert(s[i]);\n    }\n    if (!ok) {\n      p.clear();\n      for (int i = n - 1; i >= 0; i--) {\n        string x(next(s[i].rbegin()), s[i].rend());\n        if (p.find(x) != p.end()) {\n          ok = true;\n          break;\n        }\n        p.insert(s[i]);\n      }\n    }\n    cout << (ok ? \"YES\" : \"NO\") << '\n';\n  }\n  return 0;\n}\n"
