        "Default_Solution": "#include<bits/stdc++.h>\n#define ll long long\n#define pb push_back\n#define fir first\n#define sec second\n#define ld long double\n//#define ll __int128\nusing namespace std;\nconst int N=600010;\ntypedef pair <int,int> P;\nstruct node {\n\tint t,b;\n}a[N];\npriority_queue <int,vector<int>,greater<int> > q;\nint read()\n{\n\tint x=0;char c=getchar(),flag='+';\n\twhile(!isdigit(c)) flag=c,c=getchar();\n\twhile(isdigit(c)) x=x*10+c-'0',c=getchar();\n\treturn flag=='-'?-x:x;\n}\nbool cmp(node a,node b) {return a.b>b.b;}\nvoid print(ll x)\n{\n\tif(x/10) print(x/10);\n\tprintf(\"%d\",(int)x%10);\n}\nint main()\n{\n\tint n=read(),k=read();\n\tfor(int i=1;i<=n;i++) a[i].t=read(),a[i].b=read();\n\tsort(a+1,a+n+1,cmp);\n\tll sum=0,ans=0;\n\tq.push(a[1].t);\n\tans=1ll*a[1].t*a[1].b;\n\tsum=a[1].t;\n\tfor(int i=2;i<=n;i++)\n\t{\n\t\tint tmp=q.top();\n\t\tq.push(a[i].t);\n\t\tsum+=a[i].t;\n\t\twhile(q.size()>k) sum-=q.top(),q.pop();\n\t\tans=max(ans,sum*a[i].b);\n\t}\n\tcout<<(long long) ans;\n//\tprint(ans);\n\treturn 0;\n}\n/*by DT_Kang*/\n"
