        "Default_Solution": "#include <bits/stdc++.h>\nusing namespace std;\nusing i64 = long long;\n\nconst int maxN = 112345;\nvector<int> p[3];\nvoid solve()\n{\n\tint a, b, c;\n\tscanf(\"%d%d%d\", &a, &b, &c);\n\tfor (int i = 0; i < 3; i++)\n\t\tp[i].clear();\n\tfor (int i = 0; i < a; i++)\n\t{\n\t\tint x;\n\t\tscanf(\"%d\", &x);\n\t\tp[0].push_back(x);\n\t}\n\tfor (int i = 0; i < b; i++)\n\t{\n\t\tint x;\n\t\tscanf(\"%d\", &x);\n\t\tp[1].push_back(x);\n\t}\n\tfor (int i = 0; i < c; i++)\n\t{\n\t\tint x;\n\t\tscanf(\"%d\", &x);\n\t\tp[2].push_back(x);\n\t}\n\tfor (int i = 0; i < 3; i++)\n\t\tsort(p[i].begin(), p[i].end());\n\ti64 ans = 1ll << 62;\n\tfor (int x = 0; x < 3; x++)\n\t\tfor (int y = 0; y < 3; y++)\n\t\t\tfor (int z = 0; z < 3; z++)\n\t\t\t\tif (x != y && y != z && x != z)\n\t\t\t\t{\n\t\t\t\t\tfor (auto u : p[x])\n\t\t\t\t\t{\n\t\t\t\t\t\tauto itv = lower_bound(p[y].begin(), p[y].end(), u);\n\t\t\t\t\t\tif (itv == p[y].end())\n\t\t\t\t\t\t\tcontinue;\n\t\t\t\t\t\tauto itw = lower_bound(p[z].begin(), p[z].end(), (*itv + u + 1) / 2);\n\t\t\t\t\t\tauto sqr = [&](i64 x) { return x * x; };\n\t\t\t\t\t\tif (itw != p[z].end())\n\t\t\t\t\t\t{\n\t\t\t\t\t\t\tans = min(ans, sqr(u - *itv) + sqr(u - *itw) + sqr(*itv - *itw));\n\t\t\t\t\t\t}\n\t\t\t\t\t\tif (itw != p[z].begin())\n\t\t\t\t\t\t{\n\t\t\t\t\t\t\t--itw;\n\t\t\t\t\t\t\tans = min(ans, sqr(u - *itv) + sqr(u - *itw) + sqr(*itv - *itw));\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\tprintf(\"%lld\n\", ans);\n}\nint main()\n{\n\tint t;\n\tscanf(\"%d\", &t);\n\tfor (int tc = 0; tc < t; tc++)\n\t{\n\t\tsolve();\n\t}\n}\n"
