        "Default_Solution": "#include <bits/stdc++.h>\n\nint main() {\n\tusing namespace std;\n\tios_base::sync_with_stdio(false), cin.tie(nullptr);\n\tint N; cin >> N;\n\tvector<int> A(N);\n\tfor (int i = 0; i < N; i++) {\n\t\tcin >> A[i];\n\t}\n\tvector<int> pref(N+1);\n\tfor (int i = 0; i < N; i++) {\n\t\tpref[i+1] = pref[i] ^ A[i];\n\t}\n\n\tfor (int l = 3; l <= N; l++) {\n\t\tfor (int i = 0, j = l; j <= N; i++, j++) {\n\t\t\tfor (int k = i+1; k <= j-1; k++) {\n\t\t\t\tif ((pref[k] ^ pref[i]) > (pref[j] ^ pref[k])) {\n\t\t\t\t\tcout << l-2 << '\n';\n\t\t\t\t\texit(0);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\tcout << -1 << '\n';\n\n\treturn 0;\n}\n"
