        "Default_Solution": "/**\n * code generated by JHelper\n * More info: https://github.com/AlexeyDmitriev/JHelper\n * @author\n */\n\n// Actual solution is at the bottom\n\n#include <algorithm>\n#include <array>\n#include <bitset>\n#include <cassert>\n#include <climits>\n#include <cstdint>\n#include <cmath>\n#include <complex>\n#include <cstdio>\n#include <cstdlib>\n#include <cstring>\n#include <functional>\n#include <iomanip>\n#include <iostream>\n#include <map>\n#include <memory>\n#include <numeric>\n#include <queue>\n#include <random>\n#include <set>\n#include <stack>\n#include <string>\n#include <unordered_set>\n#include <unordered_map>\n#include <vector>\n\n#define sz(v) ((int)(v).size())\n#define all(v) (v).begin(),(v).end()\n\nusing namespace std;\n\ntypedef int64_t int64;\ntypedef pair<int, int> ii;\n\nclass CContinuousCity {\n public:\n  void solveOne() {\n    int l, r;\n    cin >> l >> r;\n    cout << \"YES\n\";\n    vector<tuple<int, int, int>> edges;\n    int n = 23;\n    int need = r - l + 1;\n    int next = l;\n    for (int i = n; i >= n - 21; --i) {\n      int p2 = 1 << max(0, n - i - 1);\n      for (int j = i - 1; j >= n - 21; --j) {\n        edges.emplace_back(j, i, p2);\n      }\n      if (i < n && (need & p2)) {\n        if (next == 1) {\n          int ne = edges.size();\n          for (int j = 0; j < ne; ++j) {\n            if (get<0>(edges[j]) == i) {\n              edges.emplace_back(1, get<1>(edges[j]), get<2>(edges[j]));\n            }\n          }\n        } else {\n          edges.emplace_back(1, i, next - 1);\n        }\n        next += p2;\n        need -= p2;\n      }\n    }\n    assert(need == 0);\n    cout << n << \"\n\";\n    cout << edges.size() << \"\n\";\n    for (auto e : edges) {\n      cout << get<0>(e) << \" \" << get<1>(e) << \" \" << get<2>(e) << \"\n\";\n    }\n  }\n\n  void solve() {\n    int nt = 1;\n    for (int it = 0; it < nt; ++it) {\n      solveOne();\n    }\n  }\n};\n\n\nint main() {\n    std::ios::sync_with_stdio(false);\n    std::cin.tie(0);\n    CContinuousCity solver;\n\n\n    solver.solve();\n    return 0;\n}\n"
