        "Default_Solution": "#line 1 \"a.cpp\"\n#include<cstdio>\n#include<vector>\nusing namespace std;\n#line 2 \"/home/kotatsugame/library/tool/FastIO.cpp\"\n#include<cctype>\n#include<string>\nconst int buffer_size=1<<20;\n//input\nint rd_char()\n{\n\tstatic char buf[buffer_size];\n\tstatic int l=buffer_size,r=buffer_size;\n\tif(l==r&&r==buffer_size)\n\t{\n\t\tr=fread(buf,sizeof(char),1<<20,stdin);\n\t\tl=0;\n\t}\n\tif(l==r)return EOF;\n\treturn buf[l++];\n}\nunsigned int rd_uint()\n{\n\tint c;\n\tunsigned int x=0;\n\twhile('0'<=(c=rd_char()))x=x*10+c-'0';\n\treturn x;\n}\nint rd_int()\n{\n\tbool neg=false;\n\tint c=rd_char();\n\tlong long x=0;\n\tif(c=='-')neg=true;\n\telse x=c-'0';\n\twhile('0'<=(c=rd_char()))x=x*10+c-'0';\n\treturn neg?-x:x;\n}\nunsigned long long rd_ull()\n{\n\tint c;\n\tunsigned long long x=0;\n\twhile('0'<=(c=rd_char()))x=x*10+c-'0';\n\treturn x;\n}\nlong long rd_ll()\n{\n\tbool neg=false;\n\tint c=rd_char();\n\tlong long x=0;\n\tif(c=='-')neg=true;\n\telse x=c-'0';\n\twhile('0'<=(c=rd_char()))x=x*10+c-'0';\n\treturn neg?-x:x;\n}\nstring rd_str()\n{\n\tstring ret;\n\tint c;\n\twhile((c=rd_char())!='\n'&&c!=' '&&c!=EOF)ret+=c;\n\treturn ret;\n}\n//output\nstruct writer_struct{\n\tchar buf[buffer_size];\n\tint l=0;\n\t~writer_struct(){fwrite(buf,sizeof(char),l,stdout);}\n}writer;\nvoid flush()\n{\n\tfwrite(writer.buf,sizeof(char),writer.l,stdout);\n\twriter.l=0;\n}\nvoid wt(char c)\n{\n\tif(writer.l==buffer_size)\n\t{\n\t\tfwrite(writer.buf,sizeof(char),buffer_size,stdout);\n\t\twriter.l=0;\n\t}\n\twriter.buf[writer.l++]=c;\n}\nvoid wt(unsigned int x)\n{\n\tif(x==0)wt('0');\n\telse\n\t{\n\t\tchar f[10];\n\t\tint sz=0;\n\t\twhile(x)\n\t\t{\n\t\t\tf[sz++]=x%10+'0';\n\t\t\tx/=10;\n\t\t}\n\t\twhile(sz)wt(f[--sz]);\n\t}\n}\nvoid wt(int x)\n{\n\tif(x<0)wt('-'),x=-x;\n\twt((unsigned int)x);\n}\nvoid wt(unsigned long long x)\n{\n\tif(x==0)wt('0');\n\telse\n\t{\n\t\tchar f[20];\n\t\tint sz=0;\n\t\twhile(x)\n\t\t{\n\t\t\tf[sz++]=x%10+'0';\n\t\t\tx/=10;\n\t\t}\n\t\twhile(sz)wt(f[--sz]);\n\t}\n}\nvoid wt(long long x)\n{\n\tif(x<0)wt('-'),x=-x;\n\twt((unsigned long long)x);\n}\nvoid wt(const char*s){while(*s!='\\0')wt(*s++);}\nvoid wt(const string&s){for(char c:s)wt(c);}\n#line 5 \"a.cpp\"\nconst long long mod=998244353;\nint N1,N2,M;\nint pr[4<<17],hs[4<<17],hn[4<<17],pe[4<<17],pc[4<<17];\nint ai[4<<17][2];\nint ans,eh=1,id;\nvector<int>es;\nbool usd[4<<17];\nvoid adj(int ei,vector<int>&a,int j)\n{\n\tint pei=-1;\n\tint cnt=0;\n\twhile(ei!=-1)\n\t{\n\t\tusd[ei]=true;\n\t\tif(cnt==j)a.push_back(ei);\n\t\tint tei=ei;\n\t\tif(pei==ai[ei][0])ei=ai[ei][1];\n\t\telse ei=ai[ei][0];\n\t\tpei=tei;\n\t\tcnt=1-cnt;\n\t}\n}\nvoid add(int ei,int ni)\n{\n\tif(ai[ei][0]==-1)ai[ei][0]=ni;\n\telse ai[ei][1]=ni;\n}\nvoid add_edge(int u,int v)\n{\n\tid++;\n\tai[id][0]=ai[id][1]=-1;\n\tv+=N1;\n\teh=eh*2%mod;\n\tif(pr[u]!=-1)\n\t{\n\t\tif(pr[v]!=-1)\n\t\t{\n\t\t\tif(pr[v]==u&&pr[u]==v)\n\t\t\t{\n\t\t\t\tif(pc[u]==0)\n\t\t\t\t{\n\t\t\t\t\tadj(pe[u],es,0);\n\t\t\t\t}\n\t\t\t\telse\n\t\t\t\t{\n\t\t\t\t\tes.push_back(id);\n\t\t\t\t\tadj(pe[u],es,1);\n\t\t\t\t\tans=(ans+eh)%mod;\n\t\t\t\t}\n\t\t\t}\n\t\t\telse\n\t\t\t{\n\t\t\t\tif(pc[u]!=pc[v])\n\t\t\t\t{\n\t\t\t\t\tint rv=pr[v];\n\t\t\t\t\tpc[v]=1-pc[v];\n\t\t\t\t\tpc[rv]=1-pc[rv];\n\t\t\t\t\tans=(ans+mod-hn[v])%mod;\n\t\t\t\t\thn[v]=hn[rv]=(hs[v]-hn[v]+mod)%mod;\n\t\t\t\t\tans=(ans+hn[v])%mod;\n\t\t\t\t}\n\t\t\t\tint ru=pr[u],rv=pr[v];\n\t\t\t\tpr[ru]=rv;pr[rv]=ru;\n\t\t\t\ths[ru]=hs[rv]=((hs[ru]+hs[rv])%mod+eh)%mod;\n\t\t\t\thn[ru]=hn[rv]=(hn[ru]+hn[rv])%mod;\n\t\t\t\tif(pc[u]==1)\n\t\t\t\t{\n\t\t\t\t\thn[ru]=hn[rv]=(hn[ru]+eh)%mod;\n\t\t\t\t\tans=(ans+eh)%mod;\n\t\t\t\t}\n\t\t\t\tadd(pe[u],id);\n\t\t\t\tadd(id,pe[u]);\n\t\t\t\tadd(pe[v],id);\n\t\t\t\tadd(id,pe[v]);\n\t\t\t}\n\t\t\tpr[u]=pr[v]=-1;\n\t\t}\n\t\telse\n\t\t{\n\t\t\tint ru=pr[u];\n\t\t\tpr[ru]=v;\n\t\t\ths[ru]=(hs[ru]+eh)%mod;\n\t\t\tif(pc[u]==1)\n\t\t\t{\n\t\t\t\thn[ru]=(hn[ru]+eh)%mod;\n\t\t\t\tans=(ans+eh)%mod;\n\t\t\t}\n\t\t\tpr[u]=-1;\n\t\t\tpr[v]=ru;\n\t\t\ths[v]=hs[ru];\n\t\t\thn[v]=hn[ru];\n\t\t\tpe[v]=id;\n\t\t\tpc[v]=1-pc[u];\n\t\t\tadd(pe[u],id);\n\t\t\tadd(id,pe[u]);\n\t\t}\n\t}\n\telse\n\t{\n\t\tif(pr[v]!=-1)\n\t\t{\n\t\t\tint rv=pr[v];\n\t\t\tpr[rv]=u;\n\t\t\ths[rv]=(hs[rv]+eh)%mod;\n\t\t\tif(pc[v]==1)\n\t\t\t{\n\t\t\t\thn[rv]=(hn[rv]+eh)%mod;\n\t\t\t\tans=(ans+eh)%mod;\n\t\t\t}\n\t\t\tpr[v]=-1;\n\t\t\tpr[u]=rv;\n\t\t\ths[u]=hs[rv];\n\t\t\thn[u]=hn[rv];\n\t\t\tpe[u]=id;\n\t\t\tpc[u]=1-pc[v];\n\t\t\tadd(pe[v],id);\n\t\t\tadd(id,pe[v]);\n\t\t}\n\t\telse\n\t\t{\n\t\t\tpr[u]=v;\n\t\t\tpr[v]=u;\n\t\t\ths[u]=hs[v]=eh;\n\t\t\thn[u]=hn[v]=eh;\n\t\t\tpe[u]=pe[v]=id;\n\t\t\tpc[u]=pc[v]=0;\n\t\t\tans=(ans+eh)%mod;\n\t\t}\n\t}\n}\nmain()\n{\n\tscanf(\"%d%d%d\",&N1,&N2,&M);\n\tfor(int i=0;i<N1+N2;i++)pr[i]=-1;\n\tfor(int i=0;i<M;i++)\n\t{\n\t\tint u,v;scanf(\"%d%d\",&u,&v);\n\t\tu--,v--;\n\t\tadd_edge(u,v);\n\t}\n\tint Q;\n\tscanf(\"%d\",&Q);\n\tfor(int ccc=0;ccc<Q;ccc++)\n\t{\n\t\tint t;scanf(\"%d\",&t);\n\t\tif(t==1)\n\t\t{\n\t\t\tint u,v;scanf(\"%d%d\",&u,&v);\n\t\t\tu--,v--;\n\t\t\tadd_edge(u,v);\n\t\t\twt(ans);\n\t\t\twt('\n');\n\t\t}\n\t\telse\n\t\t{\n\t\t\tvector<int>ret=es;\n\t\t\tfor(int i=0;i<=id;i++)usd[i]=false;\n\t\t\tfor(int i=0;i<N1+N2;i++)if(pr[i]!=-1&&!usd[pe[i]])\n\t\t\t{\n\t\t\t\tadj(pe[i],ret,pc[i]);\n\t\t\t}\n\t\t\twt((unsigned int)ret.size());\n\t\t\tfor(int id:ret)wt(' '),wt(id);\n\t\t\twt('\n');\n\t\t}\n\t\tflush();\n\t\tfflush(stdout);\n\t}\n}\n"
