        "Default_Solution": "//PRZEMYSL ASSERTY\n\n//SPRAWDZ CORNER CASE'Y, MINIMALNE I MAKSYMALNE WEJ\u015aCIE I WYJ\u015aCIE\n\n//MODULO = 1\n\n//while (clock()<=69*CLOCKS_PER_SEC)\n\n#include <bits/stdc++.h>\n#include <ext/pb_ds/assoc_container.hpp>\n#include <ext/pb_ds/tree_policy.hpp>\n\nusing namespace __gnu_pbds;\nusing namespace std;\n\ntemplate <typename T>\nusing ordered_set =\n    tree<T, null_type, less<T>, rb_tree_tag, tree_order_statistics_node_update>;\n\n#define sim template < class c\n#define ris return * this\n#define dor > debug & operator <<\n#define eni(x) sim > typename \\\n  enable_if<sizeof dud<c>(0) x 1, debug&>::type operator<<(c i) {\nsim > struct rge { c b, e; };\nsim > rge<c> range(c i, c j) { return rge<c>{i, j}; }\nsim > auto dud(c* x) -> decltype(cerr << *x, 0);\nsim > char dud(...);\nstruct debug {\n#ifdef LOCAL\n~debug() { cerr << endl; }\neni(!=) cerr << boolalpha << i; ris; }\neni(==) ris << range(begin(i), end(i)); }\nsim, class b dor(pair < b, c > d) {\n  ris << \"(\" << d.first << \", \" << d.second << \")\";\n}\nsim dor(rge<c> d) {\n  *this << \"[\";\n  for (auto it = d.b; it != d.e; ++it)\n    *this << \", \" + 2 * (it == d.b) << *it;\n  ris << \"]\";\n}\n#else\nsim dor(const c&) { ris; }\n#endif\n};\n#define imie(...) \" [\" << #__VA_ARGS__ \": \" << (__VA_ARGS__) << \"] \"\n\n#define shandom_ruffle random_shuffle\n\nconst int nax=5007;\nconst long long inf=1000*1000*1000+7;\n\nint n;\nlong long b;\n\nlong long c[nax];\nlong long d[nax];\nint oj[nax];\nvector <int> graf[nax];\n\nint roz[nax];\nlong long dpkup[nax][nax];\nlong long dpbez[nax][nax];\n\nvoid dfs(int v)\n{\n\tfor (int i=0; i<=n; i++)\n\t\tdpkup[v][i]=dpbez[v][i]=inf;\n\t\n\troz[v]=0;\n\t\n\tdpkup[v][0]=0;\n\tdpbez[v][0]=0;\n\t\n\tfor (int i : graf[v])\n\t{\n\t\tdfs(i);\n\t\t\n\t\tfor (int j=roz[v]; j>=0; j--)\n\t\t{\n\t\t\tfor (int l=roz[i]; l>=0; l--)\n\t\t\t{\n\t\t\t\tdpkup[v][j+l]=min(dpkup[v][j+l], dpkup[v][j]+min(dpkup[i][l], dpbez[i][l]));\n\t\t\t\tdpbez[v][j+l]=min(dpbez[v][j+l], dpbez[v][j]+dpbez[i][l]);\n\t\t\t}\n\t\t}\n\t\troz[v]+=roz[i];\n\t}\n\tfor (int i=roz[v]; i>=0; i--)\n\t\tdpkup[v][i+1]=dpkup[v][i]+c[v]-d[v];\n\tfor (int i=roz[v]; i>=0; i--)\n\t\tdpbez[v][i+1]=min(dpbez[v][i+1], dpbez[v][i]+c[v]);\n\troz[v]++;\n}\n\nint main()\n{\n\tscanf(\"%d%lld\", &n, &b);\n\t\n\tfor (int i=1; i<=n; i++)\n\t{\n\t\tscanf(\"%lld%lld\", &c[i], &d[i]);\n\t\tif (i>1)\n\t\t{\n\t\t\tscanf(\"%d\", &oj[i]);\n\t\t\tgraf[oj[i]].push_back(i);\n\t\t}\n\t}\n\t\n\tdfs(1);\n\t\n\tfor (int i=1; 1; i++)\n\t{\n\t\tif (i>n || ( dpbez[1][i]>b && dpkup[1][i]>b ))\n\t\t{\n\t\t\tprintf(\"%d\n\", i-1);\n\t\t\treturn 0;\n\t\t}\n\t}\n\t\n\treturn 0;\n}\n"
