    "Chaotic V.": {
        "Default_Solution": "#include <iostream>\n#include <cstdio>\n#include <cstdlib>\n#include <algorithm>\n#include <cmath>\n#include <vector>\n#include <set>\n#include <map>\n#include <unordered_set>\n#include <unordered_map>\n#include <queue>\n#include <ctime>\n#include <cassert>\n#include <complex>\n#include <string>\n#include <cstring>\n#include <chrono>\n#include <random>\n#include <queue>\n#include <bitset>\nusing namespace std;\n\n#ifdef LOCAL\n\t#define eprintf(...) fprintf(stderr, __VA_ARGS__)\n#else\n\t#define eprintf(...) 42\n#endif\n\ntypedef long long ll;\ntypedef pair<int, int> pii;\ntypedef pair<ll, int> pli;\ntypedef pair<ll, ll> pll;\ntypedef long double ld;\n#define mp make_pair\nmt19937 rng(chrono::steady_clock::now().time_since_epoch().count());\n\nconst int N = 5003;\nconst int M = 1001;\nint d[N];\nint pr[M];\nint m;\nint a[N][M];\nint b[N][M];\nint cnt[N];\nll curAns;\n\nvoid precalc() {\n\tm = 1;\n\tfor (int x = 2; x < N; x++) {\n\t\tif (d[x] != 0) continue;\n\t\tpr[m] = x;\n\t\tfor (int y = x; y < N; y += x)\n\t\t\td[y] = m;\n\t\tm++;\n\t}\n\tfor (int x = 2; x < N; x++) {\n\t\tint z = x;\n\t\twhile(z > 1) {\n\t\t\ta[x][d[z]]++;\n\t\t\tz /= pr[d[z]];\n\t\t}\n\t\tfor (int i = 0; i <= m; i++)\n\t\t\ta[x][i] += a[x - 1][i];\n\t}\n\tfor (int x = 1; x < N; x++) {\n\t\tb[x][m] = 0;\n\t\tfor (int i = m - 1; i >= 0; i--)\n\t\t\tb[x][i] = b[x][i + 1] + a[x][i];\n\t}\n}\n\nint main()\n{\n//\tfreopen(\"input.txt\", \"r\", stdin);\n//\tfreopen(\"output.txt\", \"w\", stdout);\n\n\tprecalc();\n\t\n\tint n;\n\tscanf(\"%d\", &n);\n\tfor (int i = 0; i < n; i++) {\n\t\tint x;\n\t\tscanf(\"%d\", &x);\n\t\tif (x == 0) x = 1;\n\t\tcnt[x]++;\n\t}\n\n\tcurAns = 0;\n\tfor (int x = 1; x < N; x++)\n\t\tcurAns += (ll)b[x][0] * cnt[x];\n\n\tint curP = m - 1;\n\tint curH = 0;\n\tint sumH = 0;\n\twhile(curP >= 0) {\n\t\tint tot = 0;\n\t\tint nextH = (int)1e9;\n\t\tfor (int x = 1; x < N; x++) {\n\t\t\tif (cnt[x] == 0) continue;\n\t\t\tif (b[x][curP + 1] != sumH || a[x][curP] <= curH) continue;\n\t\t\ttot += cnt[x];\n\t\t\tnextH = min(nextH, a[x][curP]);\n\t\t}\n\t\tif (2 * tot > n) {\n\t\t\tcurAns -= (ll)(2 * tot - n) * (nextH - curH);\n\t\t\tcurH = nextH;\n\t\t} else {\n\t\t\tsumH += curH;\n\t\t\tcurH = 0;\n\t\t\tcurP--;\n\t\t}\n\t}\n\tprintf(\"%lld\n\", curAns);\n\n\treturn 0;\n}\n"
    },
    "Chattering": {
        "Default_Solution": "#include <bits/stdc++.h>\nusing namespace std;\ntypedef long long LL;\n\nvector<int> l, r, x;\n\nvector<vector<int> > jl, jr;\n\nint largmin(int i, int j){\n\tif(l[i] < l[j]) return i;\n\treturn j;\n}\nint rargmax(int i, int j){\n\tif(r[i] > r[j]) return i;\n\treturn j;\n}\n\nint lmin(int a, int b){\n\tint z = 0;\n\twhile((1 << (z+1)) <= b-a+1) z += 1;\n\treturn largmin(jl[z][b], jl[z][a-1+(1 << z)]);\n}\nint rmax(int a, int b){\n\tint z = 0;\n\twhile((1 << (z+1)) <= b-a+1) z += 1;\n\treturn rargmax(jr[z][a], jr[z][b+1 - (1 << z)]);\n}\n\nint main(){\n\tint n;\n\tcin >> n;\n\tx.resize(n);\n\tfor(int i = 0; i < n; i++){\n\t\tcin >> x[i];\n\t}\n\tint N = 3*n;\n\tl.resize(N);\n\tr.resize(N);\n\tfor(int i = 0; i < N; i++){\n\t\tl[i] = max(i - x[i % n], 0);\n\t\tr[i] = min(i + x[i % n], N-1);\n\t}\n\tconst int MAXJ = 20;\n\tjl.resize(MAXJ, vector<int>(N));\n\tjr.resize(MAXJ, vector<int>(N));\n\tfor(int j = 0; j < MAXJ; j++){\n\t\tfor(int i = 0; i < N; i++){\n\t\t\tif(j == 0){\n\t\t\t\tjl[j][i] = jr[j][i] = i;\n\t\t\t} else {\n\t\t\t\tjl[j][i] = largmin(jl[j-1][i], jl[j-1][max(i - (1 << (j-1)), 0)]);\n\t\t\t\tjr[j][i] = rargmax(jr[j-1][i], jr[j-1][min(i + (1 << (j-1)), N-1)]);\n\t\t\t}\n\t\t}\n\t}\n\tvector<vector<int> > lexpo(MAXJ, vector<int>(N));\n\tvector<vector<int> > rexpo(MAXJ, vector<int>(N));\t\n\tfor(int j = 0; j < MAXJ; j++){\n\t\tfor(int i = 0; i < N; i++){\n\t\t\tif(j == 0){\n\t\t\t\tlexpo[j][i] = lmin(l[i], i);\n\t\t\t\trexpo[j][i] = rmax(i, r[i]);\n\t\t\t} else {\n\t\t\t\tlexpo[j][i] = lexpo[j-1][lexpo[j-1][i]];\n\t\t\t\trexpo[j][i] = rexpo[j-1][rexpo[j-1][i]];\n\t\t\t}\n\t\t}\n\t}\n\tvector<int> ans(n);\n\tfor(int i = n; i < 2*n; i++){\n\t\tint curl = i;\n\t\tint curr = i;\n\t\tint nsteps = 0;\n\t\twhile(1){\n\t\t\tif(curr - curl + 1 >= n) break;\n\t\t\tfor(int j = MAXJ-1; j >= 0; j--){\n\t\t\t\tint newl = lmin(curl, curr);\n\t\t\t\tint newr = rmax(curl, curr);\n\t\t\t\tint xl = lexpo[j][newl];\n\t\t\t\tint xr = rexpo[j][newr];\n\t\t\t\tif(r[rmax(xl, curl)] > curr){\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tif(l[lmin(curr, xr)] < curl){\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\tif(r[xr] - l[xl] + 1 >= n) continue;\n\t\t\t\tcurl = l[xl];\n\t\t\t\tcurr = r[xr];\n\t\t\t\tnsteps += 1 + (1<<j);\n\t\t\t}\n\t\t\tif(curr - curl + 1 >= n) break;\n\t\t\tint newl = lmin(curl, curr);\n\t\t\tint newr = rmax(curl, curr);\n\t\t\tcurl = l[newl];\n\t\t\tcurr = r[newr];\n\t\t\tnsteps++;\n\t\t}\n\t\tans[i - n] = nsteps;\n\t}\n\tfor(int i = 0; i < n; i++){\n\t\tcout << ans[i] << \" \";\n\t}\n\tcout << '\n';\n}"
    },
