        "Default_Solution": "#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nchar ch;\n\nvoid read(int &x)\n{\n\tx=0;\n\tch=getchar();\n\twhile (ch<=32) ch=getchar();\n\twhile (ch>32) x=x*10+ch-48,ch=getchar();\n}\n\nchar a[1005];\nint w[30];\n\nlong long getsum(int l,int r)\n{\n\treturn 1LL*(r-l+1)*(l+r)/2LL;\n}\n\nint main()\n{\n\tscanf(\"%s\",a+1);\n\tint n=strlen(a+1);\n\tint k;\n\tread(k);\n\tint i;\n\tint ma=0;\n\tfor (i=1;i<=26;i++) {\n\t\tread(w[i]);\n\t\tif (w[i]>ma) ma=w[i];\n\t}\n\tlong long sum=0;\n\tlong long ans=0;\n\tfor (i=1;i<=n;i++) {\n\t\tsum+=1LL*i*w[a[i]-'a'+1];\n\t}\n\tans=sum+getsum(n+1,n+k)*ma;\n\tprintf(\"%I64d\n\",ans);\n}"
