    "Road Improvement": {
        "Default_Solution": "#include <cstdio>\n#include <cstdlib>\n#include <cmath>\n#include <algorithm>\n#include <iostream>\n#include <cstring>\n#include <vector>\n#include <set>\n#include <map>\n#include <cassert>\n#include <ctime>\n#include <string>\n\nusing namespace std;\n\n#ifdef _WIN32\n#define LLD \"%I64d\"\n#else\n#define LLD \"%lld\"\n#endif\n\ntypedef long double ld;\n\nlong long rdtsc() {\n  long long tmp;\n  asm(\"rdtsc\" : \"=A\"(tmp));\n  return tmp;\n}\n\ninline int myrand() {\n  return abs((rand() << 15) ^ rand());\n}\n\ninline int rnd(int x) {\n  return myrand() % x;\n}\n\n#define pb push_back\n#define mp make_pair\n#define eprintf(...) fprintf(stderr, __VA_ARGS__)\n#define sz(x) ((int)(x).size())\n#define TASKNAME \"text\"\n\nconst int INF = (int)1e9 + 1;\nconst ld EPS = 1e-9;\n\nvoid precalc() {\n}\n\nint n;\n\nconst int maxn = (int) 2e5 + 10;\nint pr[maxn];\n\nbool read() {\n  if (scanf(\"%d\", &n) < 1) {\n    return 0;\n  }\n  pr[0] = -1;\n  for (int i = 1; i < n; ++i) {\n    scanf(\"%d\", &pr[i]);\n    --pr[i];\n  }\n  return 1;\n}\n\nconst int MOD = (int) 1e9 + 7;\n\nint mult(int x, int y) {\n  return (long long) x * y % MOD;\n}\n\nvector<vector<int> > es;\n\nint f[maxn];\n\nvoid dfs(int v) {\n  int &res = f[v];\n  res = 1;\n  for (int it = 0; it < sz(es[v]); ++it) {\n    int u = es[v][it];\n    dfs(u);\n    res = mult(res, f[u] + 1);\n  }\n}\n\nint ans[maxn];\n\nvoid dfsLast(int v, int coef = 0) {\n  ++coef;\n  if (coef == MOD) {\n    coef = 0;\n  }\n  int &res = f[v];\n  res = 1;\n  int k  = sz(es[v]);\n  vector<int> pref(k + 1);\n  vector<int> suf(k + 1);\n  pref[0] = 1;\n  for (int i = 0; i < k; ++i) {\n    pref[i + 1] = mult(pref[i], f[es[v][i]] + 1);\n  }\n  suf[k] = 1;\n  for (int i = k - 1; i >= 0; --i) {\n    suf[i] = mult(suf[i + 1], f[es[v][i]] + 1);\n  }\n\n  ans[v] = mult(pref[k], coef);\n  for (int it = 0; it < k; ++it) {\n    int u = es[v][it];\n    dfsLast(u, mult(coef, mult(pref[it], suf[it + 1])));\n  }\n}\n\nvoid solve() {\n  es = vector<vector<int> >(n);\n  for (int i = 1; i < n; ++i) {\n    es[pr[i]].pb(i);\n  }\n\n  dfs(0);\n\n  dfsLast(0);\n  for (int i = 0; i < n; ++i) {\n    printf(\"%d%c\", ans[i], \" \n\"[i == n - 1]);\n  }\n}\n\nint main() {\n  srand(rdtsc());\n#ifdef DEBUG\n  freopen(TASKNAME\".out\", \"w\", stdout);\n  assert(freopen(TASKNAME\".in\", \"r\", stdin));\n#endif\n\n  precalc();\n  while (1) {\n    if (!read()) {\n      break;\n    }\n    solve();\n#ifdef DEBUG\n    eprintf(\"%.18lf\n\", (double)clock() / CLOCKS_PER_SEC);\n#endif\n  }\n  return 0;\n}\n"
    },
