    "Zip-line": {
        "Default_Solution": "#include <bits/stdc++.h>\n\nusing namespace std;\n\nconst int N = 1200010;\n\nint t, mx[N];\n\ninline void modify(int x, int v) {\n  while (x <= t) {\n    if (v > mx[x]) {\n      mx[x] = v;\n    }\n    x = (x | (x - 1)) + 1;\n  }\n}\n\ninline int find_max(int x) {\n  int v = 0;\n  while (x > 0) {\n    if (mx[x] > v) {\n      v = mx[x];\n    }\n    x &= x - 1;\n  }\n  return v;\n}\n\npair <int, int> ev[N];\nint pos[N], value[N], with[N];\nint dpleft[N], dpright[N];\nvector <int> qs[N];\nvector <int> who[N];\nint h[N];\nbool all[N];\n\nint main() {\n  int n, m;\n  scanf(\"%d %d\", &n, &m);\n  for (int i = 0; i < n; i++) {\n    scanf(\"%d\", h + i);\n    ev[i] = make_pair(h[i], i);\n  }\n  for (int i = 0; i < m; i++) {\n    scanf(\"%d %d\", pos + i, value + i);\n    pos[i]--;\n    ev[n + i] = make_pair(value[i], ~i);\n    with[i] = 1;\n  }\n  sort(ev, ev + n + m);\n  t = 0;\n  for (int i = 0; i < n + m; i++) {\n    if (i == 0 || ev[i].first != ev[i - 1].first) {\n      t++;\n    }\n    int id = ev[i].second;\n    if (id >= 0) {\n      h[id] = t;\n    } else {\n      value[~id] = t;\n    }\n  }\n  for (int i = 0; i < n; i++) {\n    qs[i].clear();\n  }\n  for (int i = 0; i < m; i++) {\n    qs[pos[i]].push_back(i);\n  }\n  for (int i = 1; i <= t; i++) {\n    mx[i] = 0;\n  }\n  for (int i = 0; i < n; i++) {\n    dpleft[i] = find_max(h[i] - 1) + 1;\n    int sz = qs[i].size();\n    for (int j = 0; j < sz; j++) {\n      int qid = qs[i][j];\n      with[qid] += find_max(value[qid] - 1);\n    }\n    modify(h[i], dpleft[i]);\n  }\n  for (int i = 1; i <= t; i++) {\n    mx[i] = 0;\n  }\n  for (int i = n - 1; i >= 0; i--) {\n    dpright[i] = find_max(t - h[i]) + 1;\n    int sz = qs[i].size();\n    for (int j = 0; j < sz; j++) {\n      int qid = qs[i][j];\n      with[qid] += find_max(t - value[qid]);\n    }\n    modify(t - h[i] + 1, dpright[i]);\n  }\n  int ans = 0;\n  for (int i = 0; i < n; i++) {\n    ans = max(ans, dpleft[i]);\n  }\n  for (int i = 1; i <= ans; i++) {\n    who[i].clear();\n  }\n  for (int i = 0; i < n; i++) {\n    int total = dpleft[i] + dpright[i] - 1;\n    if (total != ans) {\n      continue;\n    }\n    who[dpleft[i]].push_back(i);\n  }\n  for (int i = 0; i < n; i++) {\n    all[i] = false;\n  }\n  for (int i = 1; i <= ans; i++) {\n    int sz = who[i].size();\n    if (sz != 1) {\n      continue;\n    }\n    all[who[i][0]] = true;\n  }\n  for (int i = 0; i < m; i++) {\n    int res = with[i];\n    if (all[pos[i]]) {\n      res = max(res, ans - 1);\n    } else {\n      res = max(res, ans);\n    }\n    printf(\"%d\n\", res);\n  }\n  return 0;\n}\n"
    },
