    "Euler tour": {
        "Default_Solution": "#include <bits/stdc++.h>\n\nusing namespace std;\n\nint main() {\n#ifdef wxh010910\n  freopen(\"input.txt\", \"r\", stdin);\n#endif\n  int n;\n  scanf(\"%d\", &n);\n  int m = (n << 1) - 1;\n  vector<int> a(m);\n  int first = -1;\n  for (int i = 0; i < m; ++i) {\n    scanf(\"%d\", &a[i]);\n    --a[i];\n    if (!~first && ~a[i]) {\n      first = i;\n    }\n  }\n  if (!~first) {\n    puts(\"yes\");\n    printf(\"1\");\n    for (int i = 1; i < n; ++i) {\n      printf(\" %d 1\", i + 1);\n    }\n    putchar(10);\n    return 0;\n  }\n  if (first) {\n    vector<int> temp;\n    for (int i = first; i < m; ++i) {\n      temp.push_back(a[i]);\n    }\n    for (int i = 0; i < first; ++i) {\n      temp.push_back(a[i]);\n    }\n    a = temp;\n  }\n\n  if (~a.back() && a.back() != a[0]) {\n    puts(\"no\");\n    return 0;\n  }\n  a.back() = a[0];\n  vector<int> free, parity(n, -1);\n  for (int i = 0; i < m; ++i) {\n    if (~a[i]) {\n      if (~parity[a[i]]) {\n        if (parity[a[i]] != (i & 1)) {\n          puts(\"no\");\n          return 0;\n        }\n      } else {\n        parity[a[i]] = i & 1;\n      }\n    }\n  }\n  for (int i = 0; i < n; ++i) {\n    if (!~parity[i]) {\n      free.push_back(i);\n    }\n  }\n\n  vector<int> prev(m), next(m);\n  for (int i = 0; i < m; ++i) {\n    prev[i] = i - 1;\n    next[i] = i + 1;\n  }\n\n  auto erase = [&](int x) {\n    if (next[x] != m) {\n      prev[next[x]] = prev[x];\n    }\n    if (~prev[x]) {\n      next[prev[x]] = next[x];\n    }\n  };\n\n  auto solve = [&](int l, int r) {\n    for (int i = next[l]; i < r; ) {\n      if (~a[i] && ~a[next[i]] && !~a[prev[i]]) {\n        a[prev[i]] = a[next[i]];\n        erase(i);\n        erase(next[i]);\n        i = prev[i];\n        if (i > l) {\n          i = prev[i];\n        }\n        if (i == l) {\n          i = next[i];\n        }\n      } else if (~a[i] && ~a[prev[i]] && !~a[next[i]]) {\n        a[next[i]] = a[prev[i]];\n        erase(i);\n        erase(next[i]);\n        i = prev[i];\n        if (i == l) {\n          i = next[i];\n        }\n      } else {\n        i = next[i];\n      }\n    }\n    for (int i = next[l]; i < r; i = next[i]) {\n      erase(i);\n    }\n    erase(r);\n  };\n\n  vector<bool> not_first(n), ban(n);\n  for (int i = 0; i < m; ++i) {\n    if (~a[i]) {\n      if (not_first[a[i]]) {\n        if (ban[a[i]]) {\n          puts(\"no\");\n          return 0;\n        }\n        int left = prev[i], right = i, numbers = 1, total = 1;\n        while (a[left] != a[right]) {\n          if (~a[left]) {\n            ban[a[left]] = true;\n            ++numbers;\n          }\n          ++total;\n          left = prev[left];\n        }\n        int need = (total >> 1) + 1 - numbers;\n        if (need < 0) {\n          puts(\"no\");\n          return 0;\n        }\n        for (int j = left; j < right; j = next[j]) {\n          if (!~a[j] && need) {\n            if (free.empty()) {\n              puts(\"no\");\n              return 0;\n            } else {\n              a[j] = free.back();\n              --need;\n              free.pop_back();\n            }\n          }\n        }\n        solve(left, right);\n      } else {\n        not_first[a[i]] = true;\n      }\n    }\n  }\n\n  puts(\"yes\");\n  if (first) {\n    vector<int> temp;\n    for (int i = m - 1 - first; i < m - 1; ++i) {\n      temp.push_back(a[i]);\n    }\n    for (int i = 0; i < m - 1 - first; ++i) {\n      temp.push_back(a[i]);\n    }\n    temp.push_back(a[m - 1 - first]);\n    a = temp;\n  }\n  for (int i = 0; i < m; ++i) {\n    printf(\"%d%c\", a[i] + 1, i == m - 1 ? '\n' : ' ');\n  }\n  return 0;\n}\n"
    },
    "Evil": {
        "Default_Solution": "#include <iostream>\n#include <fstream>\n#include <iomanip>\n#include <cstdio>\n#include <vector>\n#include <cmath>\n#include <algorithm>\n#include <string>\n#include <queue>\n\nusing namespace std;\ntypedef long long ll;\nconst int MAXN = 200100;\n\nint N;\npair <int, int> city[MAXN];\nint xval[MAXN], yval[MAXN];\n\nint main()\n{\n\tcin >> N;\n\tfor (int i = 0; i < N; i++)\n\t{\n\t\tcin >> city[i].first >> city[i].second;\n\t\t\n\t\txval[i] = city[i].first;\n\t\tyval[i] = city[i].second;\n\t}\n\t\n\tsort (xval, xval + N);\n\tsort (yval, yval + N);\n\t\n\tll tot = 0;\n\tfor (int i = 0; i < N; i++)\n\t{\n\t\tif (i * 2 < N - 1)\n\t\t\ttot -= xval[i] + yval[i];\n\t\tif (i * 2 > N - 1)\n\t\t\ttot += xval[i] + yval[i];\n\t}\n\ttot *= 2;\n\t\n\tif (N % 2 == 0)\n\t{\n\t\tbool bad1 = false, bad2 = false;\n\t\tfor (int i = 0; i < N; i++)\n\t\t{\n\t\t\tif (city[i].first <= xval[N / 2 - 1] && city[i].second >= yval[N / 2])\n\t\t\t\tbad1 = true;\n\t\t\tif (city[i].first >= xval[N / 2] && city[i].second <= yval[N / 2 - 1])\n\t\t\t\tbad1 = true;\n\t\t\t\n\t\t\tif (city[i].first <= xval[N / 2 - 1] && city[i].second <= yval[N / 2 - 1])\n\t\t\t\tbad2 = true;\n\t\t\tif (city[i].first >= xval[N / 2] && city[i].second >= yval[N / 2])\n\t\t\t\tbad2 = true;\n\t\t}\n\t\t\n\t\tif (bad1 && bad2)\n\t\t\ttot -= 2 * min (xval[N / 2] - xval[N / 2 - 1], yval[N / 2] - yval[N / 2 - 1]);\n\t\t\n\t\tcout << tot << \"\n\";\n\t}\n\telse\n\t{\n\t\tbool good = false, bad1 = false, bad2 = false;\n\t\tfor (int i = 0; i < N; i++)\n\t\t{\n\t\t\tif (city[i].first < xval[N / 2] && city[i].second > yval[N / 2])\n\t\t\t\tbad1 = true;\n\t\t\tif (city[i].first > xval[N / 2] && city[i].second < yval[N / 2])\n\t\t\t\tbad1 = true;\n\t\t\t\n\t\t\tif (city[i].first < xval[N / 2] && city[i].second < yval[N / 2])\n\t\t\t\tbad2 = true;\n\t\t\tif (city[i].first > xval[N / 2] && city[i].second > yval[N / 2])\n\t\t\t\tbad2 = true;\n\t\t\t\n\t\t\tif (city[i].first == xval[N/2] && city[i].second != yval[N/2])\n\t\t\t\tgood = true;\n\t\t\tif (city[i].first != xval[N/2] && city[i].second == yval[N/2])\n\t\t\t\tgood = true;\n\t\t}\n\t\t\n\t\tif (!good && bad1 && bad2)\n\t\t\ttot -= 2 * min (min (xval[N / 2] - xval[N / 2 - 1], xval[N / 2 + 1] - xval[N / 2]),\n\t\t\t\t\t\t\tmin (yval[N / 2] - yval[N / 2 - 1], yval[N / 2 + 1] - yval[N / 2]));\n\t\t\n\t\tcout << tot << \"\n\";\n\t}\n\treturn 0;\n}\n"
    },
