    "Playing on Graph": {
        "Default_Solution": "#include <iostream>\n#include <fstream>\n#include <cstdio>\n#include <algorithm>\n#include <map>\n#include <vector>\n#include <string>\n#include <queue>\n\nusing namespace std;\ntypedef long long ll;\nconst int MAXN = 1100;\n\nint N, M;\nvector <int> edge[MAXN];\nbool seen[MAXN];\nbool bad;\nint par[MAXN];\n\nvector <int> cvert;\nint dist[MAXN];\n\nvoid flood (int cloc, int cpar)\n{\n    if (par[cloc] == 1 - cpar)\n    {\n        bad = true;\n        return;\n    }\n    \n    if (seen[cloc])\n        return;\n    seen[cloc] = true;\n    par[cloc] = cpar;\n    cvert.push_back (cloc);\n    \n    for (int i = 0; i < edge[cloc].size(); i++)\n        flood (edge[cloc][i], 1 - cpar);\n}\n\nvector <int> q;\n\nint solve (int start)\n{\n    cvert.clear();\n    flood (start, 0);\n    \n    int res = 0;\n    for (int i = 0; i < cvert.size(); i++)\n    {\n        int cloc = cvert[i];\n        \n        for (int j = 0; j < N; j++)\n            dist[j] = 1e9;\n        \n        dist[cloc] = 0;\n        q.clear();\n        q.push_back (cloc);\n        \n        for (int j = 0; j < q.size(); j++)\n        {\n            int x = q[j];\n            for (int k = 0; k < edge[x].size(); k++)\n            {\n                int neigh = edge[x][k];\n                if (dist[neigh] > dist[x] + 1)\n                {\n                    dist[neigh] = dist[x] + 1;\n                    \n                    //cout << i << \" \" << neigh << \" \" << dist[neigh] << \"\n\";\n                    res = max (res, dist[neigh]);\n                    q.push_back (neigh);\n                }\n            }\n        }\n    }\n    \n    //cout << start << \" \" << res << \"\n\";\n    return res;\n}\n\nint main()\n{\n    ios_base::sync_with_stdio(0);\n    \n    cin >> N >> M;\n    for (int i = 0; i < M; i++)\n    {\n        int a, b;\n        cin >> a >> b;\n        a--, b--;\n        edge[a].push_back (b);\n        edge[b].push_back (a);\n    }\n    \n    for (int i = 0; i < N; i++)\n    {\n        seen[i] = false;\n        par[i] = 2;\n    }\n    bad = false;\n    \n    int ans = 0;\n    for (int i = 0; i < N; i++)\n        if (!seen[i])\n            ans += solve (i);\n    \n    if (bad)\n        cout << \"-1\n\";\n    else\n        cout << ans << \"\n\";\n    return 0;\n}"
    },
