        "Default_Solution": "#pragma comment(linker, \"/STACK:60000000\")\n#define _CRT_SECURE_NO_WARNINGS\n\n#include <cstdio>\n#include <iostream>\n#include <vector>\n#include <cmath>\n#include <algorithm>\n#include <string>\n#include <set>\n#include <map>\n#include <ctime>\n#include <cstring>\n#include <cassert>\n#include <sstream>\n#include <iomanip>\n#include <complex>\n#include <queue>\n#include <functional>\n\nusing namespace std;\n\n#define forn(i, n) for(int i = 0; i < (int)(n); i++)\n#define ford(i, n) for(int i = (int)(n) - 1; i >= 0; i--)\n#define pb push_back\n#define mp make_pair\n#define fs first\n#define sc second\n#define last(a) int(a.size() - 1)\n#define all(a) a.begin(), a.end()\n#define seta(a,x) memset (a, x, sizeof (a))\n#define I (int)\n#define next NEXTHUI\n#define prev PREVHUI\n#define y1 Y1HUI\n\ntypedef long long int64;\ntypedef pair <int, int> pii;\ntypedef long double ldb;\n\nconst long double eps = 1e-9;\nconst int inf = (1 << 30) - 1;\nconst int64 inf64 = ((int64)1 << 62) - 1;\nconst long double pi = 3.1415926535897932384626433832795;\n\ntemplate <class T> T sqr (T x) {return x * x;}\n\nint n;\nvector<pii> a;\nvector< vector<int> > g;\nvector<int> pos[100500];\nint col[200500];\n\nvoid error() {\n\tcout << -1 << endl;\n\texit(0);\n}\n\nvoid go(int v, int c) {\n\tcol[v]= c;\n\tforn(i, g[v].size())\n\t\tif (col[g[v][i]] == -1)\n\t\t\tgo(g[v][i], 1 - c);\n\t\telse if (col[g[v][i]] == c)\n\t\t\terror();\t\t\t\t\n}\n\nint main ()\n{\n//\tfreopen (\"input.txt\", \"r\", stdin);\n//\tfreopen (\"output.txt\", \"w\", stdout);\n\tcin >> n;\n\ta.clear();\n\tforn(i, n) {\n\t\tint x, y;\n\t\tscanf(\"%d%d\", &x, &y);\n\t\tx *= 2;\n\t\ty *= 2;\n\t\ta.pb(mp(x-1, i));\n\t\ta.pb(mp(y, i));\n\t}\t\n\tsort(all(a));\n\tforn(i, a.size())\n\t\tpos[a[i].sc].pb(i);\n\tg.resize(n * 2);\n\tforn(i, n) {\n\t\tg[i * 2].pb(i * 2 + 1);\n\t\tg[i * 2 + 1].pb(i * 2);\n\n\t\tg[pos[i][0]].pb(pos[i][1]);\n\t\tg[pos[i][1]].pb(pos[i][0]);\n\t}\n\tseta(col, 255);\n\tforn(i, n * 2)\n\t\tif (col[i] == -1)\n\t\t\tgo(i, 0);\n\tforn(i, n)\n\t\tprintf(\"%d \", col[pos[i][0]]);\n\tprintf(\"\n\");\n\treturn 0;\n}\n"
