        "Default_Solution": "//~ while (clock()<=69*CLOCKS_PER_SEC)\n//~ #pragma comment(linker, \"/stack:200000000\")\n#pragma GCC optimize(\"O3\")\n//~ #pragma GCC optimize(\"Ofast\")\n//~ #pragma GCC target(\"sse,sse2,sse3,ssse3,sse4,popcnt,abm,mmx,avx,tune=native\")\n//~ #pragma GCC optimize(\"unroll-loops\")\n#include <bits/stdc++.h>\n#include <ext/pb_ds/assoc_container.hpp>\n#include <ext/pb_ds/tree_policy.hpp>\n\nusing namespace __gnu_pbds;\nusing namespace std;\n\ntemplate <typename T>\nusing ordered_set =\n    tree<T, null_type, less<T>, rb_tree_tag, tree_order_statistics_node_update>;\n\n#define sim template < class c\n#define ris return * this\n#define dor > debug & operator <<\n#define eni(x) sim > typename \\\n  enable_if<sizeof dud<c>(0) x 1, debug&>::type operator<<(c i) {\nsim > struct rge { c b, e; };\nsim > rge<c> range(c i, c j) { return rge<c>{i, j}; }\nsim > auto dud(c* x) -> decltype(cerr << *x, 0);\nsim > char dud(...);\nstruct debug {\n#ifdef LOCAL\n~debug() { cerr << endl; }\neni(!=) cerr << boolalpha << i; ris; }\neni(==) ris << range(begin(i), end(i)); }\nsim, class b dor(pair < b, c > d) {\n  ris << \"(\" << d.first << \", \" << d.second << \")\";\n}\nsim dor(rge<c> d) {\n  *this << \"[\";\n  for (auto it = d.b; it != d.e; ++it)\n    *this << \", \" + 2 * (it == d.b) << *it;\n  ris << \"]\";\n}\n#else\nsim dor(const c&) { ris; }\n#endif\n};\n#define imie(...) \" [\" << #__VA_ARGS__ \": \" << (__VA_ARGS__) << \"] \"\n\n#define shandom_ruffle random_shuffle\n\nusing ll=long long;\nusing pii=pair<int,int>;\nusing pll=pair<ll,ll>;\nusing vi=vector<int>;\nusing vll=vector<ll>;\nconst int nax=100*1007;\nconst ll inf=1e18;\n\nint n;\nll c, d;\nll tab[nax];\nint kto[nax];\n\nll dp[nax];\nll wyn=inf;\n\nll ile[nax][2];\nll sum[nax][2];\n\nint najd[nax];\n\n//~ ll koszt(int i, int j)\n//~ {\n\t//~ int x=kto[i];\n\t//~ return dp[j]+(ile[i][x^1]-ile[j][x^1])*d+((sum[i][x]-sum[j][x])-(tab[n+1]-tab[j])*(ile[i][x]-ile[j][x]))*c;\n//~ }\n\nll koszt(int i, int j)\n{\n\tint x=kto[i];\n\tll ret=dp[j]+(ile[i][x^1]-ile[j][x^1])*d;\n\tret+=(tab[j]-tab[i])*c;\n\ti++;\n\tif (i<najd[j])\n\t{\n\t\tret+=(ile[i][x]-ile[najd[j]][x])*d;\n\t\ti=najd[j];\n\t}\n\tret+=((sum[i][x]-sum[j][x])-(tab[n+1]-tab[j])*(ile[i][x]-ile[j][x]))*c;\n\treturn ret;\n}\n\nvi poz[2];\nvi pot[2];\n\nvoid mini(ll &a, ll b)\n{\n\ta=min(a, b);\n}\n\nvoid rek2(int h, int a, int b, int c, int d)\n{\n\tif (a>b || c>d)\n\t\treturn;\n\tint s=(a+b)>>1;\n\tint g=-1;\n\tll war=inf;\n\tfor (int i=c; i<=d; i++)\n\t{\n\t\tll w=koszt(poz[h][s], pot[h][i]);\n\t\tif (w<war)\n\t\t{\n\t\t\twar=w;\n\t\t\tg=i;\n\t\t}\n\t}\n\tmini(dp[poz[h][s]], war);\n\tassert(g>=0);\n\trek2(h, a, s-1, c, g);\n\trek2(h, s+1, b, g, d);\n}\n\nvoid rek1(int a, int b)\n{\n\tif (a>=b)\n\t\treturn;\n\tint s=(a+b)>>1;\n\trek1(s+1, b);\n\t\n\tpoz[0].clear();\n\tpoz[1].clear();\n\tpot[0].clear();\n\tpot[1].clear();\n\tfor (int i=a; i<=s; i++)\n\t\tpoz[kto[i]].push_back(i);\n\tfor (int i=s+1; i<=b; i++)\n\t\tfor (int h=0; h<2; h++)\n\t\t\tif (h!=kto[i])\n\t\t\t\tpot[h].push_back(i);\n\t\n\tfor (int h=0; h<2; h++)\n\t\trek2(h, 0, (int)poz[h].size()-1, 0, (int)pot[h].size()-1);\n\t\n\t\n\trek1(a, s);\n}\n\nint main()\n{\n\tscanf(\"%d%lld%lld\", &n, &c, &d);\n\tfor (int i=1; i<=n+1; i++)\n\t{\n\t\ttab[i]=i;\n\t\tscanf(\"%lld\", &tab[i]);\n\t\tif (i<=n)\n\t\t{\n\t\t\tchar x;\n\t\t\tscanf(\" %c\", &x);\n\t\t\tkto[i]=(x=='P');\n\t\t\t//~ kto[i]=rand()&1;\n\t\t}\n\t\telse\n\t\t\tkto[i]=2;\n\t}\n\t//~ debug() << range(tab+1, tab+1+n);\n\tfor (int i=1; i<=n; i++)\n\t\tdp[i]=inf;\n\t//~ debug() << imie(n) << imie(dp[6]);\n\tfor (int i=n; i; i--)\n\t{\n\t\tfor (int h=0; h<2; h++)\n\t\t{\n\t\t\tile[i][h]=ile[i+1][h];\n\t\t\tsum[i][h]=sum[i+1][h];\n\t\t}\n\t\tile[i][kto[i]]++;\n\t\tsum[i][kto[i]]+=(tab[n+1]-tab[i]);\n\t}\n\t\n\tfor (int i=1; i<=n+1; i++)\n\t{\n\t\tnajd[i]=max(najd[i-1], 1);\n\t\twhile(d<c*(tab[i]-tab[najd[i]]))\n\t\t\tnajd[i]++;\n\t}\n\t//~ debug() << range(najd+1, najd+1+n);\n\t\n\t//~ for (int i=n; i; i--)\n\t\t//~ for (int j=i+1; j<=n+1; j++)\n\t\t\t//~ if (kto[i]!=kto[j])\n\t\t\t\t//~ dp[i]=min(dp[i], koszt(i, j));\n\t\n\trek1(1, n+1);\n\t//~ for (int i=n; i; i--)\n\t//~ {\n\t\t//~ for (int j=i+1; j<=n+1; j++)\n\t\t//~ {\n\t\t\t//~ if (kto[i]==kto[j])\n\t\t\t\t//~ continue;\n\t\t\t//~ ll trz=dp[j];\n\t\t\t//~ for (int l=i; l<j; l++)\n\t\t\t//~ {\n\t\t\t\t//~ if (kto[l]==kto[i])\n\t\t\t\t//~ {\n\t\t\t\t\t//~ if (l==i)\n\t\t\t\t\t\t//~ trz+=c*(tab[j]-tab[l]);\n\t\t\t\t\t//~ else\n\t\t\t\t\t\t//~ trz+=min(c*(tab[j]-tab[l]), d);\n\t\t\t\t//~ }\n\t\t\t\t//~ else\n\t\t\t\t\t//~ trz+=d;\n\t\t\t//~ }\n\t\t\t//~ dp[i]=min(dp[i], trz);\n\t\t//~ }\n\t//~ }\n\t//~ debug() << range(dp+1, dp+1+n+1);\n\t\n\tfor (int i=1; i<=n+1; i++)\n\t\twyn=min(wyn, dp[i]+(i-1)*d);\n\tprintf(\"%lld\n\", wyn);\n\treturn 0;\n}\n"
