        "Default_Solution": "#include <bits/stdc++.h>\n#define rep(i, n) for(int i = 0; i < (int)(n); i ++)\n#define rep1(i, n) for(int i = 1; i <= (int)(n); i ++)\n#define MP make_pair\n\nusing namespace std;\ntypedef long long LL;\ntypedef pair<int, int> PII;\nconst int MOD = 998244353;\n\nbool ok[100005];\nvoid solve()\n{\n\tint n, m, a, b, c;\n\tscanf(\"%d%d\", &n, &m);\n\trep1(i, n) ok[i] = true;\n\trep(i, m) {\n\t\tscanf(\"%d%d%d\", &a, &b, &c);\n\t\tok[b] = false;\n\t}\n\trep1(i, n) if(ok[i]) {\n\t\trep1(j, n) if(i != j) printf(\"%d %d\n\", i, j);\n\t\treturn;\n\t}\n}\n\nint main()\n{\n\tint T;\n\tscanf(\"%d\", &T);\n\twhile(T --) solve();\n\treturn 0;\n}"
