        "Default_Solution": "/**\n *    author:  tourist\n *    created: 28.11.2021 17:38:41       \n**/\n#include <bits/stdc++.h>\n\nusing namespace std;\n\nint main() {\n  ios::sync_with_stdio(false);\n  cin.tie(0);\n  const int M = (int) 1e6 + 10;\n  vector<bool> pr(M, true);\n  pr[0] = pr[1] = false;\n  for (int i = 2; i < M; i++) {\n    if (pr[i]) {\n      for (int j = i + i; j < M; j += i) {\n        pr[j] = false;\n      }\n    }\n  }\n  int tt;\n  cin >> tt;\n  while (tt--) {\n    int n, e;\n    cin >> n >> e;\n    vector<int> a(n);\n    for (int i = 0; i < n; i++) {\n      cin >> a[i];\n    }\n    vector<int> L(n);\n    vector<int> R(n);\n    for (int z = 0; z < e; z++) {\n      int i = z;\n      int cc = 0;\n      while (i < n) {\n        if (a[i] > 1) {\n          L[i] = cc + 1;\n          cc = 0;\n        } else {\n          cc += 1;\n        }\n        i += e;\n      }\n      cc = 0;\n      i -= e;\n      while (i >= 0) {\n        if (a[i] > 1) {\n          R[i] = cc + 1;\n          cc = 0;\n        } else {\n          cc += 1;\n        }\n        i -= e;\n      }\n    }\n    long long ans = 0;\n    for (int i = 0; i < n; i++) {\n      if (pr[a[i]]) {\n        ans += L[i] * 1LL * R[i] - 1;\n      }\n    }\n    cout << ans << '\n';\n  }\n  return 0;\n}\n"
