    "Cow and Fields": {
        "Default_Solution": "#include <bits/stdc++.h>\nusing namespace std;\n#define rep(i,a,n) for (int i=a;i<n;i++)\n#define per(i,a,n) for (int i=n-1;i>=a;i--)\n#define pb push_back\n#define mp make_pair\n#define all(x) (x).begin(),(x).end()\n#define fi first\n#define se second\n#define SZ(x) ((int)(x).size())\ntypedef vector<int> VI;\ntypedef long long ll;\ntypedef pair<int,int> PII;\ntypedef double db;\nmt19937 mrand(random_device{}()); \nconst ll mod=1000000007;\nint rnd(int x) { return mrand() % x;}\nll powmod(ll a,ll b) {ll res=1;a%=mod; assert(b>=0); for(;b;b>>=1){if(b&1)res=res*a%mod;a=a*a%mod;}return res;}\nll gcd(ll a,ll b) { return b?gcd(b,a%b):a;}\n// head\n \nconst int N=201000;\nint q[N],vis[N],d1[N],d2[N];\nint n,m,k,spe[N],u,v;\nVI e[N];\n \nvoid bfs(int s,int *d) {\n\trep(i,1,n+1) vis[i]=0,d[i]=n+1;\n\tint t=0;\n\tvis[s]=1; d[s]=0;\n\tq[t++]=s;\n\trep(i,0,t) {\n\t\tint u=q[i];\n\t\tfor (auto v:e[u]) if (d[v]>d[u]+1) {\n\t\t\td[v]=d[u]+1;\n\t\t\tq[t++]=v;\n\t\t}\n\t}\n}\n \nint main() {\n\tscanf(\"%d%d%d\",&n,&m,&k);\n\trep(i,0,k) scanf(\"%d\",spe+i);\n\trep(i,0,m) {\n\t\tscanf(\"%d%d\",&u,&v);\n\t\te[u].pb(v); e[v].pb(u);\n\t}\n\tbfs(1,d1);\n\tbfs(n,d2);\n\tsort(spe,spe+k,[&](int a,int b) {\n\t\treturn d1[a]-d2[a]<d1[b]-d2[b];\n\t});\n\tint ans=0;\n\trep(i,1,k) {\n\t\tans=max(ans,d1[spe[i-1]]+d2[spe[i]]+1);\n\t\t//assert(d1[spe[i-1]]+d2[spe[i]]+1<=d2[spe[i-1]]+d1[spe[i]]+1);\n\t}\n\tans=min(ans,d1[n]);\n\tprintf(\"%d\n\",ans);\n}"
    },
