        "Default_Solution": "#include<bits/stdc++.h>\n\n#define fo(i,a,b) for(int i=a;i<=b;i++)\n#define fd(i,a,b) for(int i=a;i>=b;i--)\n\nusing namespace std;\n\ntypedef long long LL;\ntypedef double db;\n\nint get(){\n    char ch;\n    while(ch=getchar(),(ch<'0'||ch>'9')&&ch!='-');\n    if (ch=='-'){\n        int s=0;\n        while(ch=getchar(),ch>='0'&&ch<='9')s=s*10+ch-'0';\n        return -s;\n    }\n    int s=ch-'0';\n    while(ch=getchar(),ch>='0'&&ch<='9')s=s*10+ch-'0';\n    return s;\n}\n\nconst int N = 3e5+5;\n\nchar s[N];\nint n,T;\n\nint main(){\n    for(T=get();T;T--){\n        scanf(\"%s\",s+1);\n        n=strlen(s+1);\n        int pos=-1;\n        fo(i,1,n)\n        if (s[i]!='a'){\n            pos=i;\n            break;\n        }\n        if (pos==-1){\n            printf(\"NO\n\");\n        }\n        else{\n            printf(\"YES\n\");\n            if (pos*2<=n){\n                int p=n-(pos-1)+1;\n                fo(i,1,p-1)putchar(s[i]);\n                putchar('a');\n                fo(i,p,n)putchar(s[i]);\n                putchar('\n');\n            }\n            else{\n                int p=n-pos;\n                fo(i,1,p)putchar(s[i]);\n                putchar('a');\n                fo(i,p+1,n)putchar(s[i]);\n                putchar('\n');\n            }\n        }\n    }\n    return 0;\n}"
