        "Default_Solution": "//program 300-C\n\n#include<iostream>\n#include<cstdio>\n#include<cstdlib>\n#include<cstring>\n#include<algorithm>\n\nusing namespace std;\n\nint Get()\n{\n  char c;\n  while(c=getchar(),c<'0'||c>'9');\n  int X=0;\n  while(c>='0'&&c<='9')\n    {\n      X=X*10+c-48;\n      c=getchar();\n    }\n  return X;\n}\n\nconst int Mod=1000000007;\n\nlong long Fac[1000001],Rev[1000001];\n\nlong long Pow(long long A,long long B)\n{\n  if(!B)\n    return 1;\n  long long T=Pow(A*A%Mod,B/2);\n  if(B&1)\n    T=T*A%Mod;\n  return T;\n}\n\nbool Good(int S,int A,int B)\n{\n  if(!S)\n    return true;\n  if(S%10!=A&&S%10!=B)\n    return false;\n  return Good(S/10,A,B);\n}\n\nlong long C(int N,int M)\n{\n  return Fac[N]*Rev[M]%Mod*Rev[N-M]%Mod;\n}\n\nint main()\n{\n  int A=Get(),B=Get(),N=Get(),Ans=0;\n  Fac[0]=1;\n  for(int i=1;i<=N;i++)\n    Fac[i]=Fac[i-1]*i%Mod;\n  for(int i=0;i<=N;i++)\n    Rev[i]=Pow(Fac[i],Mod-2);\n  for(int i=0;i<=N;i++)\n    {\n      int Sum=i*A+(N-i)*B;\n      if(!Good(Sum,A,B))\n        continue;\n      Ans=(Ans+C(N,i))%Mod;\n    }\n  printf(\"%d\n\",Ans);\n  return 0;\n}\n"
