        "Default_Solution": "#include <bits/stdc++.h>\n\nusing namespace std;\n\ntypedef long long ll;\ntypedef pair<ll,ll> ii;\ntypedef vector<int> vi;\n\n#define fi first\n#define se second\n#define mp make_pair\n#define pb push_back\n\n#define unrequited_love ios_base::sync_with_stdio(0);cin.tie(0);\n\nvoid solve(vi a)\n{\n\tint n=a.size();\n\tsort(a.rbegin(), a.rend());\n\tint k = 1;\n\twhile (k + 1 <= n && a[k] >= k + 1) {\n\t\tk += 1;\n\t}\n\tint up = a[k - 1] - k;\n\tint right = 0;\n\twhile (k + right < n && a[k + right] == k) {\n\t\t++right;\n\t}\n\tcout << (up % 2 == 0 && right % 2 == 0 ? \"Ashish\" : \"Utkarsh\") << '\n';\n}\n\nint main()\n{\n\tunrequited_love\n\tint t; cin>>t;\n\twhile(t--)\n\t{\n\t\tll d,k; cin>>d>>k;\n\t\tll bestr = (d*d)/(k*k);\n\t\tvi ans;\n\t\tll cur=0;\n\t\twhile(cur*cur<=bestr)\n\t\t{\n\t\t\tll rem = bestr-cur*cur;\n\t\t\tll ps = max(ll(floor(sqrt(double(rem))))-1,0LL);\n\t\t\twhile((ps+1)*(ps+1)<=rem) ps++;\n\t\t\t//cerr<<\"CUR, PS = \"<<cur<<' '<<ps<<'\n';\n\t\t\tans.pb(ps);\n\t\t\tcur++;\n\t\t}\n\t\t/*\n\t\tfor(int x:ans)\n\t\t{\n\t\t\tcout<<x<<' ';\n\t\t}\n\t\tcout<<'\n';\n\t\t*/\n\t\tsolve(ans);\n\t}\n}\n"
