        "Default_Solution": "#include<bits/stdc++.h>\n\nusing namespace std;\n\n#define ll  long long\n#define ld  double\n\n#define sz(x)   (int)x.size()\n#define all(x)  x.begin(),x.end()\n\n#define pb  emplace_back\n#define X   first\n#define Y   second\n\nconst int   N   = 2e5 + 5;\n\ntypedef pair<int,int>   ii;\n\nint main()  {\n    ios_base::sync_with_stdio(0);\n    cin.tie(0); cout.tie(0);\n\n    int n;  cin >> n;\n    int m;  cin >> m;\n    int k;  cin >> k;\n\n    vector<int> row;\n    vector<int> col;\n\n    for(int i = 0 ; i < n ; ++i)    {\n        int x;  cin >> x;\n        if (x)  row.pb(i);\n    }\n    for(int j = 0 ; j < m ; ++j)    {\n        int x;  cin >> x;\n        if (x)  col.pb(j);\n    }\n\n    ll  ans = 0;\n\n    auto cal = [&](int R,int C) {\n        int cnt0 = 0;\n        int cnt1 = 0;\n        for(int i = R - 1 ; i < sz(row) ; ++i)  if (row[i - R + 1] == row[i] - R + 1)   cnt0++;\n        for(int i = C - 1 ; i < sz(col) ; ++i)  if (col[i - C + 1] == col[i] - C + 1)   cnt1++;\n\n        ans += 1ll * cnt0 * cnt1;\n    };\n\n    for(int i = 1 ; i * i <= k ; ++i)   if (k % i == 0) {\n        cal(i,k / i);\n        if (i * i < k)\n            cal(k / i,i);\n    }\n    cout << ans << endl;\n}"
