        "Default_Solution": "#include<bits/stdc++.h>\n\nusing namespace std;\n\nint a[2005], cnt[1005], used[2005], lst[1005];\n\nmain() {\n    ios_base::sync_with_stdio(0);\n    cin.tie(0);\n    cout.tie(0);\n    int t;\n    cin >> t;\n    vector < int > primes;\n    for (int i = 2; i <= 1000; ++i) {\n        int ok = 1;\n        for (int j = 2; j < i; ++j) if (i % j == 0) ok = 0;\n        if (ok) primes.push_back(i);\n    }\n    while (t--) {\n        int n;\n        cin >> n;\n        for (int i = 1; i <= 2 * n; ++i) used[i] = 0;\n        for (int i = 1; i <= 2 * n; ++i) cin >> a[i];\n        for (auto key : primes) {\n            for (int j = 0; j < key; ++j) cnt[j] = 0;\n            for (int i = 1; i <= 2 * n; ++i) cnt[a[i] % key]++;\n            int sum = 0;\n            for (int i = 0; i < key; ++i) {\n                if (i == 0) sum += cnt[i] / 2;\n                else if (i <= key - i) sum += min(cnt[i], cnt[key - i]);\n            }\n            if (sum >= n - 1) {\n                for (int t = 1; t <= n - 1; ++t) {\n                    for (int j = 0; j < key; ++j) lst[j] = 0;\n                    for (int i = 1; i <= 2 * n; ++i) {\n                        if (used[i]) continue;\n                        int val = (key - a[i] % key) % key;\n                        if (lst[val] != 0) {\n                            cout << i << \" \" << lst[val] << '\n';\n                            used[i] = 1;\n                            used[lst[val]] = 1;\n                            break;\n                        }\n                        lst[a[i] % key] = i;\n                    }\n                }\n                break;\n            }\n        }\n    }\n    return 0;\n}\n\n"
