        "Default_Solution": "#include <bits/stdc++.h> \nusing namespace std;\n#define fl(i,a,b) for(int i=a;i<b;i++)\n#define ff first\n#define ss second\n#define endl '\n'\n#define pb push_back\n#define khushi ios_base::sync_with_stdio(0);cin.tie(NULL);cout.tie(NULL);\ntypedef long long ll;\nconst int  mod  = 1000000007;\n#define int long long\nconst int mx = 200005;\nvoid f()\n{\n\tint n,k;\n\tcin >> n >> k;\n\tstring s;\n\tcin >> s; \n\tint nxt[n + 1];\n\tnxt[n] = 1e9;\n\tfor(int i = s.size() - 1; i >=0 ; i--)\n\t{\n\t\tif(s[i] == '1')\n\t\t{\n\t\t\tnxt[i] = i;\n\t\t}\n\t\telse nxt[i] = nxt[i + 1];\n\t}\n\tint pre = -1e9;\n\tint ans = 0;\n\tfl(i,0,n)\n\t{\n\t\tif(s[i] == '1')\n\t\t{\n\t\t\tpre = i;\n\t\t}\n\t\tif(pre < i - k && nxt[i] > i + k)\n\t\t{\n\t\t\tans++;\n\t\t\tpre = i;\n\t\t}\n\t}\n\tcout << ans << endl;\n}\nmain()\n{\n\tkhushi;\n\tint t = 1;\n\tcin >> t;\n\twhile(t--)\n\t{\n\t\tf();\n\t}\n}"
