        "Default_Solution": "#include<bits/stdc++.h>\nusing namespace std;\nstruct item{\n\tlong long a,b;\n};\nvoid solve(){\n\tlong long n,i,j=-1,k,mxm=-1;\n\tcin>>n;\n\tn*=2;\n\tlong long a[n];\n\tfor(i=0;i<n;i++){\n\t\tcin>>a[i];\n\t}\n\tfor(i=0;i<n;i++){\n\t\tif(mxm<a[i]){\n\t\t\tmxm=a[i];\n\t\t\tj=i;\n\t\t}\n\t}\n\tfor(i=0;i<n;i++){\n\t\tif(j==i){\n\t\t\tcontinue;\n\t\t}\n\t\tvector<item> bucket;\n\t\tmultiset<long long> ms;\n\t\tfor(k=0;k<n;k++){\n\t\t\tms.insert(a[k]);\n\t\t}\n\t\tlong long x=mxm+a[i],f=1;\n\t\twhile(ms.empty()==false){\n\t\t\tlong long mx=*ms.rbegin();\n\t\t\tms.erase(ms.find(mx));\n\t\t\tif(ms.find(x-mx)==ms.end()){\n\t\t\t\tf=0;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\tms.erase(ms.find(x-mx));\n\t\t\titem it;\n\t\t\tit.a=mx,it.b=x-mx;\n\t\t\tbucket.emplace_back(it);\n\t\t\tswap(x,mx);\n\t\t}\n\t\tif(f){\n\t\t\tcout<<\"YES\"<<endl;\n\t\t\tcout<<mxm+a[i]<<endl;\n\t\t\tfor(item it:bucket)\n\t\t\t\tcout<<it.a<<' '<<it.b<<endl;\n\t\t\treturn;\n\t\t}\n\t}\n\tcout<<\"NO\"<<endl;\n}\nint main(){\n\tios_base::sync_with_stdio(0);\n\tcin.tie(NULL);\n\tcout.tie(NULL);\n\tlong long t=1;\n\tcin>>t;\n\twhile(t--){\n\t\tsolve();\n\t}\n\treturn 0;\n}"
