        "Default_Solution": "#include <cstdio>\n#include <cstdlib>\n#include <cstring>\n#include <algorithm>\n\nusing namespace std;\n\nconst int kMaxX = 10000000, kMaxP = 664579;\nint n, pr[kMaxP + 1];\nbool not_pr[kMaxX + 1];\nint sum[kMaxX + 1];\n\nvoid init() {\n    for (int i = 2; i <= kMaxX; ++ i) {\n        if (!not_pr[i]) pr[++ pr[0]] = i;\n        for (int j = 1, k; j <= pr[0] && (k = pr[j] * i) <= kMaxX; ++ j) {\n            not_pr[k] = true;\n            if (i % pr[j] == 0) break;\n        }\n    }\n}\n\nint main() {\n    init();\n    scanf(\"%d\", &n);\n    for (int x; n --; ) {\n        scanf(\"%d\", &x);\n        for (int i = 1; pr[i] * pr[i] <= x; ++ i)\n            if (x % pr[i] == 0) {\n                ++ sum[pr[i]];\n                while (x % pr[i] == 0) x /= pr[i];\n            }\n        if (x != 1) ++ sum[x];\n    }\n    for (int i = 3; i <= kMaxX; ++ i) sum[i] += sum[i - 1];\n    scanf(\"%d\", &n);\n    for (int l, r; n --; ) {\n        scanf(\"%d%d\", &l, &r);\n        l = min(l, kMaxX);\n        r = min(r, kMaxX);\n        printf(\"%d\n\", sum[r] - sum[l - 1]);\n    }\n    return 0;\n}\n"
