        "Default_Solution": "#ifdef LOCAL\n#define _GLIBCXX_DEBUG\n#endif\n#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\nusing ld = long double;\nconst ll INF = LLONG_MAX, MOD = 1e9 + 7, P = 239;\nconst ld PI = 3.1415926535897938462643383279502, EPS = 1e-7;\n\ntemplate <typename T>\ninline ll sz(const T &a) {\n    return a.size();\n}\n\ntemplate <typename T, typename C>\nistream &operator >> (istream &in, pair<T, C> &a) {\n    return in >> a.first >> a.second;\n}\n\ntemplate <typename T, typename C>\nostream &operator << (ostream &out, pair<T, C> a) {\n    return out << a.first << ' ' << a.second;\n}\n\ntemplate <typename T>\nistream & operator >> (istream &in, vector<T> &a) {\n    for (auto &i : a) {\n        in >> i;\n    }\n    return in;\n}\n\ntemplate <typename T>\nostream &operator << (ostream &out, vector<T> a) {\n    for (auto i : a) {\n        out << i << ' ';\n    }\n    return out;\n}\n\ntemplate <typename T>\nvoid print(vector<T> a, string c = \"\n\") {\n    for (T i : a) {\n        cout << i << c;\n    }\n}\n\nvoid solve() {\n    ll n, x;\n    cin >> n >> x;\n    vector<ll> p(n + 1);\n    for (int i = 1; i <= n; ++i) {\n        cin >> p[i];\n    }\n    ll pos = -1;\n    for (int i = 1; i <= n; ++i) {\n        if (p[i] == x) {\n            pos = i;\n        }\n    }\n    ll l = 1, r = n + 1;\n    vector<bool> change(n + 1), tryed(n + 1);\n//    while (r - l > 1) {\n//        ll m = (r + l) / 2;\n//        tryed[m] = true;\n//        if (p[m] <= x) {\n//            l = m;\n//            if (pos < m) {\n//                change[m] = true;\n//                r = m;\n//            }\n//        } else {\n//            r = m;\n//            if (pos >= m) {\n//                change[m] = true;\n//                l = m;\n//            }\n//        }\n//    }\n//    vector<ll> nc;\n//    for (int i = 1; i <= n; ++i) {\n//        if (change[i]) {\n//            nc.push_back(i);\n//        }\n//    }\n    while (r - l > 1) {\n        ll m = (r + l) / 2;\n        tryed[m] = true;\n        if (p[m] <= x) {\n            l = m;\n        } else {\n            r = m;\n        }\n    }\n    ll last = l;\n    if (last == pos) {\n        return void(cout << 0);\n    }\n    vector<pair<int, int>> ans;\n    ans.push_back({pos, l});\n    if (tryed[pos]) {\n        for (int i = 1; i <= n; ++i) {\n            if (p[i] <= x && !tryed[i]) {\n                ans.push_back({i, pos});\n                break;\n            }\n        }\n    }\n    cout << sz(ans) << '\n';\n    print(ans);\n}\n\nsigned main() {\n#ifdef LOCAL\n    freopen(\"inp.txt\", \"r\", stdin);\n    freopen(\"out.txt\", \"w\", stdout);\n    freopen(\"err.txt\", \"w\", stderr);\n\n    auto start_time = clock();\n#endif\n    ios_base::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int times = 1;\n    cin >> times;\n    while (times--)\n        solve(), cout << '\n';\n\n#ifdef LOCAL\n    auto end_time = clock();\n    cerr << setprecision(3) << fixed << \"Execution time: \" << (end_time - start_time) * (int) 1e3 / CLOCKS_PER_SEC << \" ms\n\";\n#endif\n    return 0;\n}\n"
