        "Default_Solution": "#include<bits/stdc++.h>\nusing namespace std;\ntypedef long long LL;\nstruct cave{\n\tLL siz,val;\n\tcave(){}\n\tcave(LL S,LL V){siz=S,val=V;}\n\tbool operator < (cave ano) const {return val<ano.val || (val==ano.val && siz>ano.siz);}\n}a[100005];\nLL n;\nvoid Solve()\n{\n\tscanf(\"%lld\",&n);\n\tfor(LL i=1;i<=n;++i)\n\t{\n\t\tLL siz;\n\t\tscanf(\"%lld\",&siz);\n\t\tLL val=0;\n\t\tfor(LL j=1;j<=siz;++j)\n\t\t{\n\t\t\tLL s;\n\t\t\tscanf(\"%lld\",&s);\n\t\t\tval=max(val,s-j+2);\n\t\t}\n\t\ta[i]=cave(siz,val);\n\t}\n\tsort(a+1,a+1+n);\n\tLL ans=a[1].val,pos=a[1].val+a[1].siz;\n\tfor(LL i=2;i<=n;++i)\n\t{\n\t\tif(pos>a[i].val)\tpos+=a[i].siz;\n\t\telse\tans+=a[i].val-pos,pos=a[i].val+a[i].siz;\n\t}\n\tprintf(\"%lld\n\",ans);\n}\nint main(){\n\tLL T;\n\tscanf(\"%lld\",&T);\n\twhile(T-->0)\tSolve();\n\treturn 0;\n}"
