        "Default_Solution": "#include <cstdio>\n#include <cstdlib>\n#include <cstring>\n#include <ctime>\n#include <cmath>\n#include <iostream>\n#include <algorithm>\n\nusing namespace std;\n\nint n, m, f[1000001], A, B;\nchar str[1000011];\nbool b[1000001];\n\nint main(){\n    // freopen(\"c.in\", \"r\", stdin);\n    // freopen(\"c.out\", \"w\", stdout);\n     scanf(\"%s\", str + 1);\n     n = strlen(str + 1);\n     if (str[1] == '0')\n     {\n          printf(\"NO\n\");\n          return 0;\n     }\n     scanf(\"%d%d\", &A, &B); \n     memset(b, false, sizeof(b));\n     for (int i = 1, j = 0; i <= n; i++)\n     {\n          j = (j * 10 + str[i] - '0') % A;\n          if (!j) b[i] = true;\n     }\n     f[0] = 1;\n     for (int i = 1; i <= n; i++) f[i] = f[i - 1] * 10 % B;\n     for (int i = n, j = 0; i > 1; --i)\n     {\n          j += f[n - i] * (str[i] - '0') % B;\n          j %= B;\n          if (!j && str[i] != '0' && b[i - 1])\n          {\n               printf(\"YES\n\");\n               for (int k = 1; k < i; k++) printf(\"%c\", str[k]);\n               printf(\"\n\");\n               for (int k = i; k <= n; k++) printf(\"%c\", str[k]);\n               printf(\"\n\");\n               return 0;\n          }\n     }\n     printf(\"NO\n\");\n     return 0;\n}\n"
