        "Default_Solution": "#include <bits/stdc++.h>\nusing namespace std;\n#define ff first\n#define ss second\n#define rep(i, a, b) for(int i = a; i < (b); ++i)\n#define all(x) begin(x), end(x)\n#define sz(x) (int)(x).size()\n#define pb push_back\n#define FASTIO ios_base::sync_with_stdio(false);cin.tie(0);cout.tie(0);\n#define endl '\n'\n//#define int long long\ntypedef long long ll;\ntypedef pair<int, int> pii;\ntypedef vector<ll> vl;\ntypedef vector<pii> vpi;\ntypedef pair<ll,ll> pll;\ntypedef vector<string> vs;\ntypedef vector<pll> vpl;\ntypedef vector<int> vi;\n\nconst int N = 100100;\nvi g[N];\nint tam[N];\n\n\nvi centroid;\nint n;\nvoid dfs1(int v,int p = -1){\n  tam[v] = 1;\n  bool is= 1;\n\n  for(int to : g[v])if(to!=p){\n    dfs1(to,v);\n    tam[v]+=tam[to];\n    if(tam[to] > n/2)is = 0;\n  }\n  if(n - tam[v] > n/2)is = 0;\n  if(is)centroid.pb(v);\n}\n\n\n\nvoid solve(){\n  cin >> n;\n  for(int i=1;i<=n;i++)g[i].clear(),tam[i] = 1;\n\n  for(int i=1;i<n;i++){\n    int a,b;\n    cin>>a>>b;\n    g[a].pb(b);\n    g[b].pb(a);\n  } \n  centroid.clear();\n  dfs1(1);\n  vector<pii> ans;\n  if(sz(centroid) == 1){\n    int to = g[1][0];\n    ans.pb(pii(1,to));\n    ans.pb(pii(1,to));\n  }else{\n    for(int to : g[centroid[0]]){\n      if(to!=centroid[1]){\n        ans.pb(pii(centroid[0],to));\n        ans.pb(pii(to,centroid[1]));\n        break;\n      }\n    }\n  }\n  assert(sz(ans) == 2);\n  for(auto it : ans){\n    cout << it.ff<<\" \"<<it.ss<<endl;\n  }\n}\n\nint32_t main(){\n  FASTIO;\n  int t;\n  cin >> t;\n  while(t--){\n    solve();\n  }\n}"
