        "Default_Solution": "// Problem: C. Need for Pink Slips\n// Contest: Codeforces - Codeforces Round #730 (Div. 2)\n// URL: https://codeforces.com/contest/1543/problem/C\n// Memory Limit: 256 MB\n// Time Limit: 1000 ms\n// \n// Powered by CP Editor (https://cpeditor.org)\n\n//And in that light,I find deliverance.\n#include<bits/stdc++.h>\nusing namespace std;\n#define int long long\ninline int read(){\n   int s=0,w=1;\n   char ch=getchar();\n   while(ch<'0'||ch>'9'){if(ch=='-')w=-1;ch=getchar();}\n   while(ch>='0'&&ch<='9') s=s*10+ch-'0',ch=getchar();\n   return s*w;\n}\ndouble dfs(double a,double b,double c,double v,int s,double p)\n{\n\tdouble res=0;\n\tres+=p*c*s;\n\tif(a>1e-9)\n\tif(a<v) \n\t{\n\t\tif(b>1e-9)\n\t\tres+=dfs(0,b+a/2.0,c+a/2.0,v,s+1,p*a);\n\t\telse res+=p*a*(s+1);\n\t}\n\telse \n\t{\n\t\tif(b>1e-9)\n\t\tres+=dfs(a-v,b+v/2.0,c+v/2.0,v,s+1,p*a);\n\t\telse \n\t\tres+=dfs(a-v,0,c+v,v,s+1,p*a);\n\t}\n\tif(b>1e-9)\n\tif(b<v) \n\t{\n\t\tif(a>1e-9)\n\t\tres+=dfs(a+b/2.0,0,c+b/2.0,v,s+1,p*b);\n\t\telse res+=p*b*(s+1);\n\t}\n\telse \n\t{\n\t\tif(a>1e-9)\n\t\tres+=dfs(a+v/2.0,b-v,c+v/2.0,v,s+1,p*b);\n\t\telse \n\t\tres+=dfs(0,b-v,c+v,v,s+1,p*b);\n\t}\n\treturn res;\n}\nsigned main()\n{\n\tfor(int T=read();T--;)\n\t{\n\t\tdouble a,b,c,v;\n\t\tdouble ans=0;\n\t\tcin>>a>>b>>c>>v;\n\t\tdouble cur=1;\n\t\tprintf(\"%.10lf\n\",dfs(a,b,c,v,1,1.0));\n\t}\n\treturn 0;\n}"
