        "Default_Solution": "#include <cstdio>\n#include <cstring>\n#include <cstdlib>\n#include <cmath>\n#include <ctime>\n#include <cctype>\n\n#include <algorithm>\n#include <random>\n#include <bitset>\n#include <queue>\n#include <functional>\n#include <set>\n#include <map>\n#include <vector>\n#include <chrono>\n#include <iostream>\n#include <limits>\n#include <numeric>\n\n#define LOG(FMT...) fprintf(stderr, FMT)\n\nusing namespace std;\n\ntypedef long long ll;\ntypedef unsigned long long ull;\n\n// mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());\n\nconst int P = 1000000007;\n\nint mpow(int x, ll k, int p = P) {\n  int ret = 1;\n  while (k) {\n    if (k & 1)\n      ret = ret * (ll)x % p;\n    x = x * (ll)x % p;\n    k >>= 1;\n  }\n  return ret;\n}\n\nint main() {\n#ifdef LBT\n  freopen(\"test.in\", \"r\", stdin);\n  int nol_cl = clock();\n#endif\n\n  int x;\n  ll n;\n\n  scanf(\"%d%lld\", &x, &n);\n  int y = x;\n  int ans = 1;\n  function<void(int, int)> gao = [&](int p, int pk) {\n    ll v = 0, nn = n;\n    while (nn) {\n      v += (nn /= p);\n    }\n    ans = ans * (ll)mpow(p, v) % P;\n  };\n  for (int v = 2; v * v <= y; ++v)\n    if (y % v == 0) {\n      int pk = 1;\n      while (y % v == 0) {\n        y /= v;\n        pk *= v;\n      }\n      gao(v, pk);\n    }\n  if (y != 1)\n    gao(y, y);\n  printf(\"%d\n\", ans);\n\n#ifdef LBT\n  LOG(\"Time: %dms\n\", int ((clock()\n          -nol_cl) / (double)CLOCKS_PER_SEC * 1000));\n#endif\n  return 0;\n}\n"
