        "Default_Solution": "#include <bits/stdc++.h>\nusing namespace std;\n#define rep(i,n) for(int i=0;i<n;i++)\n#define rep2(i,n) for(int i=1;i<=n;i++)\ntypedef pair<int,int> P;\nset<pair<deque<int>,int> >se;\nint win;\nint go(deque<int>a,deque<int>b,deque<int>c,int t){\n//rep(i,a.size()) cout << a[i] << \" \" ; cout << endl;\n\tif(se.find(make_pair(c,a.size())) != se.end()) return -1;\n\tse.insert(make_pair(c,a.size()));\n\tif(a.empty()){\n\t\twin = 2; return t;\n\t}\n\tif(b.empty()){\n\t\twin = 1; return t;\n\t}\n\tint x = a[0];\n\tint y = b[0];\n\tif(x < y){\n\t\ta.pop_front(); b.pop_front();\n\t\tb.push_back(x); b.push_back(y);\n\t\t//swap(b[b.size()-2],b[b.size()-1]);\n\t}\n\telse{\n\t\tb.pop_front(); a.pop_front();\n\t\ta.push_back(y); a.push_back(x);\n\t\t//swap(a[a.size()-2],a[a.size()-1]);\n\t}\n\tdeque<int>C;\n\trep(i,a.size()) C.push_back(a[i]);\n\trep(i,b.size()) C.push_back(b[i]);\n\treturn go(a,b,C,t+1);\n}\nint main(){\n    int n;\n    deque<int>va,vb,vc;\n    cin >> n;\n    int a; cin >> a; \n    rep(i,a){\n    \tint x; cin >> x; va.push_back(x); vc.push_back(x);\n    }\n    int b; cin >> b; \n    rep(i,b){\n    \tint x; cin >> x; vb.push_back(x); vc.push_back(x);\n    }\n    int p = go(va,vb,vc,0);\n    if(p==-1) cout << -1 << endl;\n    else cout << p << \" \" << win << endl;\n   }"
