    "505": {
        "Default_Solution": "#include <bits/stdc++.h>\n\nusing namespace std;\n\nconst int k_N = 1e6 + 3;\n\nint n, m;\npair<int, bool> dp[k_N][1 << 3];\nstring s[3];\n\nbool check(int mask, int new_mask){\n    int cnt = 0;\n    for(int i = 0; i < 2; ++i){\n        cnt += (bool)(mask & (1 << i));\n        cnt += (bool)(new_mask & (1 << i));\n    }\n\n    if(cnt % 2 == 0) return false;\n    if(n == 2) return true;\n\n    cnt = 0;\n    for(int i = 1; i < 3; ++i){\n        cnt += (bool)(mask & (1 << i));\n        cnt += (bool)(new_mask & (1 << i));\n    }\n\n    return cnt & 1;\n}\n\nint solve(int pos, int mask){\n    if(pos == m) return 0;\n\n    auto &[ans, solved] = dp[pos][mask];\n    if(solved) return ans;\n\n    solved = true, ans = k_N;\n\n    for(int new_mask = 0; new_mask < (1 << n); ++new_mask){\n        if(pos == 0 || check(mask, new_mask)){\n            int add = 0;\n            for(int i = 0; i < n; ++i){\n                int x = (bool)(new_mask & (1 << i));\n                if(x != s[i][pos] - '0') add++;\n            }\n            ans = min(ans, solve(pos + 1, new_mask) + add);\n        }\n    }\n\n    return ans;\n}\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(NULL);\n\n    cin >> n >> m;\n\n    if(n >= 4){\n        cout << \"-1\n\";\n        return 0;\n    }\n    if(n == 1){\n        cout << \"0\n\";\n        return 0;\n    }\n\n    for(int i = 0; i < n; ++i)\n        cin >> s[i];\n\n    int ans = k_N;\n    for(int i = 0; i < (1 << n); ++i)\n        ans = min(ans, solve(0, i));\n\n    cout << ans << \"\n\";\n}"
    },
