        "Default_Solution": "#pragma GCC optimize(\"O3\")\n#include<cstdio>\n#include<cstdlib>\n#include<cstring>\n#include<cmath>\n#include<algorithm>\n#include<functional>\n#include<vector>\n#include<queue>\n#include<stack>\n#include<set>\n#include<map>\nusing namespace std;\n#define MOD 1000000007\n#define f(i,n) for(long long i=0;i<(long long)(n);i++)\n#define N 400000\n\n\nint main() {\n\tlong long a[N];\n\tlong long b[N];\n\tlong long c[N];\n\tlong long d[N];\n\tbool used[N];\n\tvector<long long>e;\n\tf(i, N) {\n\t\ta[i] = 0;\n\t\tb[i] = 0;\n\t\tc[i] = 0;\n\t\td[i] = 0;\n\t\tused[i] = false;\n\t}\n\tlong long n, k, ans;\n\tscanf(\"%lld\", &n);\n\tf(i, n) {\n\t\tscanf(\"%lld\", &a[i]);\n\t}\n\tf(i, n) {\n\t\tscanf(\"%lld\", &b[i]);\n\t\tb[i]--;\n\t\tif (b[i] >= 0)c[b[i]]++;\n\t}\n\tans = 0;\n\tk = 0;\n\tf(i, n) {\n\t\tif (c[i] == 0) {\n\t\t\td[k] = i;\n\t\t\tk++;\n\t\t}\n\t}\n\tf(i, n) {\n\t\tans += a[d[i]];\n\t\tif (b[d[i]] >= 0) {\n\t\t\tif (a[d[i]] > 0) {\n\t\t\t\tused[d[i]] = true;\n\t\t\t\te.push_back(d[i]+1);\n\t\t\t\ta[b[d[i]]] += a[d[i]];\n\t\t\t}\n\t\t\tc[b[d[i]]]--;\n\t\t\tif (c[b[d[i]]] == 0) {\n\t\t\t\td[k] = b[d[i]];\n\t\t\t\tk++;\n\t\t\t}\n\t\t}\n\n\t}\n\tfor (int i = n - 1; i >= 0; i--) {\n\t\tif (!used[d[i]])e.push_back(d[i]+1);\n\t}\n\tprintf(\"%lld\n\", ans);\n\tf(i, n - 1)printf(\"%lld \", e[i]);\n\tprintf(\"%lld\n\", e[n - 1]);\n\treturn 0;\n}"
