        "Default_Solution": "#include <iostream>\n#include <vector>\n#include <cassert>\n#include <cmath>\n#include <map>\n\nusing namespace std;\n\n#define MIN(a, b) (((a) < (b)) ? (a) : (b))\n#define MAX(a, b) (((a) < (b)) ? (b) : (a))\n\nusing ll = long long;\nint const nmax = 3000;\nchar v[1 + nmax];\n\nvector<int> processlevel(int n){\n  vector<int> sol;\n  for(int i = 1;i < n; i++)\n    if(v[i] == 'R' && v[i + 1] == 'L')\n      sol.push_back(i);\n  for(int i = 0; i < sol.size(); i++)\n    swap(v[sol[i]], v[sol[i] + 1]);\n  return sol;\n}\n\nint main()\n{\n  int n, k;\n  cin >> n >> k;\n  for(int i = 1;i <= n; i++)\n    cin >> v[i];\n  vector<vector<int>> solbig;\n  int movesmax = 0;\n  while(true){\n    vector<int> sol = processlevel(n);\n    if(sol.size() == 0)\n      break;\n    movesmax += sol.size();\n    solbig.push_back(sol);\n  }\n  if(k < solbig.size() || movesmax < k){\n    cout << -1;\n    return 0;\n  }\n  int ptr = 0, movesmin = solbig.size();\n\n  while(movesmin < k){\n    if(solbig[ptr].size() == 0) {\n      ptr++;\n      movesmin--;\n    }\n    cout << 1 << \" \" << solbig[ptr].back() << '\n';\n    solbig[ptr].pop_back();\n    k--;\n    if(solbig[ptr].size() == 0) {\n      ptr++;\n      movesmin--;\n    }\n  }\n\n  for(int i = ptr; i < solbig.size(); i++){\n    cout << solbig[i].size() << \" \";\n    for(int j = 0; j < solbig[i].size(); j++)\n      cout << solbig[i][j] << \" \";\n    cout << '\n';\n  }\n\n  return 0;\n}\n"
