        "Default_Solution": "#include <bits/stdc++.h>\nusing namespace std;\n\ntypedef pair<int, int> pii;\n#define fst first\n#define snd second\n#define mp make_pair\n\n#define rep(i, n) for(int i = 0; i < n; ++i)\n\n#define ri(x) scanf(\"%d\", &x)\n#define rii(x,y) scanf(\"%d%d\", &x, &y)\n#define riii(x,y,z) scanf(\"%d%d%d\", &x, &y, &z)\n#define ria(a, n) rep(_, n) scanf(\"%d\", &a[_])\n\n#define pi(x) printf(\"%d\n\", x)\n#define pia(a, n) rep(_, n) printf(\"%d%c\", a[_], _==n-1?'\n': ' ')\n\n#define Ttimes int T; scanf(\"%d\", &T); while(T--)\n\nconst int maxn = 100000 + 10;\n\nint main() {\n    string s; cin >> s;\n    long long c[2][2]={{}};\n    for(int i = 0; i < s.length(); ++i) {\n        int j = i&1;\n        int k = s[i]-'a';\n        c[j][k]++;\n    }\n\n\n    long long a1 = 0, a2 = 0;\n    for(int i = 0; i < 2; ++i)\n        for(int j = 0; j < 2; ++j) {\n            a1 += c[i][j] * (c[i][j] - 1) / 2;\n            a1 += c[i][j];\n        }\n    a2 += c[0][0] * c[1][0];\n    a2 += c[0][1] * c[1][1];\n\n    cout << a2 << ' ' << a1 << endl;\n    return 0;\n}"
