        "Default_Solution": "#include <bits/stdc++.h>\nusing namespace std;\n \n#define IOS ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n#define endl \"\n\"\n#define ll long long\n\nconst int mxN=1e5, M=1e9+7;\nstring s;\nint q, c2i[256], c[52], n;\nll dp1[53][mxN/2+1], dp2[53][mxN/2+1], iv[mxN+1], f1[mxN+1], f2[mxN+1], ans[52][52], dp3[53][mxN/2+1];\n\nint32_t main()\n{\n\tIOS;\n\tfor(int i=0; i<26; ++i) {\n\t\tc2i['a'+i]=i;\n\t\tc2i['A'+i]=i+26;\n\t}\n\tcin >> s;\n\tn=s.size();\n\tfor(char ci : s)\n\t\t++c[c2i[ci]];\n\tiv[1]=1;\n\tfor(int i=2; i<=n; ++i)\n\t\tiv[i]=M-M/i*iv[M%i]%M;\n\tf1[0]=1;\n\tf2[0]=1;\n\tfor(int i=1; i<=n; ++i) {\n\t\tf1[i]=f1[i-1]*i%M;\n\t\tf2[i]=f2[i-1]*iv[i]%M;\n\t}\n\tdp1[0][0]=dp2[52][0]=1;\n\tfor(int i=0; i<52; ++i) {\n\t\tfor(int j=0; j<=n/2; ++j) {\n\t\t\tif(j+c[i]<=n/2&&c[i]) {\n\t\t\t\tdp1[i+1][j+c[i]]=(dp1[i+1][j+c[i]]+dp1[i][j])%M;\n\t\t\t}\n\t\t\tdp1[i+1][j]=(dp1[i+1][j]+dp1[i][j])%M;\n\t\t}\n\t}\n\tfor(int i=51; i>=0; --i) {\n\t\tfor(int j=0; j<=n/2; ++j) {\n\t\t\tif(j+c[i]<=n/2&&c[i]) {\n\t\t\t\tdp2[i][j+c[i]]=(dp2[i][j+c[i]]+dp2[i+1][j])%M;\n\t\t\t}\n\t\t\tdp2[i][j]=(dp2[i][j]+dp2[i+1][j])%M;\n\t\t}\n\t}\n\t//cout << dp2[2][2] << endl;\n\tll mult=f1[n/2]*f1[n/2]%M;\n\tfor(int i=0; i<52; ++i)\n\t\tmult=mult*f2[c[i]]%M;\n\tfor(int i=0; i<52; ++i) {\n\t\tmemcpy(dp3[i+1], dp1[i], sizeof(dp1[0]));\n\t\tfor(int j=i+1; j<52; ++j) {\n\t\t\tfor(int k=0; k<=n/2; ++k)\n\t\t\t\tans[i][j]=(ans[i][j]+dp3[j][k]*dp2[j+1][n/2-k])%M;\n\t\t\t//if(!i)\n\t\t\t//cout << ans[i][j] << endl;\n\t\t\tans[i][j]=2*ans[i][j]*mult%M;\n\t\t\tmemset(dp3[j+1], 0, sizeof(dp1[0]));\n\t\t\tfor(int k=0; k<=n/2; ++k) {\n\t\t\t\tif(k+c[j]<=n/2&&c[j]) {\n\t\t\t\t\tdp3[j+1][k+c[j]]=(dp3[j+1][k+c[j]]+dp3[j][k])%M;\n\t\t\t\t}\n\t\t\t\tdp3[j+1][k]=(dp3[j+1][k]+dp3[j][k])%M;\n\t\t\t}\n\t\t}\n\t}\n\tcin >> q;\n\twhile(q--) {\n\t\tint xi, yi;\n\t\tcin >> xi >> yi, --xi, --yi;\n\t\txi=c2i[s[xi]];\n\t\tyi=c2i[s[yi]];\n\t\tif(xi==yi) {\n\t\t\tcout << dp1[52][n/2]*mult%M << \"\n\";\n\t\t\tcontinue;\n\t\t}\n\t\tif(xi>yi)\n\t\t\tswap(xi, yi);\n\t\tcout << ans[xi][yi] << \"\n\";\n\t}\n\treturn 0;\n}\n"
