        "Default_Solution": "#include <utility>\n#include <iostream>\n#include <cmath>\n#include <deque>\n#include <string>\n#include <time.h>\n#include <stack>\n#include <vector>\n#include <map>\n#include <set>\n#include <sstream>\n#include <algorithm>\n#include <bitset>\n#include <stdint.h>\n\n#define pii pair<ll,ll>\n#define X first\n#define Y second\n#define mp make_pair\n\ntypedef long long ll;\nusing namespace std;\n#define MAXN 200500\n#define MOD 998244353\n#define OFF 2001\nll n, x, k, z, m, pos, q, ans_v, y;\nll x1, p1, x2;\nll b[MAXN], c[MAXN];\npii a[MAXN];\nvector<ll> f;\nvector<ll> g[MAXN];\nstring s;\nll ask(string s) {\n    cout << s << endl;\n    fflush(stdout);\n    ll x;\n    cin >> x;\n    if (x == 0) {\n        exit(0);\n    }\n    return x;\n}\nint main() {\n    ios_base::sync_with_stdio(false); cin.tie(0);\n    ll numa, numb;\n    for (int i = 0; i < 300; i++) {\n        cout << \"a\";\n    }\n    cout << endl;\n    fflush(stdout);\n    cin >> numa;\n    if (numa == 0) {\n        return 0;\n    }\n\n    numa = 300 - numa;\n\n    for (int i = 0; i < 300; i++) {\n        cout << \"b\";\n    }\n    cout << endl;\n    fflush(stdout);\n    cin >> numb;\n    if (numb == 0) {\n        return 0;\n    }\n\n    numb = 300 - numb;\n\n    ll n = numa + numb;\n    string pat;\n    for (int i = 0; i < n; i++) {\n        s.push_back('a');\n        pat.push_back('a');\n    }\n\n    ll cur_ans = n - numa;\n    for (int i = 0; i < n - 1; i++) {\n        pat[i] = 'b';\n        ll x = ask(pat);\n        if (x < cur_ans) {\n            s[i] = 'b';\n        }\n        cur_ans = x;\n    }\n    if (n - numb < cur_ans) {\n        s[n-1] = 'b';\n    }\n    ll x = ask(s);\n\n\n\n\n    return 0;\n}"
