    "Maximum Distributed Tree": {
        "Default_Solution": "#include <bits/stdc++.h>\nusing namespace std;\n\ntypedef long long ll;\ntypedef long double ld;\n\ntypedef pair<int, int> pi;\ntypedef pair<ll,ll> pl;\n\ntypedef vector<int> vi;\ntypedef vector<ld> vd;\ntypedef vector<ll> vl;\ntypedef vector<pi> vpi;\ntypedef vector<pl> vpl;\n\n#define sz(x) (int)(x).size()\n#define mp make_pair\n#define pb push_back\n#define f first\n#define s second\n#define lb lower_bound\n#define ub upper_bound\n#define all(x) x.begin(), x.end()\n\nconst int MAX = 1e5, MOD = 1e9+7;\nint n, m;\nvi adj[MAX];\nll p[MAX], s[MAX], contrib[MAX];\n\nvoid dfs(int u=0, int p=-1) {\n\ts[u]=1;\n\tfor(int v : adj[u]) {\n\t\tif(v==p) {\n\t\t\tcontinue;\n\t\t}\n\t\tdfs(v, u);\n\t\ts[u]+=s[v];\n\t}\n\tcontrib[u]=s[u]*(n-s[u]);\n}\n\nint main() {\n\tios::sync_with_stdio(0); cin.tie(0);\n\n\tint t;\n\tcin >> t;\n\twhile(t--) {\n\t\tcin >> n;\n\t\tfor(int i=0; i<n; i++) {\n\t\t\tadj[i].clear();\n\t\t}\n\t\tfor(int i=0; i<n-1; i++) {\n\t\t\tint u, v;\n\t\t\tcin >> u >> v, --u, --v;\n\t\t\tadj[u].pb(v);\n\t\t\tadj[v].pb(u);\n\t\t}\n\t\tcin >> m;\n\t\tfor(int i=0; i<m; i++) {\n\t\t\tcin >> p[i];\n\t\t}\n\t\tsort(p, p+m);\n\t\tdfs();\n\t\tsort(contrib+1, contrib+n);\n\t\tll ans=0;\n\t\tfor(int i=n-1; i>0; i--) {\n\t\t\tll pp=1;\n\t\t\tif(i>n-1-m) {\n\t\t\t\tpp=p[i-1-max(n-1-m, 0)];\n\t\t\t}\n\t\t\tif(i==n-1) {\n\t\t\t\tfor(int j=n-1; j<m; j++) {\n\t\t\t\t\tpp=pp*p[j]%MOD;\n\t\t\t\t}\n\t\t\t}\n\t\t\tans += pp*contrib[i]%MOD;\n\t\t}\n\t\tcout << ans%MOD << \"\n\";\n\t}\n\n\treturn 0;\n}"
    },
