    "Robot Cleaner Revisit": {
        "Default_Solution": "#include <bits/stdc++.h>\nusing namespace std;\n\nconst int mod = 1e9 + 7;\n\nint mpow(int x, int y) {\n\tint ret = 1;\n\twhile (y) {\n\t\tif (y & 1) ret = 1ll * ret * x % mod;\n\t\ty >>= 1; x = 1ll * x * x % mod;\n\t}\n\treturn ret;\n}\n\nint norm(int x) {\n\treturn x >= mod ? x - mod : x;\n}\n\nint reduce(int x) {\n\treturn x < 0 ? x + mod : x;\n}\n\nconst int d[2] = {-1, 1};\n\nint vis[100005][2][2];\n\nstruct state {\n\tint x, y, dx, dy;\n\tstate(int x_ = 0, int y_ = 0, int dx_ = 0, int dy_ = 0) : x(x_), y(y_), dx(dx_), dy(dy_) {}\n};\n\nint main() {\n\tios::sync_with_stdio(false); cin.tie(0);\n\tint T; cin >> T;\n\twhile (T--) {\n\t\tint n, m, x, y, a, b, p;\n\t\tcin >> n >> m >> x >> y >> a >> b >> p;\n\t\tauto s = [&](int x, int y) { return (x - 1) * m + y; };\n\t\tp = 1ll * p * mpow(100, mod - 2) % mod; p = reduce(1 - p);\n\t\tmemset(vis, 0, sizeof(vis));\n\t\tvector<state> seq;\n\t\tstate now = state(x, y, 1, 1);\n\t\tint pos = 0;\n\t\twhile (1) {\n\t\t\tseq.push_back(now);\n\t\t\tif (vis[s(now.x, now.y)][now.dx][now.dy]) {\n\t\t\t\tpos = vis[s(now.x, now.y)][now.dx][now.dy];\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\tvis[s(now.x, now.y)][now.dx][now.dy] = (int)seq.size();\n\t\t\tif (now.x + d[now.dx] < 1 || now.x + d[now.dx] > n) now.dx ^= 1;\n\t\t\tif (now.y + d[now.dy] < 1 || now.y + d[now.dy] > m) now.dy ^= 1;\n\t\t\tnow.x += d[now.dx]; now.y += d[now.dy];\n\t\t}\n\t\t--pos;\n\t\tint ca = 1, cb = 0;\n\t\t// for (int i = 0; i < (int)seq.size(); i++) cout << seq[i].x << \" \" << seq[i].y << endl;\n\t\tfor (int i = (int)seq.size() - 2; i >= pos; i--) {\n\t\t\tif (seq[i].x == a || seq[i].y == b) {\n\t\t\t\tca = 1ll * p * ca % mod, cb = 1ll * p * cb % mod;\n\t\t\t\tcb = norm(cb + p);\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tcb = (cb + 1) % mod;\n\t\t}\n\t\tint ans = 1ll * cb * mpow(reduce(1 - ca), mod - 2) % mod;\n\t\tfor (int i = pos - 1; i >= 0; i--) {\n\t\t\tif (seq[i].x == a || seq[i].y == b) {\n\t\t\t\tans = 1ll * ans * p % mod;\n\t\t\t\tans = norm(ans + p);\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tans = (ans + 1) % mod;\n\t\t}\n\t\tcout << ans << endl;\n\t}\n\treturn 0;\n}"
    },
    "Secret Passwords": {
        "Default_Solution": "#include <cstdio>\n#include <algorithm>\n#include <cstdlib>\n#include <cmath>\n#include <climits>\n#include <cstring>\n#include <string>\n#include <vector>\n#include <queue>\n#include <numeric>\n#include <functional>\n#include <set>\n#include <map>\n#include <unordered_map>\n#include <unordered_set>\n#include <memory>\n#include <thread>\n#include <tuple>\n#include <limits>\n\nusing namespace std;\n\nstruct UF {\n  struct node_t { int parent, size; node_t() : size(1) {} };\n  vector<node_t> nodes;\n\n  UF() { }\n  UF(int size) : nodes(size) {\n    for (int i = 0; i < size; i++) {\n      nodes[i].parent = i;\n    }\n  }\n\n  int find(int index) {\n    int root = index;\n    while (root != nodes[root].parent) {\n      root = nodes[root].parent;\n    }\n    while (root != nodes[index].parent) {\n      int next = nodes[index].parent;\n      nodes[index].parent = root;\n      index = next;\n    }\n    return root;\n  }\n\n  bool merge(int first, int second) {\n    int r1 = find(first);\n    int r2 = find(second);\n    if (r1 == r2) return false;\n    if (nodes[r1].size < nodes[r2].size) swap(r1, r2);\n    nodes[r1].size += nodes[r2].size;\n    nodes[r2].parent = r1;\n    return true;\n  }\n};\n\n\nchar buff[1048576];\n\nint main() {\n  int n;\n  scanf(\"%d\", &n);\n  UF uf(26);\n  set<int> used;\n  for (int i = 0; i < n; i++) {\n    scanf(\"%s\", buff);\n    string d = buff;\n    sort(d.begin(), d.end());\n    d.resize(unique(d.begin(), d.end()) - d.begin());\n    for (auto a : d) {\n      used.insert(a - 'a');\n      for (auto b : d) {\n        uf.merge(a - 'a', b - 'a');\n      }\n    }\n  }\n  int ans = 0;\n  for (auto u : used) {\n    if (uf.find(u) == u) ans++;\n  }\n  printf(\"%d\n\", ans);\n  return 0;\n}\n"
    },
    "Shichikuji and Power Grid": {
        "Default_Solution": "#include<bits/stdc++.h>\nusing namespace std;\n\nvector<tuple<long long, int, int> > V;\nint N;\nint x[2020], y[2020], c[2020], k[2020];\nint ufd[2020];\nvoid init()\n{\n    for(int i=0; i<2020; ++i) ufd[i] = i;\n}\nint Find(int a)\n{\n    if(a==ufd[a]) return a;\n    return ufd[a] = Find(ufd[a]);\n}\nvoid Union(int a, int b)\n{\n    ufd[Find(a)] = Find(b);\n}\nint main()\n{\n    scanf(\"%d\", &N);\n    for(int i=1; i<=N; ++i) scanf(\"%d%d\", x+i, y+i);\n    for(int i=1; i<=N; ++i) scanf(\"%d\", c+i);\n    for(int i=1; i<=N; ++i) scanf(\"%d\", k+i);\n\n    for(int i=1; i<=N; ++i) V.emplace_back(c[i], 0, i);\n    for(int i=1; i<=N; ++i)\n        for(int j=1; j<i; ++j)\n        {\n            long long cost = 1LL*(abs(x[i]-x[j])+abs(y[i]-y[j]))*(k[i]+k[j]);\n            V.emplace_back(cost, i, j);\n        }\n    sort(V.begin(), V.end());\n    \n    vector<pair<int, int> > E;\n\n    long long ans = 0;\n    init();\n    for(auto [c, i, j]: V)\n    {\n        if(Find(i) == Find(j)) continue;\n        Union(i, j);\n        ans += c;\n        E.emplace_back(i, j);\n    }\n\n    vector<int>power;\n    vector<pair<int, int> > conn;\n    for(auto [u, v]: E)\n    {\n        if(u==0 || v == 0)\n        {\n            power.emplace_back(u+v);\n        }\n        else conn.emplace_back(u ,v);\n    }\n    printf(\"%lld\n\", ans);\n    printf(\"%d\n\", (int)power.size());\n    for(auto x: power) printf(\"%d \", x); puts(\"\");\n    printf(\"%d\n\", (int)conn.size());\n    for(auto [u, v]:conn)\n        printf(\"%d %d\n\", u, v);\n    return 0;\n\n}"
    },
