        "Default_Solution": "#include<bits/stdc++.h>\nusing namespace std;\ntypedef long long ll;\nll n, k;\nll a[100010];\nint l, r;\nvoid done() {\n\tputs(\"0\");\n\texit(0);\n}\nvoid move_left() {\n\twhile(1) {\n\t\tif(l == r) done();\n\t\tif(a[l] != a[l + 1]) break;\n\t\tl++;\n\t}\n}\nvoid move_right(){\n\twhile(1) {\n\t\tif(r == l) done();\n\t\tif(a[r] != a[r - 1]) break;\n\t\tr--;\n\t}\n}\nint main() {\n\tcin >> n >> k;\n\tfor(int i = 0; i < n; i++) {\n\t\tcin >> a[i];\n\t}\n\tsort(a, a + n);\n\tl = 0;\n\tr = n - 1;\n\twhile(k > 0) {\n\t\tmove_left();\n\t\tmove_right();\n\t\tint lc = l + 1;\n\t\tint rc = n - r;\n\t\tif(lc < rc) {\n\t\t\tll c = a[l + 1] - a[l];\n\t\t\tif(k < c * lc){\n\t\t\t\ta[0] += k / lc;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\tk -= c * lc;\n\t\t\ta[0] = a[l] = a[l + 1];\n\t\t}\n\t\telse{\n\t\t\tll c = a[r] - a[r - 1];\n\t\t\tif(k < c * rc){\n\t\t\t\ta[n - 1] -= k / rc;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\tk -= c * rc;\n\t\t\ta[n - 1] = a[r] = a[r - 1];\n\t\t}\n\t}\n\tcout << (a[n - 1] - a[0]) << endl;\n\treturn 0;\n}"
