        "Default_Solution": "#include<bits/stdc++.h>\n#define FOR(i,s,e) for(int i=(s);i<=(e);i++)\n#define FORD(i,s,e) for(int i=(s);i>=(e);i--)\n#define ALL(k) (k).begin(),(k).end()\n#define e1 first\n#define e2 second\n#define mp make_pair\n#define pb push_back\n#define eb emplace_back\n\nusing namespace std;\ntypedef long long LL;\ntypedef unsigned long long LLU;\ntypedef long double LD;\ntypedef pair<int,int> PII;\ntypedef pair<LL,LL> PLL;\ntypedef vector<int> VI;\nconst bool print=false;\n\nconst int N=(1<<21)+7;\nint d=20;\n\nint n, k;\n\nvector <int> graf[N];\n\nint ok;\n\nint naj=1;\n\nlong long mas[N];\n\nint dp[N];\n\nint main()\n{\n    scanf(\"%d%d\", &n, &k);\n    for (int i=0; i<n; i++)\n    {\n        mas[i]|=(1LL<<i);\n        for (int j=0; j<n; j++)\n        {\n            int x;\n            scanf(\"%d\", &x);\n            if (x)\n            {\n                ok=1;\n                mas[i]|=(1LL<<j);\n            }\n        }\n    }\n    if (!ok)\n    {\n        printf(\"%.9lf\n\", 0.0);\n        return 0;\n    }\n    d=min(d, n);\n    for (int i=1; i<(1<<d); i++)\n    {\n        int czy=1;\n        long long wsz=(1LL<<n)-1;\n        for (int j=0; j<d && czy; j++)\n        {\n            if ((i&(1<<j)) && (mas[j]&i)!=i)\n                czy=0;\n            if (i&(1<<j))\n                wsz&=mas[j];\n        }\n        if (czy)\n            dp[wsz>>d]=max(dp[wsz>>d], __builtin_popcount(i));\n    }\n    for (int i=(1<<(n-d))-1; i>=0; i--)\n    {\n        int czy=1;\n        for (int j=0; j<(n-d); j++)\n        {\n            if ((i&(1<<j)) && ((mas[d+j]>>d)&i)!=i)\n                czy=0;\n            if (i&(1<<j))\n                dp[i^(1<<j)]=max(dp[i^(1<<j)], dp[i]);\n        }\n        if (czy)\n            naj=max(naj, __builtin_popcount(i)+dp[i]);\n    }\n    printf(\"%.9lf\n\", k*k*(naj-1.0)/(2.0*naj));\n    return 0;\n}\n"
