    "XOR on Segment": {
        "Default_Solution": "#include <cstdio>\n#include <cstring>\n#include <cmath>\n\nusing namespace std;\n\nconst int maxn = 811111;\n\nstruct tree {\n\tint rev[maxn]; int cnt[maxn];\n\n\tinline void reverse(int x, int st, int ed) {\n\t\trev[x] ^= 1;\n\t\tcnt[x] = ed - st + 1 - cnt[x];\n\t}\n\n\tvoid change(int x, int st, int ed, int p, int q) {\n\t\tif (st == p && ed == q) {\n\t\t\treverse(x, st, ed); return ;\n\t\t}\n\n\t\tint mid = (st + ed) / 2;\n\t\tif (rev[x]) {\n\t\t\treverse(x + x, st, mid);\n\t\t\treverse(x + x + 1, mid + 1, ed);\n\t\t\trev[x] = 0;\n\t\t}\n\n\t\tif (q <= mid) {\n\t\t\tchange(x + x, st, mid, p, q);\n\t\t}\n\t\telse {\n\t\t\tif (p > mid) change(x + x + 1, mid + 1, ed, p, q);\n\t\t\telse {\n\t\t\t\tchange(x + x, st, mid, p, mid);\n\t\t\t\tchange(x + x + 1, mid + 1, ed, mid + 1, q);\n\t\t\t}\n\t\t}\n\n\t\tcnt[x] = cnt[x + x] + cnt[x + x + 1];\n\t}\n\n\tint calc(int x, int st, int ed, int p, int q) {\n\t\tif (st == p && ed == q) {\n\t\t\treturn cnt[x];\n\t\t}\n\n\t\tint mid = (st + ed) / 2;\n\t\tif (rev[x]) {\n\t\t\treverse(x + x, st, mid);\n\t\t\treverse(x + x + 1, mid + 1, ed);\n\t\t\trev[x] = 0;\n\t\t}\n\n\t\tint ret;\n\t\tif (q <= mid) ret = calc(x + x, st, mid, p, q);\n\t\telse {\n\t\t\tif (p > mid) ret =  calc(x + x + 1, mid + 1, ed, p, q);\n\t\t\telse ret = calc(x + x, st, mid, p, mid) + calc(x + x + 1, mid + 1, ed, mid + 1, q);\n\t\t}\n\n\t\tcnt[x] = cnt[x + x] + cnt[x + x + 1];\n\t\treturn ret;\n \t}\n\n} F[20];\n\n\nint main() {\n\tint n; scanf(\"%d\", &n);\n\tfor (int i = 1; i <= n; ++i) {\n\t\tint x; scanf(\"%d\", &x);\n\t\tfor (int j = 0; j < 20; ++j)\n\t\t\tif (x & (1 << j)) F[j].change(1, 1, n, i, i);\n\t}\n\tint m; scanf(\"%d\", &m);\n\tfor (int i = 0; i < m; ++i) {\n\t\tint t, p, q; scanf(\"%d%d%d\", &t, &p, &q);\n\n\t\tif (t == 1) {\n\t\t\tlong long ans = 0ll;\n\t\t\tfor (int j = 0; j < 20; ++j) ans += (long long) (1 << j) * F[j].calc(1, 1, n, p, q);\n\t\t\tprintf(\"%I64d\n\", ans);\n\t\t}\n\t\telse {\n\t\t\tint x; scanf(\"%d\", &x);\n\t\t\tfor (int j = 0; j < 20 ;++j) if (x & (1 << j)) F[j].change(1, 1, n, p, q);\n\t\t}\n\t}\n\n\treturn 0;\n}\n"
    },
