        "Default_Solution": "#include <bits/stdc++.h>\n#define int long long\nusing namespace std;\nint a[1005],n,s,k,qwq=0;\ninline void dfs(int x,int y)\n{\n\tif(x==n)\n\t{\n\tif(qwq) return ;\n\t\ta[n]=y;\n\t\tint flag=0;\n\t\tfor(int i=1;i<=n;i++)\n\t\t{\n\t\t\tint s=0;\n\t\t\tfor(int j=i;j<=n;j++)\n\t\t\t{\n\t\t\t\ts+=a[j];\n\t\t\t\tif(s==k)\n\t\t\t\t\tflag=1;\n\t\t\t}\n\t\t}\n\t\tif(!flag)\n\t\t{\n\t\t\tfor(int i=1;i<=n;i++)\n\t\t\t\tcout << a[i] << \"*\";\n\t\t\tcout << \"\n\";\n\t\t\tqwq=1;\n\t\t}\n\t\treturn ;\n\t}\n\tif(qwq) return ;\n\tfor(int i=1;i<=y-(n-x);i++)\n\t{\n\t\ta[x]=i,dfs(x+1,y-i);\n\t}\n}\nsigned main(int argc, char** argv) {\n\tint T;\n\tcin >> T;\n\t\n\twhile(T--)\n\t{\n\t\tcin >> s >> n >> k;\n/*\tfor(s=1;s<=10;s++)\n\t{\n\t\tfor(n=1;n<=s;n++)\n\t\t{\n\t\t\tfor(k=1;k<=10;k++)\n\t\t\t{*/\n\t\t\tqwq=0;\n\t\t\tint qaq=n/k*(k*2)+n%k;\n\t\t//\tcout << qwq << \"*\n\";\n\t\tint ans1,ans2;\n\t//\t\tcout << n << \" \" << k << \" \" << s << \"\n\";\n\t\t\tif(k>s)\n\t\t\t{\n\t\t\t\tcout << \"NO\n\";\n\t\t\t\tans1=0;\n\t\t\t}\n\t\t\telse if(k==s)\n\t\t\t{\n\t\t\t\tcout << \"YES\n\";\n\t\t\t\tans1=1;\n\t\t\t}\n\t\t\telse if(s>=qaq)\n\t\t\t{\n\t\t\t\tcout << \"NO\n\";\n\t\t\t\tans1=0;\n\t\t\t}\n\t\t\telse\n\t\t\t{\n\t\t\t\tcout << \"YES\n\";\n\t\t\t\tans1=1;\n\t\t\t}\n\t\t/*\tdfs(1,s); \n\t\t\tif(qwq)\n\t\t\t{\n\t\t\t\tcout << \"NO\n\n\";\n\t\t\t\tans2=0;\n\t\t\t}\n\t\t\telse\n\t\t\t{\n\t\t\t\tcout << \"YES\n\n\";\n\t\t\t\tans2=1;\n\t\t\t}\n\t\t\tif(ans1!=ans2)\n\t\t\t{\n\t\t\t\tfor(int i=1;i<=1000;i++)\n\t\t\t\t\tcout << n << \" \" << k << \" \" << s << \"\n\";\n\t\t\t}*/\n//\t}\n}\n\treturn 0;\n}"
