        "Default_Solution": "#include<bits/stdc++.h>\n#define MAXN 500005\n#define INF 1000000000\n#define MOD 1000000007\n#define F first\n#define S second\nusing namespace std;\ntypedef long long ll;\ntypedef pair<int,int> P;\nint n,q,a[MAXN],ans[MAXN],bas[40],pos[40];\nvector<P> eve[MAXN];\nint main()\n{\n    scanf(\"%d\",&n);\n    for(int i=1;i<=n;i++) scanf(\"%d\",&a[i]);\n    scanf(\"%d\",&q);\n    for(int i=0;i<q;i++)\n    {\n        int l,r;scanf(\"%d%d\",&l,&r);\n        eve[r].push_back(P(l,i));\n    }\n    for(int i=1;i<=n;i++)\n    {\n        int x=a[i],p=i;\n        for(int j=20;j>=0;j--)\n        {\n            if(x&(1<<j))\n            {\n                if(!bas[j])\n                {\n                    bas[j]=x;pos[j]=p;\n                    break;\n                }\n                if(pos[j]<p) swap(bas[j],x),swap(pos[j],p);\n                x^=bas[j];\n            }\n        }\n        for(auto p:eve[i])\n            for(int j=20;j>=0;j--)\n                if(pos[j]>=p.F) ans[p.S]=max(ans[p.S],ans[p.S]^bas[j]);\n    }\n    for(int i=0;i<q;i++) printf(\"%d\n\",ans[i]);\n    return 0;\n}\n"
