        "Default_Solution": "#include \"bits/stdc++.h\"\nusing namespace std;\n// #define int long long\n#define pb push_back\n#define fi first\n#define se second\n#define FF first\n#define SS second\n#define mp make_pair\n#define pii pair<int,int>\n#define sd(x) scanf(\"%d\",&x)\n#define slld(x) scanf(\"%lld\",&x)\n#define pd(x) printf(\"%d\n\",x)\n#define plld(x) printf(\"%lld\n\",x)\n#define endl '\n'\n#define fr(i, a, b) for(int i = a; i <= b; i++)\n#define sz(x) (int)x.size()\n#define all(x) x.begin(), x.end()\n\ntypedef long long ll;\ntypedef long double f80;\n\nconst int mod = 1e9 + 7;\n\nll pwr(ll a, ll b) {\n    a %= mod;\n    ll ans = 1;\n    while(b) {\n        if(b & 1) ans = (ans * a) % mod;\n        a = (a * a) % mod;\n        b >>= 1;\n    }\n    return ans;\n}\n\nconst int N = 2e5 + 5;\nint a[N];\n\nsigned main()\n{\n    #ifdef LOCAL\n        freopen(\"inp.txt\", \"r\", stdin);\n        freopen(\"out.txt\", \"w\", stdout);\n    #endif\n    ios_base::sync_with_stdio(0);\n    cin.tie(NULL);\n    cout.tie(NULL);\n    int t;\n    cin >> t;\n    while(t--) {\n        int n;\n        cin >> n;\n        fr(i, 1, n) {\n            cin >> a[i];\n        }\n        int mini = 1e9, ans = 0;\n        for(int i = n; i >= 1; i--) {\n            if(a[i] > mini) ans++;\n            mini = min(mini, a[i]);\n        }\n        cout << ans << endl;\n    }\n    return 0;\n}"
