        "Default_Solution": "#include<iostream>\n#include<string>\n#include<vector>\n#include<stack>\n#include<queue>\n#include<set>\n#include<map>\n#include<algorithm>\n#include<cstring>\nusing namespace std;\n\nint main()\n{\n\tint t;\n\tint n;\n\tint div[3];\n\tint i;\n\tint x;\n\tint ans;\n\n\tcin >> t;\n\twhile (t--)\n\t{\n\t\tcin >> n;\n\n\t\tfor (i = 0; i < 3; i++) div[i] = 0;\n\t\tfor (i = 0; i < n; i++)\n\t\t{\n\t\t\tcin >> x;\n\n\t\t\tdiv[x % 3]++;\n\t\t}\n\n\t\tans = 0;\n\t\tfor (i = 0; i < 3; i++)\n\t\t{\n\t\t\tif (div[i] > n / 3)\n\t\t\t{\n\t\t\t\tans += div[i] - n / 3;\n\t\t\t\tdiv[(i + 1) % 3] += div[i] - n / 3;\n\t\t\t\tdiv[i] = n / 3;\n\t\t\t}\n\t\t\telse if (div[i] < n / 3)\n\t\t\t{\n\t\t\t\tans += n / 3 - div[i];\n\t\t\t\tdiv[(i + 2) % 3] -= n / 3 - div[i];\n\t\t\t\tdiv[i] = n / 3;\n\t\t\t}\n\t\t}\n\n\t\tcout << ans << '\n';\n\t}\n}"
