        "Default_Solution": "#include<bits/stdc++.h>\ntypedef unsigned long long ull;\ntypedef long long ll;\ntemplate<class T1,class T2,class T3>T1 ksm(T1 a,T2 b,T3 mod){T1 ans=1;while(b){if(b&1)ans=(ans*a)%mod;a=(a*a)%mod;b>>=1;}return ans;}\n#ifndef ONLINE_JUDGE\ntemplate<class T>T __gcd(T a,T b){ll r;while(b>0){r=a%b;a=b;b=r;}return a;}\n#endif\n#define inf INT_MAX\n#define Max(x,y) x=max(x,y)\n#define Min(x,y) x=min(x,y)\n#define Out(t) printf(\"%s\n\",(t)?\"YES\":\"NO\")\nconst double pi=acos(-1.);\nconst int def=100010;\nconst int mod=1000000007;\nusing namespace std;\n\nint a[2];\nstring s;\n\nstring solve()\n{\tint n=s.length();\n\tif(a[0]+a[1]!=n)return \"-1\";\n\tfor(int i=0;i<n/2;i++){\n\t\tif(s[i]!='?'||s[n-i-1]!='?'){\n\t\t\tif(s[i]!='?'&&s[n-i-1]!='?'){\n\t\t\t\tif(s[i]!=s[n-i-1])return \"-1\";\n\t\t\t}else{\n\t\t\t\tif(s[i]=='?')\n\t\t\t\t\ts[i]=s[n-i-1];\n\t\t\t\telse\n\t\t\t\t\ts[n-i-1]=s[i];\n\t\t\t}\n\t\t\ta[s[i]-'0']-=2;\n\t\t\tif(a[s[i]-'0']<0)return \"-1\";\n\t\t}\n\t}\n\tif(n%2){\n\t\tif(s[n/2]=='?'){\n\t\t\tif(a[0]%2)s[n/2]='0';\n\t\t\telse if(a[1]%2)s[n/2]='1';\n\t\t\telse return \"-1\";\n\t\t\ta[s[n/2]-'0']--;\n\t\t}else{\n\t\t\ta[s[n/2]-'0']--;\n\t\t\tif(a[s[n/2]-'0']<0)return \"-1\";\n\t\t}\n\t}\n\tfor(int i=0;i<n/2;i++){\n\t\tif(s[i]=='?'){\n\t\t\tif(a[0])\n\t\t\t\ts[i]=s[n-i-1]='0';\n\t\t\telse\n\t\t\t\ts[i]=s[n-i-1]='1';\n\t\t\ta[s[i]-'0']-=2;\n\t\t\tif(a[s[i]-'0']<0)return \"-1\";\n\t\t}\n\t}\n\treturn s;\n}\n\nint main()\n{\tint _=1,__=1;\n\t#ifndef ONLINE_JUDGE\n\tfreopen(\"/Users/py/Documents/workspace/C++/try.in\",\"r\",stdin);\n\tfreopen(\"/Users/py/Documents/workspace/C++/try.out\",\"w\",stdout);\n\t#endif\n\tfor(((1)?scanf(\"%d\",&_):EOF);_;_--,__++){\n\t\tscanf(\"%d%d\",&a[0],&a[1]);\n\t\tcin>>s;\n\t\tcout<<solve()<<endl;\n\t}\n\treturn 0;\n}"
