        "Default_Solution": "#include <bits/stdc++.h>\n \nusing namespace std;\n \n#define F first\n#define S second\ntypedef long long   ll;\ntypedef long double ld;\ntypedef pair<ll, ll> pll;  \n\n\n\nint main() {\n    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n    int k;\n    cin >> k;\n    vector<ll> a, b, c, d;\n    a.resize(k);\n    b.resize(k);\n    for (int i = 0; i < k; i++)\n    \tcin >> a[i];\n    for (int i = 0; i < k; i++)\n    \tcin >> b[i];\n    for (int i = 0; i < k; i++)\n    \ta[i] -= b[i];\n\n    for (int i = 0; i < k; i++)\n    \tif (a[i] > 0)\n    \t\tc.push_back(a[i]);\n    \telse\n    \t\td.push_back(a[i]);\n\n\tsort(c.begin(), c.end());\n\tsort(d.rbegin(), d.rend());\n\tint j = 0;\n\tll ans = 0;\n\tfor (int i = 0; i < c.size(); i++) {\n\t\twhile (j < d.size() && c[i] + d[j] > 0)\n\t\t\tj++;\n\t\tans += j;\n\t}\n\tans += ((long long)c.size() * (c.size() - 1)) / 2;\t\n\n\tcout << ans << endl;\n\n    return 0;\n}"
