        "Default_Solution": "#include <cstdio>\n#include <set>\nusing namespace std;\nint minans[5005];\nint fa[5005];\nint dep[5005];\nmultiset<int> s[5005];\nint main()\n{\n    int t,n,d,tmp,dd,p;\n    minans[1]=0;\n    tmp=0;\n    for(int i=2;i<=5000;i++)\n    {\n        if((i&(-i))==i)\n            tmp++;\n        minans[i]=minans[i-1]+tmp;\n    }\n    scanf(\"%d\",&t);\n    while(t--)\n    {\n        scanf(\"%d%d\",&n,&d);\n        if(d>n*(n-1)/2)\n        {\n            printf(\"NO\n\");\n            continue;\n        }\n        if(d<minans[n])\n        {\n            printf(\"NO\n\");\n            continue;\n        }\n        printf(\"YES\n\");\n        for(int i=2;i<=n;i++)\n            fa[i]=i-1;\n        dd=n*(n-1)/2-d;\n        p=1;\n        for(int i=0;i<n;i++)\n            s[i].insert(i+1);\n        s[n-1].insert(n);\n        for(int i=1;i<=n;i++)\n            dep[i]=i-1;\n        for(int i=n;i>=2&&dd>0;i--)\n            if(dd>=(i-1)-p)\n            {\n                s[dep[i]].erase(i);\n                s[dep[i]-1].insert(fa[i]);\n                fa[i]=(*s[p-1].begin());\n                s[p-1].erase(s[p-1].begin());\n                s[p].insert(i);\n                s[p].insert(i);\n                dep[i]=p;\n                dd-=(i-1)-p;\n                while(s[p-1].empty())\n                    p++;\n            }\n            else\n            {\n                fa[i]=(*s[(i-1)-dd-1].begin());\n                break;\n            }\n        for(int i=2;i<=n;i++)\n            if(i!=n)\n                printf(\"%d \",fa[i]);\n            else printf(\"%d\n\",fa[i]);\n        for(int i=0;i<n;i++)\n            s[i].clear();\n    }\n    return 0;\n}\n"
