    "Divisibility by 25": {
        "Default_Solution": "/// In The Name Of God\n\n#pragma GCC optimize(\"Ofast\")\n#pragma GCC target(\"sse,sse2,sse3,ssse3,sse4,popcnt,abm,mmx,avx,tune=native\")\n\n#include <bits/stdc++.h>\n\n#define f first\n#define s second\n\n#define pb push_back\n#define pp pop_back\n#define mp make_pair\n\n#define sz(x) (int)x.size()\n#define sqr(x) ((x) * 1ll * (x))\n#define all(x) x.begin(), x.end()\n\n#define rep(i, l, r) for (int i = (l); i <= (r); i++)\n#define per(i, l, r) for (int i = (l); i >= (r); i--)\n\n#define Kazakhstan ios_base :: sync_with_stdio(0), cin.tie(0), cout.tie(0);\n\n#define nl '\n'\n#define ioi exit(0);\n\ntypedef long long ll;\ntypedef long double ld;\ntypedef unsigned long long ull;\n\nconst int N = (int)5e5 + 7;\nconst int inf = (int)1e9 + 7;\nconst int mod = (int)1e9 + 7;\nconst ll linf = (ll)1e18 + 7;\n\nconst int dx[] = {-1, 0, 1, 0, 1, -1, -1, 1};\nconst int dy[] = {0, 1, 0, -1, 1, -1, 1, -1};\n\nusing namespace std;\n\nint n;\nint ans = inf;\nchar s[N], t[N];\nint last[10];\n\nvoid go(char x, char y) {\n\tif (!min(last[x], last[y])) return;\n\tint cnt = 0;\n\trep(i, 1, n) t[i] = s[i];\n\tx += '0', y += '0';\n\tper(i, n, 1) {\n\t\tif (t[i] == y) {\n\t\t\twhile (i < n) swap(t[i], t[i + 1]), ++cnt, ++i;\n\t\t\tbreak;\n\t\t}\n\t}\n\tper(i, n, 1) {\n\t\tif (t[i] == x) {\n\t\t\twhile (i < (n - 1)) swap(t[i], t[i + 1]), ++cnt, ++i;\n\t\t\tbreak;\n\t\t}\n\t}\n\tif (t[1] == '0') {\n\t\trep(i, 2, n - 2) {\n\t\t\tif (t[i] != '0') {\n\t\t\t\tans = min(ans, cnt + i - 1);\n\t\t\t\treturn;\n\t\t\t}\n\t\t}\n\t\treturn;\n\t}\n\tans = min(ans, cnt);\n}\nint main() {\n\t#ifdef IOI2018\n\t\tfreopen (\"in.txt\", \"r\", stdin);\n\t#endif\n\tcin >> (s + 1);\n\tn = strlen(s + 1);\n\tint cnt = 0, cur = 0;\n\tper(i, n, 1) {\n\t\tif (s[i] == '0' && cnt < 2) {\n\t\t\tcur += (n - cnt) - i;\n\t\t\t++cnt;\n\t\t}\n\t\tint x = s[i] - '0';\n\t\tif (!last[x]) last[x] = i;\n\t}\n\tif (cnt == 2) ans = min(ans, cur);\n\t/*\n\tif (last[2] && last[5]) ans = min(ans, (n - last[5]) + (n - 1 - last[2]));\n\tif (last[7] && last[5]) ans = min(ans, (n - last[5]) + (n - 1 - last[7]));*/\n\tgo(2, 5);\n\tgo(5, 0);\n\tgo(7, 5);\n\n\tif (ans == inf) ans = -1;\n\tcout << ans;\n\tioi\n}\n"
    },
