        "Default_Solution": "#include<bits/stdc++.h>\nusing namespace std ;\n\n#define ll              long long \n#define pb              push_back\n#define all(v)          v.begin(),v.end()\n#define sz(a)           (ll)a.size()\n#define F               first\n#define S               second\n#define INF             2000000000000000000\n#define popcount(x)     __builtin_popcountll(x)\n#define pll             pair<ll,ll>\n#define pii             pair<int,int>\n#define ld              long double\n\nconst int M = 1000000007;\nconst int MM = 998244353;\n\ntemplate<typename T, typename U> static inline void amin(T &x, U y){ if(y<x) x=y; }\ntemplate<typename T, typename U> static inline void amax(T &x, U y){ if(x<y) x=y; }\n\n#ifdef LOCAL\n#define debug(...) debug_out(#__VA_ARGS__, __VA_ARGS__)\n#else\n#define debug(...) 2351\n#endif\n\n\nint _runtimeTerror_()\n{\n    int n,k;\n    cin >> n >> k;\n    vector<int> a(n+1);\n    for(int i=1;i<=n;++i)\n        cin >> a[i];\n    vector<vector<ll>> dp(n+10,vector<ll>(n+10,0));\n    dp[0][0] = 0;\n    for(int i=0;i<n;++i)\n    {\n        for(int j=0;j<=i;++j)\n        {\n            amax(dp[i+1][j],dp[i][j]);\n            if(a[i+1] == j + 1)\n                amax(dp[i+1][j+1],dp[i][j] + 1);\n            else\n                amax(dp[i+1][j+1],dp[i][j]);\n        }\n    }\n    int ans = -1;\n    for(int i=1;i<=n;++i)\n    {\n        if(dp[n][i] >= k)\n            amax(ans,i);\n    }\n    if(ans == -1)\n        cout << ans << \"\n\";\n    else\n        cout << n - ans << \"\n\";\n    return 0;\n}\n\nint main()\n{\n    ios_base::sync_with_stdio(0);cin.tie(0);cout.tie(0);\n    #ifdef runSieve\n        sieve();\n    #endif\n    #ifdef NCR\n        initialize();\n    #endif\n    int TESTS=1;\n    cin>>TESTS;\n    while(TESTS--)\n        _runtimeTerror_();\n    return 0;\n}"
