    "Funny Substrings": {
        "Default_Solution": "#ifndef CPL_TEMPLATE\n#define CPL_TEMPLATE\n/*\n\tNormie's Template v2.4\n\tChanges:\n    Added include-guards to help with writing in multiple source files.\n*/\n// Standard library in one include.\n#include <bits/stdc++.h>\nusing namespace std;\n \n// ordered_set library.\n#include <ext/pb_ds/assoc_container.hpp>\n#include <ext/pb_ds/tree_policy.hpp>\nusing namespace __gnu_pbds;\n#define ordered_set(el) tree<el,null_type,less<el>,rb_tree_tag,tree_order_statistics_node_update>\n \n// AtCoder library. (Comment out these two lines if you're not submitting in AtCoder.) (Or if you want to use it in other judges, run expander.py first.)\n//#include <atcoder/all>\n//using namespace atcoder;\n \n//Pragmas (Comment out these three lines if you're submitting in szkopul.)\n#pragma comment(linker, \"/stack:200000000\")\n#pragma GCC optimize(\"Ofast,unroll-loops,tree-vectorize\")\n#pragma GCC target(\"sse,sse2,sse3,ssse3,sse4,popcnt,abm,mmx,avx,avx2,tune=native\")\n \n//File I/O.\n#define FILE_IN \"cseq.inp\"\n#define FILE_OUT \"cseq.out\"\n#define ofile freopen(FILE_IN,\"r\",stdin);freopen(FILE_OUT,\"w\",stdout)\n \n//Fast I/O.\n#define fio ios::sync_with_stdio(0);cin.tie(0)\n#define nfio cin.tie(0)\n#define endl \"\n\"\n \n//Order checking.\n#define ord(a,b,c) ((a>=b)and(b>=c))\n \n//min/max redefines, so i dont have to resolve annoying compile errors.\n#define min(a,b) (((a)<(b))?(a):(b))\n#define max(a,b) (((a)>(b))?(a):(b))\n\n// Fast min/max assigns to use with AVX.\n// Requires g++ 9.2.0.\ntemplate<typename T>\n__attribute__((always_inline)) void chkmin(T& a, const T& b) {\n    a=(a<b)?a:b;\n}\n\ntemplate<typename T>\n__attribute__((always_inline)) void chkmax(T& a, const T& b) {\n    a=(a>b)?a:b;\n}\n \n//Constants.\n#define MOD (ll(998244353))\n#define MAX 300001\n#define mag 320\nconst long double PI=3.14159265358979;\n \n//Pairs and 3-pairs.\n#define p1 first\n#define p2 second.first\n#define p3 second.second\n#define fi first\n#define se second\n#define pii(element_type) pair<element_type,element_type>\n#define piii(element_type) pair<element_type,pii(element_type)>\n \n//Quick power of 2.\n#define pow2(x) (ll(1)<<x)\n \n//Short for-loops.\n#define ff(i,__,___) for(int i=__;i<=___;i++)\n#define rr(i,__,___) for(int i=__;i>=___;i--)\n \n//Typedefs.\n#define bi BigInt\ntypedef long long ll;\ntypedef long double ld;\ntypedef short sh;\n\n// Binpow and stuff\nll BOW(ll a, ll x, ll p)\n{\n\tif (!x) return 1;\n\tll res=BOW(a,x/2,p);\n\tres*=res;\n\tres%=p;\n\tif (x%2) res*=a;\n\treturn res%p;\n}\nll INV(ll a, ll p)\n{\n\treturn BOW(a,p-2,p);\n}\n//---------END-------//\n#endif\nstruct comp\n{\n    ll cnt=0,len=0;\n    string st=\"\",en=\"\";\n    comp(string s)\n    {\n        len=s.length();\n        cnt=0;\n        for (int i=0;i+4<=len;i++) if (s.substr(i,4)==\"haha\") cnt++;\n        if (len<=3) st=en=s;\n        else \n        {\n            st=s.substr(0,3);\n            en=s.substr(len-3,3);\n        }\n    }\n    comp()\n    {}\n    comp operator+(comp oth)\n    {\n        if ((len<=3)and(oth.len<=3)) return comp(st+oth.st);\n        comp res;\n        res.cnt=cnt+oth.cnt;\n        res.len=len+oth.len;\n        string bruh=en+oth.st;\n        for (int i=0;i+4<=bruh.length();i++) if (bruh.substr(i,4)==\"haha\") res.cnt++;\n        res.st=st;\n        int i=0;\n        while(res.st.size()<3)\n        {\n            res.st.push_back(oth.st[i]);\n            i++;\n        }\n        res.en=oth.en;\n        i=en.size()-1;\n        while(res.en.size()<3)\n        {\n            res.en.push_back(en[i]);\n            i--;\n        }\n        return res;\n    }\n};\nvector<int> vec;\nll n,m,i,j,k,t,t1,u,v,a,b;\nll res=0;\nmap<string,comp> var;\nstring sa,sb,sc,sd,se;\nint main()\n{\n\tfio;\n    cin>>t;\n    for (t1=0;t1<t;t1++)\n    {\n        cin>>n;\n        var.clear();\n        for (i=0;i<n;i++)\n        {\n            cin>>sa>>sb;\n            if (sb==\":=\")\n            {\n                cin>>sc;\n                var[sa]=comp(sc);\n            }\n            else\n            {\n                cin>>sc>>sd>>se;\n                var[sa]=var[sc]+var[se];\n            }\n        }\n        cout<<var[sa].cnt<<endl;\n    }\n}\n"
    },
