        "Default_Solution": "#include <bits/stdc++.h>\n\nusing namespace std;\n\n#define pb push_back\n#define pf push_front\n#define pob pop_back\n#define pof pop_front\n#define mp make_pair\n#define fi first\n#define se second\n\ntypedef long long lli;\ntypedef pair<int, int> ii;\ntypedef pair<lli, lli> ll;\n\nint x[200005], len[200005], suff[200005];\n\nint main() {\n\tint tc, n, k, y, r, temp, maxi;\n\tscanf(\"%d\", &tc);\n\twhile (tc--) {\n\t\tscanf(\"%d %d\", &n, &k);\n\t\tfor (int i = 0; i < n; i++)\n\t\t\tscanf(\"%d\", &x[i]);\n\t\tsort(x, x + n);\n\t\tfor (int i = 0; i < n; i++)\n\t\t\tscanf(\"%d\", &y);\n\t\tr = -1;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\twhile (r + 1 < n) {\n\t\t\t\tif (x[r + 1] > x[i] + k)\n\t\t\t\t\tbreak;\n\t\t\t\tr++;\n\t\t\t}\n\t\t\tlen[i] = r - i + 1;\n\t\t}\n\t\tsuff[n - 1] = len[n - 1];\n\t\tfor (int i = n - 2; i >= 0; i--)\n\t\t\tsuff[i] = max(suff[i + 1], len[i]);\n\t\tmaxi = 0;\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\ttemp = len[i];\n\t\t\tr = i + temp;\n\t\t\tif (r < n)\n\t\t\t\ttemp += suff[r];\n\t\t\tmaxi = max(maxi, temp);\n\t\t}\n\t\tprintf(\"%d\n\", maxi);\n\t}\n\treturn 0;\n}"
