        "Default_Solution": "#include <bits/stdc++.h>\nusing namespace std;\ntemplate<class...Args>\nvoid debug(Args... args) {\n    auto tmp = {(cout << args << ' ', 0)...};\n    cout << endl;\n}\nusing ll = long long;\nusing ull = unsigned long long;\nconst int N = 1e3 + 10;\nconst int mod = 998244353;\nint ask(int x) {\n    cout << \"+ \" << x << endl;\n    int y;\n    cin >> y;\n    return y;\n}\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    int l = 1, r = n - 1;\n    int lst = 0;\n    while (l < r) {\n        int x = (l + r) / 2 + 1;\n        int y = n - x % n;\n        int v = ask(y);\n        l += y;\n        x += y;\n        r += y;\n        if (v == lst) {\n            r = x - 1;\n        } else {\n            l = x;\n        }\n        lst = v;\n    }\n    cout << \"! \" << l << endl;\n}"
