        "Default_Solution": "#include <iostream>\n#include <vector>\n#include <cstring>\n#include <algorithm>\n#include <map>\n#include <queue>\nusing namespace std;\npair <int,int> a[200005];\nint main(int argc, char** argv) {\n\tint T;\n\tios::sync_with_stdio(false);\n\tcin.tie(0);\n\tcin >> T;\n\twhile(T--)\n\t{\n\t\tint n;\n\t\tcin >> n;\n\t\tfor(int i=1;i<=n;i++) cin >> a[i].first;\n\t\tfor(int i=1;i<=n;i++) cin >> a[i].second;\n\t\tsort(a+1,a+n+1);\n\t\tint ans=0;\n\t\ta[0]={1,1};\n\t\tfor(int i=0;i<n;i++)\n\t\t{\n\t\t\tif((a[i+1].second-a[i].second)==(a[i+1].first-a[i].first))\n\t\t\t{\n\t\t\t\tif(a[i].first+a[i].second&1) ans+=0;\n\t\t\t\telse ans+=a[i+1].second-a[i].second;\n\t\t\t}\n\t\t\telse\n\t\t\t{\n\t\t\t\tint lst=a[i].first-a[i].second,nxt=a[i+1].first-a[i+1].second;\n\t\t\t\tif(lst%2==0) ++lst;\n\t\t\t\tif(nxt%2==0) ++nxt;\n\t\t\t\tans+=(nxt-lst)/2;\n\t\t\t}\n\t\t}\n\t\tcout << ans << \"\n\";\n\t}\n\treturn 0;\n}"
