        "Default_Solution": "#include <bits/stdc++.h>\n#define int long long\nusing namespace std;\nint a[200005],b[200005],l[200005],r[200005];\nsigned main(int argc, char** argv) {\n\tios::sync_with_stdio(false);\n\tcin.tie(0);\n\tint T;\n\tcin >> T;\n\twhile(T--)\n\t{\n\t\tint n,m;\n\t\tcin >> n >> m;\n\t\tfor(int i=1;i<=n;i++)\n\t\t\tcin >> a[i] >> b[i];\n\t\tfor(int i=1;i<=n;i++)\n\t\t{\n\t\t\tint x=min(b[i],m);\n\t\t\tr[i]=(a[i]-(m-x))-(b[i]-x);\n\t\t\tx=min(a[i],m);\n\t\t\tl[i]=(a[i]-x)-(b[i]-(m-x));\n//\t\t\tcout << l[i] << \"**\" << r[i] << \"\n\";\n\t\t}\n\t\tint L=0,R=0;\n\t\tfor(int i=1;i<=n;i++) L+=l[i],R+=r[i];\n\t\tint g=0;\n\t\tif(R<=0) g=R;\n\t\telse if(L>=0) g=L;\n\t\telse\n\t\t{\n\t\t\tif(L==0||R==0) g=0;\n\t\t\telse if(L%2==0) g=0;\n\t\t\telse if(L>0) g=1;\n\t\t\telse g=-1;\n\t\t}\n\t\tcout << max(g,-g) << \"\n\";// << \"*\n\";\n\t\tfor(int i=1;i<=n;i++)\n\t\t{\n\t\t\tR-=r[i],L-=l[i];\n\t\t\tint x=min(b[i],m);\n\t\t\tint qwq=L+(a[i]-(m-x))-(b[i]-x)-g;\n\t\t\tif(qwq<=0)\n\t\t\t{\n\t\t\t\tL+=(a[i]-(m-x))-(b[i]-x),R+=(a[i]-(m-x))-(b[i]-x);\n\t\t\t\tcout << m-x << \" \" << x << \"\n\";\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t//\tcout << qwq << \"()\n\";\n\t\t\tif(qwq%2==0) x-=qwq/2;\n\t\t\telse x-=qwq/2+1;\n\t\t\tL+=(a[i]-(m-x))-(b[i]-x),R+=(a[i]-(m-x))-(b[i]-x);\n\t\t\tcout << m-x << \" \" << x << \"\n\";\n\t\t}\n\t}\n\treturn 0;\n}"
