        "Default_Solution": "#include<bits/stdc++.h>\ntypedef unsigned long long ull;\ntypedef long long ll;\ntemplate<class T1,class T2,class T3>T1 ksm(T1 a,T2 b,T3 mod){T1 ans=1;while(b){if(b&1)ans=(ans*a)%mod;a=(a*a)%mod;b>>=1;}return ans;}\n#ifndef ONLINE_JUDGE\ntemplate<class T>T __gcd(T a,T b){ll r;while(b>0){r=a%b;a=b;b=r;}return a;}\n#endif\n#define inf INT_MAX\n#define Max(x,y) x=max(x,y)\n#define Min(x,y) x=min(x,y)\n#define Out(t) printf(\"%s\n\",(t)?\"YES\":\"NO\")\nconst double pi=acos(-1.);\nconst int def=10000010;\nconst int mod=1000000007;\nusing namespace std;\n\nll ans[def],sum[def];\n\nint main()\n{\tint _=1,__=1,n;\n\tfor(int i=1;i<def;i++)\n\t\tfor(int j=1;i*j<def;j++)\n\t\t\tsum[i*j]+=i;\n\tfor(int i=1;i<def;i++)\n\t\tif(sum[i]<def&&!ans[sum[i]])ans[sum[i]]=i;\n\tfor(((1)?scanf(\"%d\",&_):EOF);_;_--,__++){\n\t\tscanf(\"%d\",&n);\n\t\tprintf(\"%lld\n\",ans[n]?ans[n]:-1);\n\t}\n\treturn 0;\n}"
