        "Default_Solution": "//#pragma comment(linker, \"/stack:200000000\")\n//#pragma GCC optimize(\"Ofast\")\n//#pragma GCC target(\"sse,sse2,sse3,ssse3,sse4,popcnt,abm,mmx,avx,tune=native\")\n//#pragma GCC optimize(\"unroll-loops\")\n\n#include <iostream>\n#include <stdlib.h>\n#include <cmath>\n#include <algorithm>\n#include <vector>\n#include <deque>\n#include <set>\n#include <map>\n#include <unordered_map>\n#include <random>\n#include <assert.h>\n#include <memory.h>\n#include <time.h>\n\n#define uint unsigned int\n#define ll long long\n#define ull unsigned long long\n#define ld long double\n#define rep(i, l, r) for (int i = l; i < r; i++)\n#define repb(i, r, l) for (int i = r; i > l; i--)\n#define sz(a) (int)a.size()\n#define fi first\n#define se second\n#define mp(a, b) make_pair(a, b)\n#define rank qwertyuio\n\nusing namespace std;\n\ninline bool setmin(int &x, int y) { return (y < x) ? x = y, 1 : 0; }\ninline bool setmax(int &x, int y) { return (y > x) ? x = y, 1 : 0; }\ninline bool setmin(ll &x, ll y) { return (y < x) ? x = y, 1 : 0; }\ninline bool setmax(ll &x, ll y) { return (y > x) ? x = y, 1 : 0; }\n\nconst int N = 200000;\nconst int inf = (int)1e9 + 1;\nconst ll big = (ll)1e18 + 1;\nconst int P = 239;\nconst int P1 = 31;\nconst int P2 = 57;\nconst int MOD = (int)1e9 + 7;\nconst int MOD1 = (int)1e9 + 9;\nconst int MOD2 = 998244353;\nconst double eps = 1e-9;\nconst double pi = atan2(0, -1);\nconst int ABC = 26;\n\nint main()\n{\n    //freopen(\"a.in\", \"r\", stdin);\n    //freopen(\"a.out\", \"w\", stdout);\n    ios_base::sync_with_stdio(0);\n    cin.tie(0);\n    cout.precision(20);\n    cout << fixed;\n    //ll TL = 0.95 * CLOCKS_PER_SEC;\n    //clock_t time = clock();\n    int T;\n    cin >> T;\n    while (T--) {\n        string s;\n        cin >> s;\n        map<char, int> mapa;\n        for (char c : s) {\n            mapa[c]++;\n        }\n        vector<pair<char, int> > a;\n        for (auto it : mapa) {\n            a.push_back(it);\n        }\n        if (sz(a) == 1) {\n            rep(i, 0, a[0].se) {\n                cout << a[0].fi;\n            }\n            cout << \"\n\";\n            continue;\n        }\n        if (sz(a) == 2) {\n            if (a[0].fi + 1 != a[1].fi) {\n                rep(i, 0, a[0].se) {\n                    cout << a[0].fi;\n                }\n                rep(i, 0, a[1].se) {\n                    cout << a[1].fi;\n                }\n                cout << \"\n\";\n            } else {\n                cout << \"No answer\n\";\n            }\n            continue;\n        }\n        if (sz(a) == 3) {\n            if (a[0].fi + 1 == a[1].fi && a[1].fi + 1 == a[2].fi) {\n                cout << \"No answer\n\";\n            } else if (a[0].fi + 1 != a[1].fi) {\n                rep(i, 0, a[1].se) {\n                    cout << a[1].fi;\n                }\n                rep(i, 0, a[0].se) {\n                    cout << a[0].fi;\n                }\n                rep(i, 0, a[2].se) {\n                    cout << a[2].fi;\n                }\n                cout << \"\n\";\n            } else {\n                rep(i, 0, a[1].se) {\n                    cout << a[1].fi;\n                }\n                rep(i, 0, a[2].se) {\n                    cout << a[2].fi;\n                }\n                rep(i, 0, a[0].se) {\n                    cout << a[0].fi;\n                }\n                cout << \"\n\";\n            }\n            continue;\n        }\n        for (int j = 1; j < sz(a); j += 2) {\n            rep(i, 0, a[j].se) {\n                cout << a[j].fi;\n            }\n        }\n        for (int j = 0; j < sz(a); j += 2) {\n            rep(i, 0, a[j].se) {\n                cout << a[j].fi;\n            }\n        }\n        cout << \"\n\";\n    }\n    return 0;\n}"
