        "Default_Solution": "#include <cmath>\n#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <string>\n#include <set>\n#include <map>\n#include <list>\n#include <time.h>\n#include <math.h>\n#include <random>\n#include <deque>\n#include <queue>\n#include <cassert>\n#include <unordered_map>\n#include <unordered_set>\n#include <iomanip>\n#include <bitset>\n#include <sstream>\n#include <chrono>\n#include <cstring>\n\nusing namespace std;\n\ntypedef long long ll;\n\n#ifdef iq\n  mt19937 rnd(228);\n#else\n  mt19937 rnd(chrono::high_resolution_clock::now().time_since_epoch().count());\n#endif\n\nint main() {\n#ifdef iq\n  freopen(\"a.in\", \"r\", stdin);\n#endif\n  ios::sync_with_stdio(0);\n  cin.tie(0);\n  auto solve = [&] () {\n    int n, s;\n    cin >> n >> s;\n    vector <int> a(n);\n    vector <ll> pref(n);\n    ll t = 0;\n    for (int i = 0; i < n; i++) {\n      cin >> a[i];\n      t += a[i];\n      pref[i] = t;\n    }\n    int ans = -1;\n    int pos = -1;\n    for (int skip = 0; skip <= n; skip++) {\n      auto cost = [&] (int i) {\n        if (skip <= i) {\n          return pref[i] - a[skip];\n        } else {\n          return pref[i];\n        }\n      };\n      int l = -1, r = n;\n      while (l < r - 1) {\n        int m = (l + r) / 2;\n        if (cost(m) <= s) {\n          l = m;\n        } else {\n          r = m;\n        }\n      }\n      int was = ans;\n      ans = max(ans, l + 1 - (skip <= l));\n      if (ans != was) pos = skip;\n    }\n    if (pos == n) {\n      cout << 0 << '\n';\n    } else {\n      cout << pos + 1 << '\n';\n    }\n  };\n  int t;\n  cin >> t;\n  while (t--) {\n    solve();\n  }\n}\n"
