    "1D Sokoban": {
        "Default_Solution": "#include <ext/pb_ds/assoc_container.hpp>\n#include <ext/pb_ds/tree_policy.hpp>\n#include <bits/stdc++.h>\n\nusing namespace __gnu_pbds;\nusing namespace std;\n\nusing ll = long long;\nusing ld = long double;\n\ntypedef tree<\n        int,\n        null_type,\n        less<int>,\n        rb_tree_tag,\n        tree_order_statistics_node_update>\n        ordered_set;\n\n#define mp make_pair\n\n\nconst int MOD =  998244353;\n\nint mul(int a, int b) {\n    return (1LL * a * b) % MOD;\n}\n\nint add(int a, int b) {\n    int s = (a+b);\n    if (s>=MOD) s-=MOD;\n    return s;\n}\n\nint sub(int a, int b) {\n    int s = (a+MOD-b);\n    if (s>=MOD) s-=MOD;\n    return s;\n}\n\nint po(int a, ll deg)\n{\n    if (deg==0) return 1;\n    if (deg%2==1) return mul(a, po(a, deg-1));\n    int t = po(a, deg/2);\n    return mul(t, t);\n}\n\nint inv(int n)\n{\n    return po(n, MOD-2);\n}\n\n\nmt19937 rnd(time(0));\n\n/*\nconst int LIM = 1e6 + 5;\n\nvector<int> facs(LIM), invfacs(LIM);\n\nvoid init()\n{\n    facs[0] = 1;\n    for (int i = 1; i<LIM; i++) facs[i] = mul(facs[i-1], i);\n    invfacs[LIM-1] = inv(facs[LIM-1]);\n    for (int i = LIM-2; i>=0; i--) invfacs[i] = mul(invfacs[i+1], i+1);\n}\n\nint C(int n, int k)\n{\n    if (n<k) return 0;\n    if (n<0 || k<0) return 0;\n    return mul(facs[n], mul(invfacs[k], invfacs[n-k]));\n}*/\n\n\n/*struct DSU\n{\n    vector<int> sz;\n    vector<int> parent;\n    vector<int> value;\n    void make_set(int v) {\n        parent[v] = v;\n        sz[v] = 1;\n        value[v] = 0;\n    }\n\n    int find_set(int v) {\n        if (v == parent[v])\n            return v;\n        else\n        {\n            auto par = find_set(parent[v]);\n            value[v]^=value[parent[v]];\n            parent[v] = par;\n            return par;\n        }\n    }\n\n    void union_sets(int a, int b, int w) {\n        find_set(a);\n        find_set(b);\n\n        w^=value[a]; w^=value[b];\n        a = find_set(a);\n        b = find_set(b);\n\n        if (a != b) {\n            if (sz[a] < sz[b])\n                swap(a, b);\n            parent[b] = a;\n            value[b] = w;\n            sz[a] += sz[b];\n        }\n    }\n\n    int val(int v)\n    {\n        find_set(v); return value[v];\n    }\n\n    DSU (int n)\n    {\n        parent.resize(n);\n        sz.resize(n);\n        value.resize(n);\n        for (int i = 0; i<n; i++) make_set(i);\n    }\n};*/\n\nint calc(vector<int> a, vector<int> b)\n{\n    int n = a.size(); int m = b.size();\n    set<int> pos(b.begin(), b.end());\n\n    vector<int> suf(n+1);\n    suf[n] = 0;\n    for (int i = n-1; i>=0; i--)\n    {\n        suf[i] = suf[i+1];\n        if (pos.count(a[i])) suf[i]++;\n    }\n\n    int ans = suf[0];\n\n\n    for (int take = 1; take<=n; take++)\n    {\n        //we take suf[take], and have take consecutive ending in a[take-1], a[take] - 1\n\n        auto it = lower_bound(b.begin(), b.end(), a[take-1]);\n        if (it==b.end()) continue;\n\n        int idx = it - b.begin();\n\n        int LIM = 1e9 + 5;\n        if (take<n) LIM = a[take]-1;\n\n        while (idx<m && b[idx] <= LIM)\n        {\n            int idx1 = lower_bound(b.begin(), b.end(), b[idx] - take + 1) - b.begin();\n\n            ans = max(ans, suf[take] + (idx - idx1 + 1));\n\n            idx++;\n        }\n    }\n    return ans;\n}\n\nvoid solve()\n{\n    int n, m;\n    cin>>n>>m;\n    vector<int> a(n); for (int i = 0; i<n; i++) cin>>a[i];\n    vector<int> b(m); for (int i = 0; i<m; i++) cin>>b[i];\n\n    int answer = 0;\n\n    vector<int> a1, b1;\n    for (auto it: a) if (it>0) a1.push_back(it);\n    for (auto it: b) if (it>0) b1.push_back(it);\n\n    answer+=calc(a1, b1);\n\n    a1.clear(); b1.clear();\n\n    for (auto it: a) if (it<0) a1.push_back(-it);\n    for (auto it: b) if (it<0) b1.push_back(-it);\n\n    reverse(a1.begin(), a1.end());\n    reverse(b1.begin(), b1.end());\n    answer+=calc(a1, b1);\n    cout<<answer<<endl;\n\n}\n\nint main()\n{\n    ios_base::sync_with_stdio(0);\n    cin.tie(nullptr);\n\n    int t; cin>>t; while (t--) solve();\n\n\n}"
    },
