        "Default_Solution": "#include <iostream>\n#include <fstream>\n#include <set>\n#include <map>\n#include <string>\n#include <vector>\n#include <bitset>\n#include <algorithm>\n#include <cstring>\n#include <cstdlib>\n#include <cmath>\n#include <cassert>\n#include <queue>\n\n#define mp make_pair\n#define pb push_back\n\n\ntypedef long long ll;\ntypedef long double ld;\n\nusing namespace std;\n\n#ifndef LOCAL\n#define cerr _cer\nstruct _cert\n{\n    template <typename T> _cert& operator << (T) { return *this; }\n};\n_cert _cer;\n#endif\n\ntemplate <typename T> void dprint(T begin, T end) {\n    for (auto i = begin; i != end; i++) {\n\t\tcerr << (*i) << \" \";\n    }\n    cerr << \"\n\";\n}\n\nstring s;\n\nvector<string> vv;\n\nstring tr(string s) {\n\tint now = 0;\n\twhile (now + 1 < s.size() && s[now] == '0')\n\t\t++now;\n\treturn s.substr(now);\n}\n\nint main() {\n\tcin >> s;\n\tint sum = 0;\n\tfor (int i = 0; i < s.size(); ++i)\n\t\tsum += (s[i] - '0');\n\tsum %= 3;\n\tif (sum != 0) {\n\t\tfor (int i = s.size() - 1; i >= 0; --i) {\n\t\t\tif ((s[i] - '0') % 3 == sum) {\n\t\t\t\tstring t = s.substr(0, i) + s.substr(i + 1);\n\t\t\t\tt = tr(t);\n\t\t\t\tif (!t.empty())\n\t\t\t\t\tvv.push_back(t);\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tint p1 = -1;\n\t\tfor (int i = s.size() - 1; i >= 0; --i) {\n\t\t\tif ((s[i] - '0') % 3 == 0)\n\t\t\t\tcontinue;\n\t\t\tif ((s[i] - '0') % 3 == sum)\n\t\t\t\tcontinue;\n\t\t\tif (p1 == -1) {\n\t\t\t\tp1 = i;\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tstring t = s.substr(0, i) + s.substr(i + 1, p1 - i - 1) + s.substr(p1 + 1);\n\t\t\tt = tr(t);\n\t\t\tif (!t.empty())\n\t\t\t\tvv.push_back(t);\n\t\t\tbreak;\n\t\t}\n\t}\n\telse {\n\t\ts = tr(s);\n\t\tif (!s.empty())\n\t\t\tvv.push_back(s);\n\t}\n\tstring ans = \"\";\n\tfor (string t: vv)\n\t\tif (t.size() > ans.size())\n\t\t\tans = t;\n\tif (ans.empty())\n\t\tcout << -1 << \"\n\";\n\telse\n\t\tcout << ans << \"\n\";\n\treturn 0;\n}\n\n\n"
