        "Default_Solution": "#include <bits/stdc++.h>\nusing namespace std;\ntypedef signed long long ll;\n\n#undef _P\n#define _P(...) (void)printf(__VA_ARGS__)\n#define FOR(x,to) for(x=0;x<(to);x++)\n#define FORR(x,arr) for(auto& x:arr)\n#define ITR(x,c) for(__typeof(c.begin()) x=c.begin();x!=c.end();x++)\n#define ALL(a) (a.begin()),(a.end())\n#define ZERO(a) memset(a,0,sizeof(a))\n#define MINUS(a) memset(a,0xff,sizeof(a))\n//-------------------------------------------------------\n\nint X,Y;\nint LR[101010],UD[101010];\nint N;\nstring S;\n\nll can(ll step) {\n\tll LR2=LR[N]*(step/N)+LR[step%N];\n\tll UD2=UD[N]*(step/N)+UD[step%N];\n\t\n\treturn (abs(X-LR2)+abs(Y-UD2)<=step);\n}\n\nvoid solve() {\n\tint i,j,k,l,r,x,y; string s;\n\t\n\tcin>>x>>y;\n\tcin>>X>>Y;\n\tX-=x;\n\tY-=y;\n\tcin>>N>>S;\n\tFOR(i,N) {\n\t\tLR[i+1]=LR[i];\n\t\tUD[i+1]=UD[i];\n\t\tif(S[i]=='U') UD[i+1]++;\n\t\tif(S[i]=='D') UD[i+1]--;\n\t\tif(S[i]=='L') LR[i+1]--;\n\t\tif(S[i]=='R') LR[i+1]++;\n\t}\n\t\n\tll ret=(1LL<<50)-1;\n\tif(can(ret)==0) return _P(\"-1\n\");\n\tfor(i=49;i>=0;i--) if(can(ret-(1LL<<i))) ret-=1LL<<i;\n\tcout<<ret<<endl;\n}\n\n\nint main(int argc,char** argv){\n\tstring s;int i;\n\tif(argc==1) ios::sync_with_stdio(false), cin.tie(0);\n\tFOR(i,argc-1) s+=argv[i+1],s+='\n'; FOR(i,s.size()) ungetc(s[s.size()-1-i],stdin);\n\tcout.tie(0); solve(); return 0;\n}\n"
