        "Default_Solution": "#include<bits/stdc++.h>\nusing namespace std;\n#define fastIO ios_base::sync_with_stdio(false); cin.tie(NULL); cout.tie(NULL)\ntypedef long long int lli;\ntypedef long long ll;\ntypedef pair<ll, ll> pll;\ntypedef vector<pll> vop;\ntypedef vector<ll> vl;\ntypedef vector<vl> vvl;\ntypedef vector<int> vi;\ntypedef long double ld;\n#define double ld\ntypedef pair<int, int> pii;\n#define REP(i,a,b) for( int i=a;i<b;i++)\n#define REPR(i,a,b) for(int i=a;i>=b;i--)\n#define adb(a) for(auto i:a) cout << i << \" \"; cout << endl\n#define PB push_back\n#define MP make_pair\n#define F first\n#define S second\n#define all(x) (x).begin(),(x).end()\n#define endl \"\n\"\n#define mem(a,b) memset(a,b,sizeof(a))\n#define mod 1000000007\n#define PI 3.14159265358979323846\n\nstruct LessSecond\n{\n    template<typename T, typename U>\n    bool operator()(const std::pair<T, U> &x, const std::pair<T, U> &y) const\n    {\n        return x.second < y.second;\n    }\n};\n\nll power(ll a, ll b, ll m) { ll ans = 1; a = a % m; while (b) { if (b & 1) ans = (ans * a) % m; b /= 2; a = (a * a) % m; } return ans; }\n\nll lcm(ll a, ll b) { return (a * b) / __gcd(a, b); }\n\nll modInverse(ll a, ll m) { ll g = __gcd(a, m); return power(a, m - 2, m); }\n\n\nint main()\n{\n#ifndef ONLINE_JUDGE\n    freopen(\"input.txt\", \"r\", stdin);\n    freopen(\"output.txt\", \"w\", stdout);\n#endif\n\n    fastIO;\n    int test = 1;\n    cin >> test;\n    while (test--)\n    {\n        ll h, c, t;\n        cin >> h >> c >> t;\n        if (h == t)\n        {\n            cout << 1 << endl;\n            continue;\n        }\n        if ((h + c) / 2 == t)\n        {\n            cout << 2 << endl;\n            continue;\n        }\n        if (h - t >= t - c)\n        {\n            cout << 2 << endl;\n            continue;\n        }\n        double ans = 1000000000000000009.00;\n        ll z = INT_MAX;\n        //vector<pair<double, ll>> v;\n        ll res = 0;\n        ll l = 1, hi = 1000000000000000000, mid;\n        while (l <= hi)\n        {\n            mid = (l + hi) / 2;\n            ll an = 1 + (mid - 1) * 2;\n            ll x = ceil((double)an / 2);\n            ll y = an / 2;\n            double cur = (double)((double)(x * h + y * c) / (double)(x + y));\n            //cout << an << \" \" << x << \" \" << y << \" \" << cur << \" \";\n            double dif = double(abs(double(t) - cur));\n            //cout << dif << \" \" << endl;\n            //v.PB(make_pair(dif, an));\n            if (dif < ans)\n            {\n                ans = dif;\n                z = an;\n            }\n            else if (dif == ans)\n            {\n                if (z > an)\n                    z = an;\n            }\n            if (double(t) >= cur) {\n                hi = mid - 1;\n            }\n            else if (double(t) < cur)\n            {\n\n                l = mid + 1;\n            }\n            else\n            {\n                //ans = min(ans, an);\n                break;\n            }\n            //ans = min(ans, an);\n        }\n        //sort(all(v));\n        cout << z << endl;\n        //cout << ans << endl;\n    }\n    return 0;\n}"
