        "Default_Solution": "// Words are flowing out like endless rain into a paper cup\n// They slither while they pass they slip away across the universe\n// Pools of sorrow, waves of joy are drifting through my open mind\n// Possessing and caressing me\n\n#include <bits/stdc++.h>\nusing namespace std;\n\nusing LL = long long;\n\nnamespace _buff {\n\nconst size_t BUFF = 1 << 19;\nchar ibuf[BUFF], *ib = ibuf, *ie = ibuf;\nchar getc() {\n    if (ib == ie) {\n        ib = ibuf;\n        ie = ibuf + fread(ibuf, 1, BUFF, stdin);\n    }\n    return ib == ie ? -1 : *ib++;\n}\n\n}\n\nLL read() {\n    using namespace _buff;\n    LL ret = 0;\n    bool pos = true;\n    char c = getc();\n    for (; (c < '0' || c > '9') && c != '-'; c = getc()) {\n        assert(~c);\n    }\n    if (c == '-') {\n        pos = false;\n        c = getc();\n    }\n    for (; c >= '0' && c <= '9'; c = getc()) {\n        ret = (ret << 3) + (ret << 1) + (c ^ 48);\n    }\n    return pos ? ret : -ret;\n}\n\nconst size_t N = 1e5 + 5;\nconst size_t AL = 26;\n\nint ls, lt;\nchar s[N], t[N];\nint nxt[N][AL];\n\nvoid get_nxt() {\n    static int head[AL];\n    fill(begin(head), end(head), -1);\n    for (int i = ls; i > 0; --i) {\n        memcpy(nxt[i], head, sizeof head);\n        head[(int) s[i] - 'a'] = i;\n    }\n    memcpy(nxt[0], head, sizeof head);\n}\n\nvoid solve() {\n    scanf(\"%s%s\", s + 1, t);\n    ls = strlen(s + 1);\n    lt = strlen(t);\n    get_nxt();\n    int ans = 0;\n    for (int i = 0; i < lt; ) {\n        int cur = 0;\n        while (i < lt && ~nxt[cur][(int) t[i] - 'a']) {\n            cur = nxt[cur][(int) t[i++] - 'a'];\n        }\n        ++ans;\n        if (!cur) {\n            puts(\"-1\");\n            return;\n        }\n    }\n    printf(\"%d\n\", ans);\n}\n\nint main() {\n    int t;\n    scanf(\"%d\", &t);\n    while (t--) solve();\n    return 0;\n}\n"
