    "Armchairs": {
        "Default_Solution": "/*\n    author:  Maksim1744\n    created: 18.05.2021 21:05:42\n*/\n\n#include \"bits/stdc++.h\"\n\nusing namespace std;\n\nint main() {\n    ios_base::sync_with_stdio(false); cin.tie(NULL); cout.tie(NULL);\n\n    int n;\n    cin >> n;\n    vector<int> a(n);\n    for (int i = 0; i < n; ++i)\n        cin >> a[i];\n\n    vector<int> sum0(n), sum1(n);\n    for (int i = 0; i < n; ++i) {\n        if (a[i] == 0) sum0[i] = i;\n        else sum1[i] = i;\n    }\n    for (int i = 1; i < n; ++i) {\n        sum0[i] += sum0[i - 1];\n        sum1[i] += sum1[i - 1];\n    }\n\n    auto get_sum = [&](int l, int r) {\n        if (l > r) return 0;\n        int s0 = sum0[r] - (l == 0 ? 0 : sum0[l - 1]);\n        int s1 = sum1[r] - (l == 0 ? 0 : sum1[l - 1]);\n        return abs(s0 - s1);\n    };\n\n    vector<int> dp(n, 1e9);\n\n    // offset for negative balance\n    int N = n;\n    vector<int> with_balance(N * 2 + 1, -1);\n\n    int balance = N + 0;\n    with_balance[N + 0] = 0;\n\n    for (int i = 0; i < n; ++i) {\n        if (a[i] == 0) --balance;\n        else ++balance;\n        if (with_balance[balance] != -1) {\n            int l = with_balance[balance];\n            int r = i;\n            int sm = get_sum(l, r);\n            // type 2 edge\n            dp[r] = min(dp[r], sm + (l == 0 ? 0 : dp[l - 1]));\n        }\n        with_balance[balance] = i + 1;\n        if (a[i] == 0) {\n            // type 1 edge\n            dp[i] = min(dp[i], (i == 0 ? 0 : dp[i - 1]));\n        }\n    }\n\n    cout << dp.back() << '\n';\n\n    return 0;\n}\n"
    },
