    "Excellent Arrays": {
        "Default_Solution": "#include <bits/stdc++.h>\n\nconstexpr int P = 1000000007;\nusing i64 = long long;\n// assume -P <= x < 2P\nint norm(int x) {\n    if (x < 0) {\n        x += P;\n    }\n    if (x >= P) {\n        x -= P;\n    }\n    return x;\n}\ntemplate<class T>\nT power(T a, int b) {\n    T res = 1;\n    for (; b; b /= 2, a *= a) {\n        if (b % 2) {\n            res *= a;\n        }\n    }\n    return res;\n}\nstruct Z {\n    int x;\n    Z(int x = 0) : x(norm(x)) {}\n    int val() const {\n        return x;\n    }\n    Z operator-() const {\n        return Z(norm(P - x));\n    }\n    Z inv() const {\n        assert(x != 0);\n        return power(*this, P - 2);\n    }\n    Z &operator*=(const Z &rhs) {\n        x = i64(x) * rhs.x % P;\n        return *this;\n    }\n    Z &operator+=(const Z &rhs) {\n        x = norm(x + rhs.x);\n        return *this;\n    }\n    Z &operator-=(const Z &rhs) {\n        x = norm(x - rhs.x);\n        return *this;\n    }\n    Z &operator/=(const Z &rhs) {\n        return *this *= rhs.inv();\n    }\n    friend Z operator*(const Z &lhs, const Z &rhs) {\n        Z res = lhs;\n        res *= rhs;\n        return res;\n    }\n    friend Z operator+(const Z &lhs, const Z &rhs) {\n        Z res = lhs;\n        res += rhs;\n        return res;\n    }\n    friend Z operator-(const Z &lhs, const Z &rhs) {\n        Z res = lhs;\n        res -= rhs;\n        return res;\n    }\n    friend Z operator/(const Z &lhs, const Z &rhs) {\n        Z res = lhs;\n        res /= rhs;\n        return res;\n    }\n};\n\nint main() {\n    std::ios::sync_with_stdio(false);\n    std::cin.tie(nullptr);\n    \n    int t;\n    std::cin >> t;\n    while (t--) {\n        int n, l, r;\n        std::cin >> n >> l >> r;\n        l--;\n        r--;\n        \n        std::vector<Z> fac(n + 1), invfac(n + 1);\n        fac[0] = 1;\n        for (int i = 1; i <= n; i++) {\n            fac[i] = fac[i - 1] * i;\n        }\n        invfac[n] = fac[n].inv();\n        for (int i = n; i > 0; i--) {\n            invfac[i - 1] = invfac[i] * i;\n        }\n        \n        auto binom = [&](int n, int m) {\n            if (m < 0 || n < m) {\n                return Z(0);\n            }\n            \n            return fac[n] * invfac[m] * invfac[n - m];\n        };\n        \n        int e = std::min(-l, r - (n - 1));\n        \n        Z ans = binom(n, n / 2) * (1 + n % 2) * e;\n        \n        for (int x = e + 1; ; x++) {\n            int a = std::min(n, n - (l + x));\n            int b = std::min(n, r - x + 1);\n            if (a < 0 || b < 0) {\n                break;\n            }\n            \n            ans += binom(a + b - n, n / 2 - (n - b));\n            if (n % 2 == 1) {\n                ans += binom(a + b - n, n / 2 - (n - a));\n            }\n        }\n        \n        std::cout << ans.val() << \"\n\";\n    }\n    \n    return 0;\n}\n"
    },
