        "Default_Solution": "#include <bits/stdc++.h>\nusing namespace std;\n\n#define ll long long\n#define ar array\n\nll n;\nll m, c[61];\n\nvoid solve() {\n\tcin >> n >> m;\n\tmemset(c, 0, sizeof(c));\n\tll s=0;\n\tfor(int i=0, a; i<m; ++i) {\n\t\tcin >> a;\n\t\ts+=a;\n\t\t++c[31-__builtin_clz(a)];\n\t}\n\tif(s<n) {\n\t\tcout << \"-1\n\";\n\t\treturn;\n\t}\n\tint ans=0;\n\tfor(int i=0; i<60; ++i) {\n\t\tif(n>>i&1) {\n\t\t\tif(!c[i]) {\n\t\t\t\tint j=i+1;\n\t\t\t\twhile(!c[j])\n\t\t\t\t\t++j;\n\t\t\t\t--c[j];\n\t\t\t\twhile(--j>=i) {\n\t\t\t\t\t++c[j];\n\t\t\t\t\t++ans;\n\t\t\t\t}\n\t\t\t\t++c[i];\n\t\t\t}\n\t\t\t--c[i];\n\t\t}\n\t\tc[i+1]+=c[i]/2;\n\t}\n\tcout << ans << \"\n\";\n}\n\nint main() {\n\tios::sync_with_stdio(0);\n\tcin.tie(0);\n\n\tint t;\n\tcin >> t;\n\twhile(t--)\n\t\tsolve();\n}"
