    "Maximum Sum of Products": {
        "Default_Solution": "#include <algorithm>\n#include <array>\n#include <cassert>\n#include <chrono>\n#include <cmath>\n#include <cstring>\n#include <functional>\n#include <iomanip>\n#include <iostream>\n#include <map>\n#include <numeric>\n#include <queue>\n#include <random>\n#include <set>\n#include <vector>\nusing namespace std;\n\n// http://www.open-std.org/jtc1/sc22/wg21/docs/papers/2016/p0200r0.html\ntemplate<class Fun> class y_combinator_result {\n    Fun fun_;\npublic:\n    template<class T> explicit y_combinator_result(T &&fun): fun_(std::forward<T>(fun)) {}\n    template<class ...Args> decltype(auto) operator()(Args &&...args) { return fun_(std::ref(*this), std::forward<Args>(args)...); }\n};\ntemplate<class Fun> decltype(auto) y_combinator(Fun &&fun) { return y_combinator_result<std::decay_t<Fun>>(std::forward<Fun>(fun)); }\n\n\ntemplate<typename A, typename B> ostream& operator<<(ostream &os, const pair<A, B> &p) { return os << '(' << p.first << \", \" << p.second << ')'; }\ntemplate<typename T_container, typename T = typename enable_if<!is_same<T_container, string>::value, typename T_container::value_type>::type> ostream& operator<<(ostream &os, const T_container &v) { os << '{'; string sep; for (const T &x : v) os << sep << x, sep = \", \"; return os << '}'; }\n\nvoid dbg_out() { cerr << endl; }\ntemplate<typename Head, typename... Tail> void dbg_out(Head H, Tail... T) { cerr << ' ' << H; dbg_out(T...); }\n#ifdef NEAL_DEBUG\n#define dbg(...) cerr << \"(\" << #__VA_ARGS__ << \"):\", dbg_out(__VA_ARGS__)\n#else\n#define dbg(...)\n#endif\n\n\nint main() {\n    ios::sync_with_stdio(false);\n#ifndef NEAL_DEBUG\n    cin.tie(nullptr);\n#endif\n\n    int N;\n    cin >> N;\n    vector<int64_t> A(N), B(N);\n\n    for (auto &a : A)\n        cin >> a;\n\n    for (auto &b : B)\n        cin >> b;\n\n    int64_t total = 0;\n\n    for (int i = 0; i < N; i++)\n        total += A[i] * B[i];\n\n    int64_t best = total;\n\n    for (int center = 0; center < N; center++) {\n        int64_t current = total;\n\n        for (int x = center - 1, y = center + 1; x >= 0 && y < N; x--, y++) {\n            current -= A[x] * B[x] + A[y] * B[y];\n            current += A[x] * B[y] + A[y] * B[x];\n            best = max(best, current);\n        }\n    }\n\n    for (int between = 0; between < N - 1; between++) {\n        int64_t current = total;\n\n        for (int x = between, y = between + 1; x >= 0 && y < N; x--, y++) {\n            current -= A[x] * B[x] + A[y] * B[y];\n            current += A[x] * B[y] + A[y] * B[x];\n            best = max(best, current);\n        }\n    }\n\n    cout << best << '\n';\n}\n"
    },
