        "Default_Solution": "//#pragma GCC optimize(\"O3\")\n#include <bits/stdc++.h>\n\nusing namespace std;\n\n//defines\ntypedef long long ll;\ntypedef long double ld;\n#define TIME clock() * 1.0 / CLOCKS_PER_SEC\n#define prev _prev\n#define y0 _y0\n#define kill _kill\n\n//permanent constants\nconst ld pi = acos(-1.0);\nconst int day[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};\nconst int digarr[10] = {6, 2, 5, 5, 4, 5, 6, 3, 7, 6};\nconst int dx[4] = {0, 1, 0, -1};\nconst int dy[4] = {1, 0, -1, 0};\nconst int dxo[8] = {-1, -1, -1, 0, 1, 1, 1, 0};\nconst int dyo[8] = {-1, 0, 1, 1, 1, 0, -1, -1};\nconst int alf = 26;\nconst int dig = 10;\nconst int two = 2;\nconst int th = 3;\nconst ll prost = 239;\nconst ll btc = 30;\nconst ld eps = 1e-10;\nconst ll INF = (ll)(1e18 + 239);\nconst int BIG = (int)(1e9 + 239);\nconst int MOD = 1e9 + 7; //(int)(1e9 + 7); //998244353;\nconst ll MOD2 = (ll)MOD * (ll)MOD;\n\n//random\nmt19937 rnd(239); //(chrono::high_resolution_clock::now().time_since_epoch().count());\n\n//constants\nconst int M = (int)(3e5 + 239);\nconst int N = (int)(1e3 + 239);\nconst int L = 20;\nconst int T = (1 << 8) + 10;\nconst int B = 500;\nconst int X = 8;\n\nint a[M][X], n, m, is[T];\n\nint32_t main()\n{\n#ifdef ONPC\n    freopen(\"input.txt\", \"r\", stdin);\n#endif\n    ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n    cin >> n >> m;\n    for (int i = 0; i < n; i++)\n        for (int j = 0; j < m; j++)\n            cin >> a[i][j];\n    int l = 0;\n    int r = (int)(1e9 + 10);\n    while (r - l > 1)\n    {\n        int h = (l + r) >> 1;\n        for (int i = 0; i < (1 << m); i++)\n            is[i] = -1;\n        for (int i = 0; i < n; i++)\n        {\n            int mask = 0;\n            for (int j = 0; j < m; j++)\n                if (a[i][j] >= h)\n                    mask ^= (1 << j);\n            is[mask] = i;\n        }\n        bool ok = false;\n        for (int i = 0; i < (1 << m); i++)\n            for (int j = 0; j < (1 << m); j++)\n                if ((i | j) + 1 == (1 << m))\n                    if (is[i] >= 0 && is[j] >= 0)\n                        ok = true;\n        if (ok)\n            l = h;\n        else\n            r = h;\n    }\n    //cout << l << \"\n\";\n    for (int i = 0; i < (1 << m); i++)\n        is[i] = -1;\n    for (int i = 0; i < n; i++)\n    {\n        int mask = 0;\n        for (int j = 0; j < m; j++)\n            if (a[i][j] >= l)\n                mask ^= (1 << j);\n        is[mask] = i;\n    }\n    for (int i = 0; i < (1 << m); i++)\n        for (int j = 0; j < (1 << m); j++)\n            if ((i | j) + 1 == (1 << m))\n                if (is[i] >= 0 && is[j] >= 0)\n                {\n                    cout << is[i] + 1 << \" \" << is[j] + 1 << \"\n\";\n                    return 0;\n                }\n    return 0;\n}"
