        "Default_Solution": "#include <bits/stdc++.h>\nusing namespace std;\nint n, m, a[200020], b[200020], c[200020];\nbool check(int k) {\n    for (int i = 1; i <= k; i++) {\n        int p = 0;\n        for (int j = i; j <= n; j += k)\n                    b[++p] = a[j];\n        for (int j = 1; j <= p; j++)\n                    if (p - j + 1 > c[b[j]])\n                        return false;\n    }\n    return true;\n}\nint find() {\n    int l = 0, r = n, mid;\n    while (l + 1 < r) {\n        mid = (l + r) >> 1;\n        if (check(mid)) r = mid; else            l = mid;\n    }\n    return r;\n}\nvoid print(int k) {\n    printf(\"%d\n\", k);\n    for (int i = 1; i <= k; i++) {\n        printf(\"%d \", (n - i) / k + 1);\n        for (int j = i; j <= n; j += k)\n                    printf(\"%d \", a[j]);\n        puts(\"\");\n    }\n}\nint main() {\n    scanf(\"%d %d\", &n, &m);\n    for (int i = 1; i <= n; i++)\n            scanf(\"%d\", &a[i]);\n    sort(a + 1, a + n + 1);\n    for (int i = 1; i <= m; i++)\n            scanf(\"%d\", &c[i]);\n    print(find());\n    return 0;\n}"
