        "Default_Solution": "#include <map>\n#include <set>\n#include <cmath>\n#include <string>\n#include <vector>\n#include <iostream>\n#include <algorithm>\n#include <functional>\nusing namespace std;\nconst int lim = 1048576;\nint bit[1048588];\nvoid add(int pos, int val) {\n\tfor (int i = pos; i <= lim; i += i & (-i)) {\n\t\tbit[i] += val;\n\t}\n}\nint bsearch(int x) {\n\tif (x == 0) return 0;\n\tint ptr = 0;\n\tfor (int i = lim / 2; i >= 1; i >>= 1) {\n\t\tif (bit[ptr + i] < x) {\n\t\t\tx -= bit[ptr + i];\n\t\t\tptr += i;\n\t\t}\n\t}\n\treturn ptr + 1;\n}\nint main() {\n\tcin.tie(0);\n\tios_base::sync_with_stdio(false);\n\tint N, Q;\n\tcin >> N >> Q;\n\tfor (int i = 0; i < N; ++i) {\n\t\tint x;\n\t\tcin >> x;\n\t\tadd(x, 1);\n\t}\n\tint cnt = N;\n\tfor (int i = 0; i < Q; ++i) {\n\t\tint x;\n\t\tcin >> x;\n\t\tif (x >= 0) add(x, 1), ++cnt;\n\t\telse {\n\t\t\tint ptr = bsearch(-x);\n\t\t\tadd(ptr, -1);\n\t\t\t--cnt;\n\t\t}\n\t}\n\tif (cnt == 0) {\n\t\tcout << 0 << endl;\n\t}\n\telse {\n\t\tcout << bsearch(1) << endl;\n\t}\n\treturn 0;\n}"
