    "Subarray Sorting": {
        "Default_Solution": "//~ while (clock()<=69*CLOCKS_PER_SEC)\n//~ #pragma comment(linker, \"/stack:200000000\")\n#pragma GCC optimize(\"O3\")\n//~ #pragma GCC optimize(\"Ofast\")\n//~ #pragma GCC target(\"sse,sse2,sse3,ssse3,sse4,popcnt,abm,mmx,avx,tune=native\")\n//~ #pragma GCC optimize(\"unroll-loops\")\n#include <bits/stdc++.h>\n#include <ext/pb_ds/assoc_container.hpp>\n#include <ext/pb_ds/tree_policy.hpp>\n\nusing namespace __gnu_pbds;\nusing namespace std;\n\ntemplate <typename T>\nusing ordered_set =\n    tree<T, null_type, less<T>, rb_tree_tag, tree_order_statistics_node_update>;\n\n#define sim template < class c\n#define ris return * this\n#define dor > debug & operator <<\n#define eni(x) sim > typename \\\n  enable_if<sizeof dud<c>(0) x 1, debug&>::type operator<<(c i) {\nsim > struct rge { c b, e; };\nsim > rge<c> range(c i, c j) { return rge<c>{i, j}; }\nsim > auto dud(c* x) -> decltype(cerr << *x, 0);\nsim > char dud(...);\nstruct debug {\n#ifdef LOCAL\n~debug() { cerr << endl; }\neni(!=) cerr << boolalpha << i; ris; }\neni(==) ris << range(begin(i), end(i)); }\nsim, class b dor(pair < b, c > d) {\n  ris << \"(\" << d.first << \", \" << d.second << \")\";\n}\nsim dor(rge<c> d) {\n  *this << \"[\";\n  for (auto it = d.b; it != d.e; ++it)\n    *this << \", \" + 2 * (it == d.b) << *it;\n  ris << \"]\";\n}\n#else\nsim dor(const c&) { ris; }\n#endif\n};\n#define imie(...) \" [\" << #__VA_ARGS__ \": \" << (__VA_ARGS__) << \"] \"\n\n#define shandom_ruffle random_shuffle\n\nusing ll=long long;\nusing pii=pair<int,int>;\nusing pll=pair<ll,ll>;\nusing vi=vector<int>;\nusing vll=vector<ll>;\nconst int nax=1200*1007;\nconst int n1=(1<<19);\n\nint n;\n\nint a[nax];\nint b[nax];\n\nint gdz[nax];\n\nmap <int,int> sta, kon;\n\nvoid nie()\n{\n\tprintf(\"NO\n\");\n}\n\nvoid tak()\n{\n\tprintf(\"YES\n\");\n}\n\nint drz[nax];\n\nvoid zmien(int v, int w)\n{\n\tv+=n1-1;\n\tdrz[v]=w;\n\tv>>=1;\n\twhile(v)\n\t{\n\t\tdrz[v]=min(drz[v*2], drz[v*2+1]);\n\t\tv>>=1;\n\t}\n}\n\nint czyt(int v, int a, int b, int graa, int grab)\n{\n\tif (a>=graa && b<=grab)\n\t{\n\t\treturn drz[v];\n\t}\n\tif (a>grab || b<graa)\n\t{\n\t\treturn 1e9;\n\t}\n\treturn min(\n\t\tczyt((v<<1), a, (a+b)>>1, graa, grab),\n\t\tczyt((v<<1)^1, (a+b+2)>>1, b, graa, grab)\n\t);\n}\n\nvoid test()\n{\n\tsta.clear();\n\tkon.clear();\n\tscanf(\"%d\", &n);\n\tfor (int i=1; i<=n; i++)\n\t{\n\t\tscanf(\"%d\", &a[i]);\n\t\tsta[a[i]]++;\n\t}\n\tfor (int i=1; i<=n; i++)\n\t{\n\t\tscanf(\"%d\", &b[i]);\n\t\tkon[b[i]]++;\n\t}\n\tif (sta!=kon)\n\t{\n\t\tnie();\n\t\treturn;\n\t}\n\tvector <pii> raz, dwa;\n\tfor (int i=1; i<=n; i++)\n\t{\n\t\traz.push_back({a[i], i});\n\t\tdwa.push_back({b[i], i});\n\t}\n\tsort(raz.begin(), raz.end());\n\tsort(dwa.begin(), dwa.end());\n\tfor (int i=1; i<=n; i++)\n\t{\n\t\ta[raz[i-1].second]=i;\n\t\tb[dwa[i-1].second]=i;\n\t}\n\tfor (int i=1; i<=n; i++)\n\t\tgdz[a[i]]=i;\n\t//~ debug() << range(a+1, a+1+n);\n\t//~ debug() << range(b+1, b+1+n);\n\tfor (int i=1; i<=n; i++)\n\t\tzmien(i, a[i]);\n\tfor (int i=1; i<=n; i++)\n\t{\n\t\tint x=gdz[b[i]];\n\t\t//~ debug() << imie(x) << czyt(1, 1, n1, 1, x);\n\t\tif (czyt(1, 1, n1, 1, x)<b[i])\n\t\t{\n\t\t\tnie();\n\t\t\treturn;\n\t\t}\n\t\tzmien(x, 1e9);\n\t}\n\ttak();\n}\n\nint main()\n{\n\tint t;\n\tscanf(\"%d\", &t);\n\twhile(t--)\n\t\ttest();\n\treturn 0;\n}\n"
    },
    "The Number of Pairs": {
        "Default_Solution": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\n\nconst int MX = 20000000;\n\nvector<int> primes;\nint sieve[20202020];\nll ans;\nint c, d, x;\n\nvoid f(int g) {\n\tint y = (x / g + d);\n\tif(y % c) return;\n\ty /= c;\n\tint cnt = 0, last = 0;\n\twhile(y > 1) {\n\t\tint t = sieve[y];\n\t\tif(last != t) { cnt++; last = t; }\n\t\ty /= t;\n\t}\n\tans += (1 << cnt);\n}\n\nint main() {\n\tfor(int i = 2; i <= MX; i++) {\n\t\tif(!sieve[i]) { sieve[i] = i; primes.push_back(i); }\n\t\tfor(int j : primes) {\n\t\t\tif(i * j > MX) break;\n\t\t\tsieve[i * j] = j;\n\t\t\tif(i % j == 0) break;\n\t\t}\n\t}\n\n\tint tc; scanf(\"%d\", &tc);\n\twhile(tc--) {\n\t\tscanf(\"%d%d%d\", &c, &d, &x);\n\t\tans = 0;\n\t\tfor(int i = 1; i * i <= x; i++) {\n\t\t\tif(x % i) continue;\n\t\t\tf(i);\n\t\t\tif(i != x / i) f(x / i);\n\t\t}\n\t\tprintf(\"%lld\n\", ans);\n\t}\n\treturn 0;\n}"
    },
