    "Yet Another Subarray Problem": {
        "Default_Solution": "#include <iostream>\n#include <cstdio>\n#include <cstdlib>\n#include <algorithm>\n#include <cmath>\n#include <vector>\n#include <set>\n#include <map>\n#include <unordered_set>\n#include <unordered_map>\n#include <queue>\n#include <ctime>\n#include <cassert>\n#include <complex>\n#include <string>\n#include <cstring>\n#include <chrono>\n#include <random>\n#include <queue>\n#include <bitset>\nusing namespace std;\n\n#ifdef LOCAL\n\t#define eprintf(...) fprintf(stderr, __VA_ARGS__)\n#else\n\t#define eprintf(...) 42\n#endif\n\ntypedef long long ll;\ntypedef pair<int, int> pii;\ntypedef pair<ll, int> pli;\ntypedef pair<ll, ll> pll;\ntypedef long double ld;\n#define mp make_pair\nmt19937 rng(chrono::steady_clock::now().time_since_epoch().count());\n\nconst ll INF = (ll)1e18;\nconst int N = 300300;\nconst int M = 10;\nll ans = 0;\nint n, m;\nll k;\nll b[M];\n\nint main()\n{\n//\tfreopen(\"input.txt\", \"r\", stdin);\n//\tfreopen(\"output.txt\", \"w\", stdout);\n\n\tscanf(\"%d%d%lld\", &n, &m, &k);\n\tfor (int i = 0; i < m; i++)\n\t\tb[i] = INF;\n\tb[0] = 0;\n\tll bal = 0;\n\tfor (int i = 1; i <= n; i++) {\n\t\tll x;\n\t\tscanf(\"%lld\", &x);\n\t\tbal += x;\n\t\tb[i % m] = min(b[i % m], bal - (i / m) * k);\n\t\tfor (int r = 0; r < m; r++) {\n\t\t\tll z = bal - (i / m) * k;\n\t\t\tif (i % m > r) z -= k;\n\t\t\tans = max(ans, z - b[r]);\n\t\t}\n\t}\n\tprintf(\"%lld\n\", ans);\n\n\treturn 0;\n}\n"
    },
    "Yet Another Yet Another Task": {
        "Default_Solution": "#ifdef DEBUG\n#define _GLIBCXX_DEBUG\n#endif\n//#pragma GCC optimize(\"O3\")\n#include <bits/stdc++.h>\nusing namespace std;\ntypedef long double ld;\ntypedef long long ll;\nconst int maxN = 1e5 + 10;\nint a[maxN];\nint n;\nint pref[maxN];\nint main() {\n    ios_base::sync_with_stdio(false);\n    cin.tie(nullptr);\n//    freopen(\"input.txt\", \"r\", stdin);\n    cin >> n;\n    int best = 0;\n    vector < pair < int, int > > all;\n\n    for (int i = 1; i <= n; i++) {\n        cin >> a[i];\n        pref[i] = pref[i - 1] + a[i];\n        for (auto& it : all) {\n            it.first = max(it.first, a[i]);\n        }\n        all.emplace_back(a[i], pref[i - 1]);\n        sort(all.begin(), all.end());\n        map < int, int > mp;\n        for (auto& it : all) {\n            if (!mp.count(it.first)) mp[it.first] = it.second;\n            else mp[it.first] = min(mp[it.first], it.second);\n        }\n        all.clear();\n        for (auto& it : mp) {\n            all.emplace_back(it);\n            best = max(best, pref[i] - it.second - it.first);\n        }\n    }\n    cout << best;\n    return 0;\n}"
    },
