        "Default_Solution": "#pragma GCC optimize (\"O3\")\n#pragma GCC target (\"sse4\")\n \n#include <bits/stdc++.h>\n \nusing namespace std;\n \ntypedef long long ll;\ntypedef long double ld;\ntypedef complex<ld> cd;\n \ntypedef pair<int, int> pi;\ntypedef pair<ll,ll> pl;\ntypedef pair<ld,ld> pd;\n \ntypedef vector<int> vi;\ntypedef vector<ld> vd;\ntypedef vector<ll> vl;\ntypedef vector<pi> vpi;\ntypedef vector<pl> vpl;\ntypedef vector<cd> vcd;\n \n#define FOR(i, a, b) for (int i=a; i<(b); i++)\n#define F0R(i, a) for (int i=0; i<(a); i++)\n#define FORd(i,a,b) for (int i = (b)-1; i >= a; i--)\n#define F0Rd(i,a) for (int i = (a)-1; i >= 0; i--)\n#define trav(a,x) for (auto& a : x)\n#define uid(a, b) uniform_int_distribution<int>(a, b)(rng)\n \n#define sz(x) (int)(x).size()\n#define mp make_pair\n#define pb push_back\n#define f first\n#define s second\n#define lb lower_bound\n#define ub upper_bound\n#define all(x) x.begin(), x.end()\n#define ins insert\n\ntemplate<class T> bool ckmin(T& a, const T& b) { return b < a ? a = b, 1 : 0; }\ntemplate<class T> bool ckmax(T& a, const T& b) { return a < b ? a = b, 1 : 0; }\n \nmt19937 rng(chrono::steady_clock::now().time_since_epoch().count());\n \nconst int MOD = 1000000007;\nconst char nl = '\n';\nconst int MX = 150001; //check the limits, dummy\n\nvoid solve() {\n\n    int N[4]; F0R(i, 4) cin >> N[i];\n    ll A[4][MX]; F0R(i, 4) F0R(j, N[i]) cin >> A[i][j];\n    vector<set<int>> graph[3];\n    F0R(i, 3) {\n        graph[i] = vector<set<int>>(N[i+1]);\n        int M; cin >> M;\n        F0R(j, M) {\n            int X, Y; cin >> X >> Y; X--; Y--; graph[i][Y].ins(X);\n        }\n    }\n\n    set<pl> cost[4];\n    F0R(i, N[0]) cost[0].ins({A[0][i], i});\n    FOR(i, 1, 4) {\n        F0R(j, N[i]) {\n            auto it = cost[i-1].begin();\n            while (it != cost[i-1].end() && graph[i-1][j].count(it->s)) {\n                it++;\n            }\n            if (it != cost[i-1].end()) {\n                cost[i].ins({it->f + A[i][j], j});\n            }\n        }\n    }\n    if (sz(cost[3]) == 0) {\n        cout << -1 << nl;\n    } else {\n        cout << cost[3].begin()->f << nl;\n    }\n}\n \nint main() {\n\tios_base::sync_with_stdio(0); cin.tie(0);    \n\n    int T = 1;\n//    cin >> T;\n    while(T--) {\n        solve();\n    }\n\n\treturn 0;\n}\n \n// read the question correctly (ll vs int)\n// template by bqi343\n\n"
