        "Default_Solution": "#include <bits/stdc++.h>\n\n#define all(x) (x).begin(), (x).end()\n#define itn int\n#define make_unique(x) sort((x).begin(), (x).end()); (x).erase(unique((x).begin(), (x).end()), (x).end())\n\nusing namespace std;\n\ninline int nxt() {\n\tint x;\n\tcin >> x;\n\treturn x;\n}\n\nvoid solve() {\n\tint n = nxt(), m = nxt();\n\tvector<string> a(n);\n\tfor (int i = 0; i < n; ++i) {\n\t\tcin >> a[i];\n\t}\n\n\tvector<pair<int, int>> coords;\n\tvector<vector<int>> g;\n\tvector<vector<int>> id(n, vector<int>(m, -1));\n\tfor (int i = 0; i < n; ++i) {\n\t\tfor (int j = 0; j < m; ++j) {\n\t\t\tif (a[i][j] == '#') {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tid[i][j] = g.size();\n\t\t\tg.push_back({});\n\t\t\tcoords.push_back({i, j});\n\t\t}\n\t}\n\tfor (int i = 0; i < n; ++i) {\n\t\tfor (int j = 0; j < m; ++j) {\n\t\t\tif (a[i][j] == '#') {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tfor (int dx = -1; dx <= 1; ++dx) {\n\t\t\t\tfor (int dy = -1; dy <= 1; ++dy) {\n\t\t\t\t\tif (abs(dx) + abs(dy) != 1) {\n\t\t\t\t\t\tcontinue;\n\t\t\t\t\t}\n\t\t\t\t\tint ni = i + dx, nj = j + dy;\n\t\t\t\t\tif (clamp(ni, 0, n - 1) != ni || clamp(nj, 0, m - 1) != nj) {\n\t\t\t\t\t\tcontinue;\n\t\t\t\t\t}\n\t\t\t\t\tif (a[ni][nj] == '#') {\n\t\t\t\t\t\tcontinue;\n\t\t\t\t\t}\n\t\t\t\t\tg[id[i][j]].push_back(id[ni][nj]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\tint lab = -1;\n\tfor (int i = 0; i < n; ++i) {\n\t\tfor (int j = 0; j < m; ++j) {\n\t\t\tif (a[i][j] == 'L') {\n\t\t\t\tlab = id[i][j];\n\t\t\t}\n\t\t}\n\t}\n\tconst int sz = g.size();\n\tvector<char> used(sz);\n\tvector<int> rem(sz);\n\tfor (int i = 0; i < sz; ++i) {\n\t\trem[i] = g[i].size();\n\t}\n\tvector<int> st = {lab};\n\tused[lab] = true;\n\twhile (!st.empty()) {\n\t\tint v = st.back();\n\t\tst.pop_back();\n\t\tfor (int x : g[v]) {\n\t\t\t--rem[x];\n\t\t\tif (!used[x] && rem[x] <= 1) {\n\t\t\t\tused[x] = 1;\n\t\t\t\tst.push_back(x);\n\t\t\t}\n\t\t}\n\t}\n\tfor (int i = 0; i < sz; ++i) {\n\t\tif (used[i] && i != lab) {\n\t\t\tauto [x, y] = coords[i];\n\t\t\ta[x][y] = '+';\n\t\t}\n\t}\n\tfor (auto s : a) {\n\t\tcout << s << \"\n\";\n\t}\n}\n\nint main() {\n\tios_base::sync_with_stdio(false);\n\tcin.tie(nullptr);\n\n\tint t = nxt();\n\twhile (t--) {\n\t\tsolve();\n\t}\n\n\treturn 0;\n}\n"
