    "Expected Damage": {
        "Default_Solution": "#ifdef xay5421\n#define D(...) fprintf(stderr,__VA_ARGS__)\n#else\n#define D(...) ((void)0)\n//#define NDEBUG\n#endif\n#include<bits/stdc++.h>\n#define int long long\n#define LL long long\n#define MP make_pair\n#define PB push_back\n#define fi first\n#define se second\n#define ALL(x) (x).begin(),(x).end()\n#define SZ(x) ((int)(x).size())\n#define rep(i,a,b) for(int i=(a);i<=(b);++i)\n#define per(i,a,b) for(int i=(a);i>=(b);--i)\nusing namespace std;\ntypedef pair<int,int>PII;typedef vector<int>VI;typedef vector<PII>VII;\ntemplate<typename T>void rd(T&x){int f=0,c;while(!isdigit(c=getchar()))f^=!(c^45);x=(c&15);while(isdigit(c=getchar()))x=x*10+(c&15);if(f)x=-x;}\ntemplate<typename T>void pt(T x,int c=-1){if(x<0)putchar('-'),x=-x;if(x>9)pt(x/10);putchar(x%10+48);if(c!=-1)putchar(c);}\n\nconst int N=200005,p=998244353;\n\nstruct xay{int a,b,id;}a[N];\n\nint d[N],ans[N];\nint n,m,allsum;\n\nbool cmp(xay a,xay b){return a.b>b.b;}\n\nint fpow(int x,int y){\n\tint ans=1;\n\twhile(y){\n\t\tif(y&1)ans=1ll*ans*x%p;\n\t\ty>>=1;x=1ll*x*x%p;\n\t}\n\treturn ans;\n}\n\nsigned main(){\n\trd(n);rd(m);\n\trep(i,1,n)rd(d[i]),allsum=(allsum+d[i])%p;\n\trep(i,1,m)rd(a[i].a),rd(a[i].b),a[i].id=i;\n\tsort(d+1,d+n+1);reverse(d+1,d+n+1);sort(a+1,a+n+1,cmp);\n\tint pos=1,sum=0;\n\trep(i,1,m){\n\t\twhile(pos<=n&&d[pos]>=a[i].b)sum=(sum+d[pos])%p,++pos;\n\t\tif(pos-1>=a[i].a)ans[a[i].id]=(1ll*sum*fpow(pos-1,p-2)%p*(pos-1-a[i].a)%p+1ll*(allsum-sum+p)*fpow(pos,p-2)%p*(pos-a[i].a)%p)%p;\n\t}\n\trep(i,1,m)pt(ans[i],'\n');\n\treturn 0;\n}"
    },
    "Four Points": {
        "Default_Solution": "#include <algorithm>\n#include <array>\n#include <cassert>\n#include <chrono>\n#include <cmath>\n#include <cstring>\n#include <functional>\n#include <iomanip>\n#include <iostream>\n#include <map>\n#include <numeric>\n#include <queue>\n#include <random>\n#include <set>\n#include <vector>\nusing namespace std;\n\ntemplate<typename A, typename B> ostream& operator<<(ostream &os, const pair<A, B> &p) { return os << '(' << p.first << \", \" << p.second << ')'; }\ntemplate<typename T_container, typename T = typename enable_if<!is_same<T_container, string>::value, typename T_container::value_type>::type> ostream& operator<<(ostream &os, const T_container &v) { os << '{'; string sep; for (const T &x : v) os << sep << x, sep = \", \"; return os << '}'; }\n\nvoid dbg_out() { cerr << endl; }\ntemplate<typename Head, typename... Tail> void dbg_out(Head H, Tail... T) { cerr << ' ' << H; dbg_out(T...); }\n\n#ifdef NEAL_DEBUG\n#define dbg(...) cerr << \"(\" << #__VA_ARGS__ << \"):\", dbg_out(__VA_ARGS__)\n#else\n#define dbg(...)\n#endif\n\n\nconst int64_t XY_MAX = int(1e9) + 5;\n\nvoid run_case() {\n    auto get_median = [](array<int64_t, 4> &X) {\n        nth_element(X.begin(), X.begin() + 1, X.end());\n        return X[1];\n    };\n\n    auto evaluate = [&](array<int64_t, 4> CX, array<int64_t, 4> CY, int64_t len) {\n        CX[1] -= len; CX[3] -= len;\n        CY[2] -= len; CY[3] -= len;\n        int64_t X_median = get_median(CX);\n        int64_t Y_median = get_median(CY);\n        int64_t value = 0;\n\n        for (int i = 0; i < 4; i++)\n            value += abs(CX[i] - X_median) + abs(CY[i] - Y_median);\n\n        return value;\n    };\n\n    auto get_choices = [](array<int64_t, 2> low, array<int64_t, 2> high) -> array<int64_t, 2> {\n        sort(low.begin(), low.end());\n        sort(high.begin(), high.end());\n        return {high[1] - low[0], high[0] - low[1]};\n    };\n\n    array<int64_t, 4> X, Y;\n\n    for (int i = 0; i < 4; i++)\n        cin >> X[i] >> Y[i];\n\n    array<int, 4> perm = {0, 1, 2, 3};\n    int64_t best = XY_MAX * XY_MAX;\n\n    do {\n        array<int64_t, 4> CX, CY;\n\n        for (int i = 0; i < 4; i++) {\n            CX[i] = X[perm[i]];\n            CY[i] = Y[perm[i]];\n        }\n\n        array<int64_t, 2> x_choices = get_choices({CX[0], CX[2]}, {CX[1], CX[3]});\n        array<int64_t, 2> y_choices = get_choices({CY[0], CY[1]}, {CY[2], CY[3]});\n        array<int64_t, 4> choices = {x_choices[0], x_choices[1], y_choices[0], y_choices[1]};\n        int64_t len = max<int64_t>(get_median(choices), 0);\n        best = min(best, evaluate(CX, CY, len));\n    } while (next_permutation(perm.begin(), perm.end()));\n\n    cout << best << '\n';\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n#ifndef NEAL_DEBUG\n    cin.tie(nullptr);\n#endif\n\n    int tests;\n    cin >> tests;\n\n    while (tests-- > 0)\n        run_case();\n}\n"
    },
    "Gold Transfer": {
        "Default_Solution": "#include <bits/stdc++.h>\nusing namespace std;\nconst int LOG = 19;\nint main(){\n  ios::sync_with_stdio(false);\n  cin.tie(nullptr);\n  int q, a0, c0;\n  cin >> q >> a0 >> c0;\n  vector<int> A(1), C(1);\n  A[0] = a0;\n  C[0] = c0;\n  int N = 1;\n  vector<int> d(1, 0);\n  vector<int> P(1, -1);\n  vector<vector<int>> pp(LOG, vector<int>(1, -1));\n  vector<int> id(q + 1, -1);\n  id[0] = 0;\n  for (int i = 0; i < q; i++){\n    int t;\n    cin >> t;\n    if (t == 1){\n      id[i + 1] = N;\n      int p, a, c;\n      cin >> p >> a >> c;\n      p = id[p];\n      P.push_back(p);\n      A.push_back(a);\n      C.push_back(c);\n      int d2 = d[p] + 1;\n      d.push_back(d2);\n      pp[0].push_back(p);\n      for (int j = 0; j < LOG - 1; j++){\n        if (pp[j][N] == -1){\n          pp[j + 1].push_back(-1);\n        } else {\n          pp[j + 1].push_back(pp[j][pp[j][N]]);\n        }\n      }\n      N++;\n    }\n    if (t == 2){\n      int v, w;\n      cin >> v >> w;\n      v = id[v];\n      if (A[v] == 0){\n        cout << 0 << ' ' << 0 << endl;\n      } else {\n        int p = v;\n        for (int j = LOG - 1; j >= 0; j--){\n          int p2 = pp[j][p];\n          if (p2 != -1){\n            if (A[p2] > 0){\n              p = p2;\n            }\n          }\n        }\n        int D = d[v] - d[p];\n        int ans1 = 0;\n        long long ans2 = 0;\n        for (int j = D; j >= 0; j--){\n          int v2 = v;\n          for (int k = 0; k < LOG; k++){\n            if ((j >> k & 1) == 1){\n              v2 = pp[k][v2];\n            }\n          }\n          int a = min(A[v2], w);\n          ans1 += a;\n          ans2 += (long long) C[v2] * a;\n          w -= a;\n          A[v2] -= a;\n          if (w == 0){\n            break;\n          }\n        }\n        cout << ans1 << ' ' << ans2 << endl;\n      }\n    }\n  }\n}"
    },
