        "Default_Solution": "/**\n *    author:  tourist\n *    created: 27.12.2021 17:44:45       \n**/\n#include <bits/stdc++.h>\n\nusing namespace std;\n\nint main() {\n  ios::sync_with_stdio(false);\n  cin.tie(0);\n  int tt;\n  cin >> tt;\n  while (tt--) {\n    int n, m;\n    cin >> n >> m;\n    vector<int> x(n);\n    for (int i = 0; i < n; i++) {\n      cin >> x[i];\n    }\n    vector<string> s(n);\n    for (int i = 0; i < n; i++) {\n      cin >> s[i];\n    }\n    int ans = -1;\n    vector<int> best(m, -1);\n    for (int t = 0; t < (1 << n); t++) {\n      vector<int> c(m);\n      int cur = 0;\n      for (int i = 0; i < n; i++) {\n        int sign = (t & (1 << i)) ? 1 : -1;\n        cur -= x[i] * sign;\n        for (int j = 0; j < m; j++) {\n          if (s[i][j] == '1') {\n            c[j] += sign;\n          }\n        }\n      }\n      vector<int> order(m);\n      iota(order.begin(), order.end(), 0);\n      sort(order.begin(), order.end(), [&](int i, int j) {\n        return c[i] < c[j];\n      });\n      for (int i = 0; i < m; i++) {\n        cur += c[order[i]] * (i + 1);\n      }\n      if (cur > ans) {\n        ans = cur;\n        best = order;\n      }\n    }\n    vector<int> p(m);\n    for (int i = 0; i < m; i++) {\n      p[best[i]] = i + 1;\n    }\n    for (int i = 0; i < m; i++) {\n      if (i > 0) {\n        cout << \" \";\n      }\n      cout << p[i];\n    }\n    cout << '\n';\n  }\n  return 0;\n}\n"
