        "Default_Solution": "//#pragma GCC optimize(\"O3\")\n#include <bits/stdc++.h>\n\nusing namespace std;\n\n//defines\ntypedef long long ll;\ntypedef long double ld;\n#define TIME clock() * 1.0 / CLOCKS_PER_SEC\n#define prev _prev\n#define y0 _y0\n#define kill _kill\n\n//permanent constants\nconst ld pi = acos(-1.0);\nconst int day[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};\nconst int digarr[10] = {6, 2, 5, 5, 4, 5, 6, 3, 7, 6};\nconst int dx[4] = {0, 1, 0, -1};\nconst int dy[4] = {1, 0, -1, 0};\nconst int dxo[8] = {-1, -1, -1, 0, 1, 1, 1, 0};\nconst int dyo[8] = {-1, 0, 1, 1, 1, 0, -1, -1};\nconst int alf = 26;\nconst int dig = 10;\nconst int two = 2;\nconst int th = 3;\nconst ll prost = 239;\nconst ll btc = 30;\nconst ld eps = 1e-10;\nconst ll INF = (ll)(1e18 + 239);\nconst int BIG = (int)(1e9 + 239);\nconst int MOD = 1e9 + 7; //(int)(1e9 + 7); //998244353;\nconst ll MOD2 = (ll)MOD * (ll)MOD;\n\n//random\nmt19937 rnd(239); //(chrono::high_resolution_clock::now().time_since_epoch().count());\n\n//constants\nconst int M = (int)(6e5 + 239);\nconst int N = (int)(1e3 + 239);\nconst int L = 20;\nconst int T = (1 << 20) + 239;\nconst int B = 500;\nconst int X = 8;\n\nint ans1[M], ans2[M], n, m, a[M], pos[M];\n\nint tree[M];\n\nvoid add(int i, int x)\n{\n    for (; i < n + m; i |= i + 1)\n        tree[i] += x;\n}\n\nint gett(int i)\n{\n    int ans = 0;\n    for (; i >= 0; i = (i & (i + 1)) - 1)\n        ans += tree[i];\n    return ans;\n}\n\nint32_t main()\n{\n#ifdef ONPC\n    freopen(\"input.txt\", \"r\", stdin);\n#endif\n    ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n    cin >> n >> m;\n    for (int i = 0; i < n; i++)\n    {\n        ans1[i] = i;\n        ans2[i] = i;\n        pos[i] = i + m;\n    }\n    for (int i = 0; i < m; i++)\n    {\n        cin >> a[i];\n        a[i]--;\n        ans1[a[i]] = 0;\n    }\n    for (int i = 0; i < n; i++)\n        add(pos[i], 1);\n    for (int i = 0; i < m; i++)\n    {\n        int p = a[i];\n        ans2[p] = max(ans2[p], gett(pos[p]) - 1);\n        add(pos[p], -1);\n        pos[p] = m - i - 1;\n        add(pos[p], 1);\n    }\n    for (int i = 0; i < n; i++)\n        ans2[i] = max(ans2[i], gett(pos[i]) - 1);\n    for (int i = 0; i < n; i++)\n        cout << ans1[i] + 1 << \" \" << ans2[i] + 1 << \"\n\";\n    return 0;\n}"
