        "Default_Solution": "#include \"bits/stdc++.h\"\n#pragma GCC optimize (\"O3\")\n#pragma GCC target (\"sse4\")\n \nusing namespace std;\n \ntypedef long long ll;\ntypedef long double ld;\ntypedef complex<ld> cd;\n \ntypedef pair<int, int> pi;\ntypedef pair<ll,ll> pl;\ntypedef pair<ld,ld> pd;\n \ntypedef vector<int> vi;\ntypedef vector<ld> vd;\ntypedef vector<ll> vl;\ntypedef vector<pi> vpi;\ntypedef vector<pl> vpl;\ntypedef vector<cd> vcd;\n\ntemplate<class T> using pq = priority_queue<T>;\ntemplate<class T> using pqg = priority_queue<T, vector<T>, greater<T>>;\n \n#define FOR(i, a, b) for (int i=a; i<(b); i++)\n#define F0R(i, a) for (int i=0; i<(a); i++)\n#define FORd(i,a,b) for (int i = (b)-1; i >= a; i--)\n#define F0Rd(i,a) for (int i = (a)-1; i >= 0; i--)\n#define trav(a,x) for (auto& a : x)\n#define uid(a, b) uniform_int_distribution<int>(a, b)(rng)\n \n#define sz(x) (int)(x).size()\n#define mp make_pair\n#define pb push_back\n#define f first\n#define s second\n#define lb lower_bound\n#define ub upper_bound\n#define all(x) x.begin(), x.end()\n#define ins insert\n\ntemplate<class T> bool ckmin(T& a, const T& b) { return b < a ? a = b, 1 : 0; }\ntemplate<class T> bool ckmax(T& a, const T& b) { return a < b ? a = b, 1 : 0; }\n \nmt19937 rng(chrono::steady_clock::now().time_since_epoch().count());\n\nvoid __print(int x) {cerr << x;}\nvoid __print(long x) {cerr << x;}\nvoid __print(long long x) {cerr << x;}\nvoid __print(unsigned x) {cerr << x;}\nvoid __print(unsigned long x) {cerr << x;}\nvoid __print(unsigned long long x) {cerr << x;}\nvoid __print(float x) {cerr << x;}\nvoid __print(double x) {cerr << x;}\nvoid __print(long double x) {cerr << x;}\nvoid __print(char x) {cerr << '\\'' << x << '\\'';}\nvoid __print(const char *x) {cerr << '\\\"' << x << '\\\"';}\nvoid __print(const string &x) {cerr << '\\\"' << x << '\\\"';}\nvoid __print(bool x) {cerr << (x ? \"true\" : \"false\");}\n\ntemplate<typename T, typename V>\nvoid __print(const pair<T, V> &x) {cerr << '{'; __print(x.first); cerr << \", \"; __print(x.second); cerr << '}';}\ntemplate<typename T>\nvoid __print(const T &x) {int f = 0; cerr << '{'; for (auto &i: x) cerr << (f++ ? \", \" : \"\"), __print(i); cerr << \"}\";}\nvoid _print() {cerr << \"]\n\";}\ntemplate <typename T, typename... V>\nvoid _print(T t, V... v) {__print(t); if (sizeof...(v)) cerr << \", \"; _print(v...);}\n#ifdef DEBUG\n#define dbg(x...) cerr << \"\\e[91m\"<<__func__<<\":\"<<__LINE__<<\" [\" << #x << \"] = [\"; _print(x); cerr << \"\\e[39m\" << endl;\n#else\n#define dbg(x...)\n#endif\n\n\nconst int MOD = 998244353;\nconst char nl = '\n';\nconst int MX = 100001; \n\n\nstruct mi {\n\tll v; explicit operator ll() const { return v; }\n\tmi() { v = 0; }\n\tmi(ll _v) { \n\t\tv = (-MOD < _v && _v < MOD) ? _v : _v % MOD;\n\t\tif (v < 0) v += MOD;\n\t}\n\tfriend bool operator==(const mi& a, const mi& b) { \n\t\treturn a.v == b.v; }\n\tfriend bool operator!=(const mi& a, const mi& b) { \n\t\treturn !(a == b); }\n\tfriend bool operator<(const mi& a, const mi& b) { \n\t\treturn a.v < b.v; }\n   \n\tmi& operator+=(const mi& m) { \n\t\tif ((v += m.v) >= MOD) v -= MOD; \n\t\treturn *this; }\n\tmi& operator-=(const mi& m) { \n\t\tif ((v -= m.v) < 0) v += MOD; \n\t\treturn *this; }\n\tmi& operator*=(const mi& m) { \n\t\tv = v*m.v%MOD; return *this; }\n\tmi& operator/=(const mi& m) { return (*this) *= inv(m); }\n\tfriend mi pow(mi a, ll p) {\n\t\tmi ans = 1; assert(p >= 0);\n\t\tfor (; p; p /= 2, a *= a) if (p&1) ans *= a;\n\t\treturn ans;\n\t}\n\tfriend mi inv(const mi& a) { assert(a.v != 0); \n\t\treturn pow(a,MOD-2); }\n\t\t\n\tmi operator-() const { return mi(-v); }\n\tmi& operator++() { return *this += 1; }\n\tmi& operator--() { return *this -= 1; }\n    mi operator++(int) { mi temp; temp.v = v++; return temp; }\n    mi operator--(int) { mi temp; temp.v = v--; return temp; }\n\tfriend mi operator+(mi a, const mi& b) { return a += b; }\n\tfriend mi operator-(mi a, const mi& b) { return a -= b; }\n\tfriend mi operator*(mi a, const mi& b) { return a *= b; }\n\tfriend mi operator/(mi a, const mi& b) { return a /= b; }\n    friend ostream& operator<<(ostream& os, const mi& m) {\n        os << m.v; return os;\n    }\n    friend istream& operator>>(istream& is, mi& m) {\n        ll x; is >> x;\n        m.v = x;\n        return is;\n    }\n};\n\n\ntypedef vector<mi> vmi;\ntypedef pair<mi,mi> pmi;\ntypedef vector<pmi> vpmi;\n\nvoid __print(mi X) {\n    cout << X.v;\n}\nint K;\nmi A, H;\nmi vals[6];\nint places[6];\n\n\nmap<int, map<mi, vi>> get(vi B) {\n    int nm = (1 << (K-1)) - 1;\n    map<int, map<mi, vi>> res;\n    F0R(m, 1 << nm) {\n        int p = 0;\n        int v = K;\n        vi cur; F0R(i, sz(B)) cur.pb(i);\n        vi place(sz(B));\n        mi value = 0;\n        while (sz(cur) > 1) {\n            vi nxt;\n            F0R(i, sz(cur) / 2) {\n                if (m & (1 << p)) {\n                    nxt.pb(cur[i*2]);\n                    place[cur[i*2+1]] = places[v];\n                    value += B[cur[i*2+1]] * vals[v];\n                } else {\n                    nxt.pb(cur[i*2+1]);\n                    place[cur[i*2]] = places[v];\n                    value += B[cur[i*2]] * vals[v];\n                }\n                p++;\n            }\n            cur = nxt;\n            v--;\n        }\n        place[cur[0]] = 2;\n        value += B[cur[0]] * vals[1];\n       /* vi tst = {5, 3, 5, 2};\n        if (place == tst) {\n            dbg(cur[0],value);\n        }*/\n        res[B[cur[0]]][value] = (place);\n    }\n    return res;\n}\n\nvoid solve() {\n    cin >> K >> A >> H;\n    vals[0] = A;\n    FOR(i, 1, 6) {\n        vals[i] = pow(mi(A), (pow(mi(2), i-1) +1).v);\n    }\n    places[0] = 1; places[1] = 2; places[2] = 3; places[3] = 5; places[4] = 9;\n    places[5] = 17;\n    vi A1, A2;\n    F0R(i, 1 << (K-1)) {\n        A1.pb(i+1);\n        A2.pb(i+1+(1<<(K-1)));\n    }\n\n    map<int, map<mi, vi>> res1 = get(A1), res2 = get(A2);\n    trav(a, res1) {\n        trav(b, res2) {\n            trav(x, a.s) {\n\n                mi cur1 = x.f + a.f * vals[0] - a.f * vals[1];\n                if (b.s.count(H-cur1)) {\n                    vi ans1 = x.s, ans2 = b.s[H-cur1];\n                    ans1[a.f-1] = 1;\n                    trav(c, ans1) cout << c << \" \";\n                    trav(c, ans2) cout << c << \" \";\n                    return;\n                }\n                mi cur2 = x.f + b.f * vals[0] - b.f * vals[1];\n                /*if (x.f.v == 706382488) {\n                    dbg(cur2);\n                }*/\n               if (b.s.count(H-cur2)) {\n                    vi ans1 = x.s, ans2 = b.s[H-cur2];\n                    ans2[b.f-(1 << (K-1))-1] = 1;\n                    trav(c, ans1) cout << c << \" \";\n                    trav(c, ans2) cout << c << \" \";\n                    return;\n                }\n            }\n        }\n    }\n\n    cout << -1 << nl;\n\n\n\n\n}\n \nint main() {\n    cin.tie(0)->sync_with_stdio(0); \n    cin.exceptions(cin.failbit);\n\n    int T = 1;\n//    cin >> T;\n    while(T--) {\n        solve();\n    }\n\n\treturn 0;\n}\n\n\n"
