        "Default_Solution": "#ifdef xay5421\n#define D(...) fprintf(stderr,__VA_ARGS__)\n#else\n#define D(...) ((void)0)\n//#define NDEBUG\n#endif\n#include<bits/stdc++.h>\n//#define int long long\n#define LL long long\n#define MP make_pair\n#define PB push_back\n#define fi first\n#define se second\n#define ALL(x) (x).begin(),(x).end()\n#define SZ(x) ((int)(x).size())\n#define rep(i,a,b) for(int i=(a);i<=(b);++i)\n#define per(i,a,b) for(int i=(a);i>=(b);--i)\nusing namespace std;\ntypedef pair<int,int>PII;typedef vector<int>VI;typedef vector<PII>VII;\ntemplate<typename T>void rd(T&x){int f=0,c;while(!isdigit(c=getchar()))f^=!(c^45);x=(c&15);while(isdigit(c=getchar()))x=x*10+(c&15);if(f)x=-x;}\ntemplate<typename T>void pt(T x,int c=-1){if(x<0)putchar('-'),x=-x;if(x>9)pt(x/10);putchar(x%10+48);if(c!=-1)putchar(c);}\nconst int N=500005;\nint n,a[N],pre[N],lst[N];\nLL ans;\nint mn[N*4],cnt[N*4],tg[N*4];\nvoid upd(int k1){\n\tmn[k1]=min(mn[k1*2],mn[k1*2+1]);\n\tcnt[k1]=0;\n\tif(mn[k1]==mn[k1*2])cnt[k1]+=cnt[k1*2];\n\tif(mn[k1]==mn[k1*2+1])cnt[k1]+=cnt[k1*2+1];\n}\nvoid pst(int k1,int k2){\n\ttg[k1]+=k2,mn[k1]+=k2;\n}\nvoid psd(int k1){\n\tif(tg[k1]){\n\t\tpst(k1*2,tg[k1]);\n\t\tpst(k1*2+1,tg[k1]);\n\t\ttg[k1]=0;\n\t}\n}\nvoid bud(int k1,int k2,int k3){\n\tif(k2==k3){\n\t\tmn[k1]=N;\n\t\tcnt[k1]=1;\n\t\treturn;\n\t}\n\tint mid=(k2+k3)>>1;\n\tbud(k1*2,k2,mid),bud(k1*2+1,mid+1,k3);\n\tupd(k1);\n}\nvoid mdf(int k1,int k2,int k3,int k4,int k5,int k6){\n\tif(k2>k5||k3<k4)return;\n\tif(k4<=k2&&k3<=k5){\n\t\tpst(k1,k6);\n\t\treturn;\n\t}\n\tpsd(k1);\n\tint mid=(k2+k3)>>1;\n\tmdf(k1*2,k2,mid,k4,k5,k6),mdf(k1*2+1,mid+1,k3,k4,k5,k6);\n\tupd(k1);\n}\nsigned main(){\n#ifdef xay5421\n\tfreopen(\"a.in\",\"r\",stdin);\n#endif\n\trd(n);\n\trep(i,1,n){\n\t\trd(a[i]);\n\t\tpre[i]=lst[a[i]];\n\t\tlst[a[i]]=i;\n\t}\n\tbud(1,1,n);\n\trep(i,1,n){\n\t\tmdf(1,1,n,i,i,-N);\n\t\tint k1=pre[i];\n\t\tint k2=pre[k1];\n\t\tint k3=pre[k2];\n\t\tint k4=pre[k3];\n\t\tif(k1){\n\t\t\tmdf(1,1,n,1,k1,-1);\n\t\t}\n\t\tif(k3){\n\t\t\tmdf(1,1,n,k4+1,k3,1);\n\t\t}\n\t\tif(k2){\n\t\t\tmdf(1,1,n,k3+1,k2,-1);\n\t\t}\n\t\tmdf(1,1,n,1,i,1);\n\t\tif(mn[1]==0){\n\t\t\tans+=cnt[1];\n\t\t\tD(\"%d %d\n\",i,cnt[1]);\n\t\t}\n\t}\n\tpt(ans,'\n');\n\treturn 0;\n}\n\n"
